body.script:
  //
  /* ==========================================
   IN-POST & THEME BILINGUAL SWITCHER (UNIFIED ORCHESTRATOR)
   - Switches VI / EN content blocks
   - Parses "VI | EN" syntax in menus, widgets
   - Translates static dictionary terms
   - Saves preference to localStorage
   - Emits languageChanged event for Auto-TOC re-render
   ========================================== */
(function() {
  'use strict';

  var STORAGE_KEY = 'user_lang';

  const CORE_I18N = {
    vi: {
      searchPlaceholder: 'Tìm kiếm bài viết...',
      readingTime: 'phút đọc',
      tableOfContents: '📑 Mục Lục Bài Viết',
      previousPost: '« Bài trước',
      nextPost: 'Bài sau »',
      newerPostTitle: 'Bài viết mới hơn',
      olderPostTitle: 'Bài viết cũ hơn',
      shareBtn: 'Chia sẻ',
      shareTitle: 'Chia sẻ bài viết:',
      sharePrompt: 'Thấy bài viết hữu ích? Hãy chia sẻ cùng bạn bè:',
      copyLink: 'Sao chép liên kết',
      copyLinkBtn: '🔗 Sao chép link',
      copiedLink: '✅ Đã sao chép liên kết!',
      moreOptions: 'Thêm tùy chọn...',
      breadcrumbHome: '🏠 Trang chủ',
      relatedPosts: '📚 Bài Viết Liên Quan',
      commentsTitle: '💬 Bình Luận',
      aboutAuthor: 'Về tác giả',
      authorBioDesc: 'Chào bạn, đây là Trà Đá Blog — một góc nhỏ bình dị để tôi bày tỏ quan điểm, chia sẻ kiến thức và những trải nghiệm sống chân thực. Một điểm dừng chân để chúng ta cùng nhìn cuộc sống dưới những lăng kính thú vị hơn.',
      buyMeACoffee: '☕ Mời tôi ly cà phê',
      subscribeNewsletter: '💌 Đăng ký bản tin',
      newsletterTitle: 'Nhận bài viết mới',
      newsletterDesc: 'Nhận thông báo khi có bài viết mới qua email.',
      subscribeBtn: 'Đăng Ký',
      olderPosts: 'Cũ hơn »',
      newerPosts: '« Mới hơn',
      newsletterSubDesc: 'Đăng ký để nhận thông báo khi có bài viết mới. Không spam, chỉ nội dung chất lượng.',
      backToTop: '↑ Lên đầu trang',
      copyrightSuffix: 'Tất cả quyền được bảo lưu.',
      aiDisclosureDetails: 'Xem chi tiết',
    },
    en: {
      searchPlaceholder: 'Search articles...',
      readingTime: 'min read',
      tableOfContents: '📑 Table of Contents',
      previousPost: '« Previous Post',
      nextPost: 'Next Post »',
      newerPostTitle: 'Newer Article',
      olderPostTitle: 'Older Article',
      shareBtn: 'Share',
      shareTitle: 'Share this post:',
      sharePrompt: 'Enjoyed this article? Share it with friends:',
      copyLink: 'Copy Link',
      copyLinkBtn: '🔗 Copy link',
      copiedLink: '✅ Link copied to clipboard!',
      moreOptions: 'More options...',
      breadcrumbHome: '🏠 Home',
      relatedPosts: '📚 Related Articles',
      commentsTitle: '💬 Comments',
      aboutAuthor: 'About the author',
      authorBioDesc: 'Welcome to Trà Đá Blog — a humble little corner where I express my perspectives, share knowledge, and document authentic life experiences. A pit stop for us to look at life through more interesting lenses.',
      buyMeACoffee: '☕ Buy me a coffee',
      subscribeNewsletter: '💌 Newsletter',
      newsletterTitle: 'Newsletter',
      newsletterDesc: 'Get thoughtful articles delivered to your inbox.',
      subscribeBtn: 'Subscribe',
      olderPosts: 'Older Posts »',
      newerPosts: '« Newer Posts',
      newsletterSubDesc: 'Subscribe to get notified of new articles. No spam, only quality content.',
      backToTop: '↑ Back to top',
      copyrightSuffix: 'All rights reserved.',
      aiDisclosureDetails: 'Details',
    }
  };

  function initBilingual() {
    // Restore preferred language from localStorage
    var preferred = localStorage.getItem(STORAGE_KEY) || 'vi';
    applyLanguage(preferred, false);
  }

  function parseBilingualText(rawText, lang) {
    if (!rawText) return '';
    lang = lang || (typeof localStorage !== 'undefined' && localStorage.getItem(STORAGE_KEY)) || 'vi';
    if (rawText.includes('|')) {
      var parts = rawText.split('|').map(function(s) { return s.trim(); });
      return (lang === 'en' ? parts[1] : parts[0]) || parts[0];
    }
    return rawText.trim();
  }
  window.parseBilingualText = parseBilingualText;

  function localizeDates(lang) {
    var timeEls = document.querySelectorAll('time[datetime]');
    timeEls.forEach(function(el) {
      var iso = el.getAttribute('datetime');
      if (!iso) return;
      try {
        var d = new Date(iso);
        if (isNaN(d.getTime())) return;
        if (lang === 'en') {
          el.textContent = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
        } else {
          el.textContent = d.getDate() + ' tháng ' + (d.getMonth() + 1) + ', ' + d.getFullYear();
        }
      } catch (e) {}
    });
  }

  function applyBilingualElements(lang) {
    lang = lang || (typeof localStorage !== 'undefined' && localStorage.getItem(STORAGE_KEY)) || 'vi';
    // Bộ chọn toàn bộ các phần tử hỗ trợ cú pháp VI | EN
    // Bao gồm: data-bilingual="true", badge thẻ bài, tab chủ đề, pill timeline, breadcrumbs, footer
    const targets = document.querySelectorAll(
      '[data-bilingual="true"], [data-raw-label], .post-badge, .tab-pill, .archive-post-cat-pill, .breadcrumbs a, .breadcrumb-category-link, .footer-copyright, .footer-copyright a, .footer-bottom-nav a, .footer-links a'
    );

    targets.forEach(function(el) {
      // Bỏ qua thẻ cha .footer-copyright nếu bên trong đã có thẻ link <a> để không xoá mất link
      if (el.classList.contains('footer-copyright') && el.querySelector('a')) {
        return;
      }

      // Bỏ qua thẻ cha nếu bên trong có chứa nút bấm tương tác (tránh xoá mất nút Shuffle)
      if (el.querySelector('button, .series-shuffle-btn')) {
        var textTarget = el.querySelector('.series-title-text, .sp-title-text');
        if (textTarget) {
          var tRaw = textTarget.getAttribute('data-raw-label') || textTarget.dataset.rawText;
          if (tRaw && tRaw.includes('|')) {
            textTarget.textContent = parseBilingualText(tRaw, lang);
          }
        }
        return;
      }

      // 1. Lấy nội dung gốc chứa cú pháp VI | EN
      var raw = el.getAttribute('data-raw-label') || el.dataset.rawText;
      if (!raw) {
        // BẢO VỆ: Khước từ tự động parse nếu bên trong có chứa thẻ <script> 
        // (tránh lỗi hiển thị source code JS nếu người dùng dán mã vào data:content)
        if (el.querySelector('script, img, iframe')) {
          return;
        }
        var currentTxt = el.textContent.trim();
        if (currentTxt.includes('|')) {
          raw = currentTxt;
          el.setAttribute('data-raw-label', raw);
          el.dataset.rawText = raw;
        }
      }

      // 2. Nếu có nội dung gốc chứa dấu phân cách "|"
      if (raw && raw.includes('|')) {
        el.textContent = parseBilingualText(raw, lang);
      }
    });

    // 3. Xử lý placeholder song ngữ cho input/textarea
    var placeholders = document.querySelectorAll('[data-bilingual-placeholder]');
    placeholders.forEach(function(el) {
      var raw = el.getAttribute('data-bilingual-placeholder');
      if (raw && raw.includes('|')) {
        el.placeholder = parseBilingualText(raw, lang);
      }
    });
  }

  function applyLanguage(lang, save) {
    // 1. Update dropdown toggle text
    var flagEl = document.getElementById('current-lang-flag');
    var textEl = document.getElementById('current-lang-text');
    if (flagEl && textEl) {
      if (lang === 'en') {
        flagEl.textContent = '🇬🇧';
        textEl.textContent = 'EN';
      } else {
        flagEl.textContent = '🇻🇳';
        textEl.textContent = 'VI';
      }
    }

    // Close dropdown
    var dropdown = document.getElementById('lang-dropdown-menu');
    if (dropdown) {
      dropdown.classList.remove('show');
    }

    // 2. Toggle in-post bilingual content blocks (if bilingual blocks exist)
    var viContents = document.querySelectorAll("[data-lang='vi'], [lang='vi'], .lang-vi");
    var enContents = document.querySelectorAll("[data-lang='en'], [lang='en'], .lang-en");

    if (lang === 'en') {
      if (enContents.length > 0) {
        viContents.forEach(el => { el.style.display = 'none'; });
        enContents.forEach(el => { el.style.display = 'block'; });
      }
    } else {
      if (enContents.length > 0) {
        enContents.forEach(el => { el.style.display = 'none'; });
      }
      viContents.forEach(el => { el.style.display = 'block'; });
    }

    // 3. Apply VI | EN syntax parsing
    applyBilingualElements(lang);

    // 4. Translate static dictionary terms
    var i18nTargets = document.querySelectorAll('[data-i18n]');
    i18nTargets.forEach(el => {
      const key = el.getAttribute('data-i18n');
      if (CORE_I18N[lang] && CORE_I18N[lang][key]) {
        if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') {
          el.placeholder = CORE_I18N[lang][key];
        } else {
          el.textContent = CORE_I18N[lang][key];
        }
      }
    });

    // 5. Localize dates
    localizeDates(lang);

    // Save to localStorage
    if (save !== false) {
      try { localStorage.setItem(STORAGE_KEY, lang); } catch(e) {}
    }

    // Dispatch event to inform Auto TOC and others to update
    window.dispatchEvent(new CustomEvent('languageChanged', { detail: { lang: lang } }));
  }

  // Global function called from inline onclick
  window.setLanguage = function(lang) {
    applyLanguage(lang, true);
  };

  // Legacy support for switchLanguage
  window.switchLanguage = window.setLanguage;
  window.applyBilingualElements = applyBilingualElements;

  // Close dropdown when clicking outside
  document.addEventListener('click', function(event) {
    var toggleBtn = document.getElementById('lang-toggle-btn');
    var dropdown = document.getElementById('lang-dropdown-menu');
    if (toggleBtn && dropdown) {
      if (!toggleBtn.contains(event.target) && !dropdown.contains(event.target)) {
        dropdown.classList.remove('show');
      }
    }
  });

  document.addEventListener('DOMContentLoaded', initBilingual);
})();


/* ==========================================
   MOBILE NAVIGATION - Hamburger + Drawer
   - Auto-syncs menu items from Desktop LinkList
   ========================================== */
(function() {
  'use strict';

  var hamburgerBtn = null;
  var navDrawer = null;
  var navDrawerBackdrop = null;
  var navDrawerClose = null;

  function ensureDesktopMenu() {
    var navWrapper = document.querySelector('.nav-menu-wrapper');
    var navMenu = document.querySelector('.nav-menu');
    if (!navMenu || !navMenu.children.length) {
      var headerInner = document.querySelector('.site-header .header-inner');
      if (headerInner) {
        if (!navWrapper) {
          navWrapper = document.createElement('nav');
          navWrapper.className = 'nav-menu-wrapper';
          navWrapper.id = 'nav-menu-wrapper';
          navWrapper.setAttribute('aria-label', 'Menu chính');
          var logoSection = document.querySelector('.site-header .brand-logo-section, .site-header .brand-logo');
          if (logoSection && logoSection.nextSibling) {
            headerInner.insertBefore(navWrapper, logoSection.nextSibling);
          } else {
            var headerActions = document.querySelector('.site-header .header-actions');
            if (headerActions) {
              headerInner.insertBefore(navWrapper, headerActions);
            } else {
              headerInner.appendChild(navWrapper);
            }
          }
        }
        navWrapper.innerHTML = '<ul class="nav-menu">' +
          '<li><a class="active" href="/" data-bilingual="true">Trang Chủ | Home</a></li>' +
          '<li><a href="/p/muc-luc.html" data-bilingual="true">Dòng Thời Gian | Timeline</a></li>' +
        '</ul>';
        // Kích hoạt dịch song ngữ cho menu vừa tạo nếu bilingual.js đã tải
        if (window.applyBilingualElements) {
          window.applyBilingualElements(localStorage.getItem('user_lang') || 'vi');
        }
      }
    }
  }

  function sanitizeLegacyMenu() {
    var menu = document.querySelector('.nav-menu');
    if (menu) {
      var text = menu.textContent;
      if (text.includes('Disclaimer') || text.includes('Privacy') || text.includes('Faq') || text.includes('Term')) {
        menu.innerHTML = '<li><a class="active" href="/" id="nav-home-btn" data-bilingual="true">Trang Chủ | Home</a></li>' +
          '<li><a href="/p/muc-luc.html" id="nav-timeline-btn" data-bilingual="true">Dòng Thời Gian | Timeline</a></li>';
        if (window.applyBilingualElements) {
          window.applyBilingualElements(localStorage.getItem('user_lang') || 'vi');
        }
      }
    }
  }

  function ensureCategoryTabs() {
    var catBar = document.getElementById('category-tabs-bar') || document.querySelector('.category-tabs-bar');
    var catSection = document.getElementById('category-tabs-section');

    if (!catBar && catSection) {
      catBar = document.createElement('nav');
      catBar.className = 'category-tabs-bar';
      catBar.id = 'category-tabs-bar';
      catBar.setAttribute('aria-label', 'Lọc theo chủ đề');
      catBar.innerHTML = '<a class="tab-pill active" href="/" data-bilingual="true" data-raw-label="✦ Tất cả | All">✦ Tất cả | All</a>';
      catSection.appendChild(catBar);
    }
    if (!catBar) return;

    var currentLang = (typeof localStorage !== 'undefined' && localStorage.getItem('user_lang')) || 'vi';

    // Helper: Thêm hoặc chuẩn hóa một tab pill
    function addOrUpdateTab(rawTerm, url) {
      var term = (rawTerm || '').trim();
      if (!term) return;
      // Bỏ qua nhãn tính năng (@...), nhãn AI (ai:...), và nhãn Series (series:...)
      if (term.startsWith('@') || term.toLowerCase().startsWith('ai:') || term.toUpperCase().startsWith('AI-') || term.toLowerCase().startsWith('series:')) {
        return;
      }

      var targetHref = url || ('/search/label/' + encodeURIComponent(term));

      // Kiểm tra xem đã có tab với nhãn này chưa
      var existingPill = null;
      catBar.querySelectorAll('.tab-pill').forEach(function(p) {
        var pRaw = p.getAttribute('data-raw-label') || p.getAttribute('data-label') || p.textContent.trim();
        var pHref = p.getAttribute('href') || '';
        if (pRaw.toLowerCase() === term.toLowerCase() || 
            (pHref && targetHref && pHref.split('/search/label/')[1] === targetHref.split('/search/label/')[1])) {
          existingPill = p;
        }
      });

      var displayText = window.parseBilingualText ? window.parseBilingualText(term, currentLang) : term.split('|')[0].trim();

      if (existingPill) {
        existingPill.setAttribute('data-raw-label', term);
        existingPill.setAttribute('data-bilingual', 'true');
        existingPill.textContent = displayText;
      } else {
        var a = document.createElement('a');
        a.className = 'tab-pill';
        a.href = targetHref;
        a.setAttribute('data-raw-label', term);
        a.setAttribute('data-bilingual', 'true');
        a.textContent = displayText;
        catBar.appendChild(a);
      }
    }

    // 1. Dọn sạch các nhãn tính năng đặc biệt (@...) và nhãn AI có sẵn từ server
    var existingPills = Array.from(catBar.querySelectorAll('.tab-pill'));
    var allPill = null;

    existingPills.forEach(function(pill) {
      var href = pill.getAttribute('href') || '';
      var label = (pill.getAttribute('data-raw-label') || pill.getAttribute('data-label') || pill.textContent || '').trim();

      if (href === '/' || href === window.location.origin + '/' || label.startsWith('✦')) {
        allPill = pill;
        pill.setAttribute('data-raw-label', '✦ Tất cả | All');
        pill.setAttribute('data-bilingual', 'true');
        pill.textContent = window.parseBilingualText ? window.parseBilingualText('✦ Tất cả | All', currentLang) : '✦ Tất cả';
        return;
      }

      if (label.startsWith('@') || label.toLowerCase().startsWith('ai:') || label.toUpperCase().startsWith('AI-') || label.toLowerCase().startsWith('series:')) {
        pill.remove();
        return;
      }

      pill.setAttribute('data-raw-label', label);
      pill.setAttribute('data-bilingual', 'true');
      pill.textContent = window.parseBilingualText ? window.parseBilingualText(label, currentLang) : label.split('|')[0].trim();
    });

    if (!allPill) {
      allPill = document.createElement('a');
      allPill.className = 'tab-pill active';
      allPill.href = '/';
      allPill.setAttribute('data-raw-label', '✦ Tất cả | All');
      allPill.setAttribute('data-bilingual', 'true');
      allPill.textContent = window.parseBilingualText ? window.parseBilingualText('✦ Tất cả | All', currentLang) : '✦ Tất cả';
      catBar.insertBefore(allPill, catBar.firstChild);
    }

    // 2. Thu thập nhãn tức thì từ các thẻ bài viết đang có trên trang (0ms lag, không phụ thuộc API)
    document.querySelectorAll('.post-raw-label').forEach(function(lblEl) {
      var name = lblEl.textContent.trim();
      var url = lblEl.getAttribute('data-url');
      addOrUpdateTab(name, url);
    });

    // 3. Nhận diện và gán class active cho tab tương ứng với URL hiện tại
    function updateActivePill() {
      var currentPath = window.location.pathname;
      var activeFound = false;
      if (currentPath.indexOf('/search/label/') !== -1) {
        var rawLabel = currentPath.split('/search/label/')[1].split('/')[0].split('?')[0];
        var currentLabel = decodeURIComponent(rawLabel).toLowerCase();
        catBar.querySelectorAll('.tab-pill').forEach(function(pill) {
          var pillHref = pill.getAttribute('href') || '';
          if (pillHref.indexOf('/search/label/') !== -1) {
            var pillRawLabel = pillHref.split('/search/label/')[1].split('/')[0].split('?')[0];
            var pillLabel = decodeURIComponent(pillRawLabel).toLowerCase();
            if (pillLabel === currentLabel) {
              pill.classList.add('active');
              activeFound = true;
            } else {
              pill.classList.remove('active');
            }
          } else {
            pill.classList.remove('active');
          }
        });
      }
      if (allPill) {
        if (!activeFound && (currentPath === '/' || currentPath === '' || currentPath.indexOf('/search') === -1)) {
          allPill.classList.add('active');
        } else if (activeFound || currentPath.indexOf('/search') !== -1) {
          if (!activeFound) allPill.classList.remove('active');
        }
      }
    }

    updateActivePill();

    // 4. Đồng bộ thêm toàn bộ nhãn từ Blogger Feed API (quét cả feed.category và feed.entry[i].category)
    fetch('/feeds/posts/summary?alt=json&max-results=150')
      .then(function(res) {
        if (!res.ok) throw new Error('Network error');
        return res.json();
      })
      .then(function(data) {
        if (!data || !data.feed) return;
        var categories = [];

        // Quét feed-level categories
        if (data.feed.category && Array.isArray(data.feed.category)) {
          data.feed.category.forEach(function(c) {
            if (c && c.term) categories.push(c.term);
          });
        }
        // Quét entry-level categories (từng bài viết)
        if (data.feed.entry && Array.isArray(data.feed.entry)) {
          data.feed.entry.forEach(function(entry) {
            if (entry.category && Array.isArray(entry.category)) {
              entry.category.forEach(function(c) {
                if (c && c.term) categories.push(c.term);
              });
            }
          });
        }

        // Đồng thời dự phòng trích xuất tóm tắt bài viết nếu thẻ bài viết chưa có snippet
        if (data.feed.entry && Array.isArray(data.feed.entry)) {
          data.feed.entry.forEach(function(entry) {
            var postTitle = (entry.title && entry.title.$t) || '';
            var summary = (entry.summary && entry.summary.$t) || '';
            if (!summary && entry.content && entry.content.$t) summary = entry.content.$t;
            if (!summary) return;

            document.querySelectorAll('.post-card').forEach(function(card) {
              var cardTitle = card.querySelector('.post-card-title');
              var cardSnippet = card.querySelector('.post-card-snippet');
              if (cardTitle && cardSnippet && !cardSnippet.textContent.trim()) {
                if (cardTitle.textContent.trim().toLowerCase() === postTitle.trim().toLowerCase()) {
                  var plain = summary.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();
                  if (plain.length > 160) {
                    var cutIdx = plain.lastIndexOf(' ', 160);
                    if (cutIdx === -1 || cutIdx < 100) cutIdx = 160;
                    plain = plain.substring(0, cutIdx) + '...';
                  }
                  cardSnippet.textContent = plain;
                }
              }
            });
          });
        }

        var addedCount = 0;
        categories.forEach(function(term) {
          addOrUpdateTab(term);
          addedCount++;
        });

        if (addedCount > 0) {
          updateActivePill();
          if (window.applyBilingualElements) {
            window.applyBilingualElements(currentLang);
          }
        }
      })
      .catch(function(err) {
        console.log('[CategoryTabs] Feed fetch bypassed:', err.message);
      });

    if (window.applyBilingualElements) {
      window.applyBilingualElements(currentLang);
    }
  }

  function formatDropdownMenus() {
    var menu = document.getElementById('nav-desktop-menu');
    if (!menu) return;
    var items = Array.from(menu.children);
    var currentParent = null;
    var currentDropdown = null;

    items.forEach(function(li) {
      var a = li.querySelector('a');
      if (!a) return;
      var text = a.textContent.trim();
      if ((text.startsWith('_') || text.startsWith('-')) && currentParent) {
        a.textContent = text.substring(1).trim();
        if (!currentDropdown) {
          currentParent.classList.add('has-dropdown');
          currentDropdown = document.createElement('ul');
          currentDropdown.className = 'dropdown-menu';
          currentParent.appendChild(currentDropdown);
        }
        currentDropdown.appendChild(li);
      } else {
        currentParent = li;
        currentDropdown = null;
      }
    });
  }

  function syncDrawerMenu() {
    ensureDesktopMenu();
    formatDropdownMenus();
    var desktopMenu = document.querySelector('.nav-menu');
    var drawerMenu = document.querySelector('.nav-drawer-menu');
    if (desktopMenu && drawerMenu && !drawerMenu.children.length) {
      drawerMenu.innerHTML = desktopMenu.innerHTML;
    }
  }

  function syncDrawerLogo() {
    var headerLogoImg = document.querySelector('.site-header .brand-logo img.brand-logo-img');
    var drawerLogo = document.querySelector('.nav-drawer-header .brand-logo');
    if (headerLogoImg && drawerLogo) {
      drawerLogo.innerHTML = headerLogoImg.outerHTML;
    }
  }

  function initMobileNav() {
    hamburgerBtn = document.getElementById('hamburger-btn');
    navDrawer = document.getElementById('nav-drawer');
    navDrawerBackdrop = document.getElementById('nav-drawer-backdrop');
    navDrawerClose = document.getElementById('nav-drawer-close');

    ensureDesktopMenu();
    sanitizeLegacyMenu();
    ensureCategoryTabs();
    syncDrawerMenu();
    syncDrawerLogo();

    if (!hamburgerBtn || !navDrawer) return;

    hamburgerBtn.addEventListener('click', openDrawer);
    if (navDrawerClose) navDrawerClose.addEventListener('click', closeDrawer);
    if (navDrawerBackdrop) navDrawerBackdrop.addEventListener('click', closeDrawer);

    // Close on Escape key
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') closeDrawer();
    });
  }

  function openDrawer() {
    if (!navDrawer) return;
    navDrawer.classList.add('is-open');
    if (navDrawerBackdrop) navDrawerBackdrop.classList.add('is-open');
    if (hamburgerBtn) hamburgerBtn.classList.add('is-open');
    document.body.style.overflow = 'hidden';
  }

  function closeDrawer() {
    if (!navDrawer) return;
    navDrawer.classList.remove('is-open');
    if (navDrawerBackdrop) navDrawerBackdrop.classList.remove('is-open');
    if (hamburgerBtn) hamburgerBtn.classList.remove('is-open');
    document.body.style.overflow = '';
  }

  // Close drawer on window resize to desktop
  window.addEventListener('resize', function() {
    if (window.innerWidth > 768) closeDrawer();
  });

  document.addEventListener('DOMContentLoaded', initMobileNav);
})();


/* ==========================================
   SEARCH MODAL
   ========================================== */
(function() {
  'use strict';

  var searchOverlay = null;
  var searchInput = null;
  var searchOpenBtn = null;
  var searchCloseBtn = null;
  var searchForm = null;

  function initSearchModal() {
    searchOverlay = document.getElementById('search-modal-overlay');
    searchInput = document.getElementById('search-input');
    searchOpenBtn = document.getElementById('search-open-btn');
    searchCloseBtn = document.getElementById('search-close-btn');
    searchForm = document.getElementById('search-form');

    if (!searchOverlay) return;

    if (searchOpenBtn) {
      searchOpenBtn.addEventListener('click', openSearch);
    }
    if (searchCloseBtn) {
      searchCloseBtn.addEventListener('click', closeSearch);
    }
    // Close on backdrop click
    searchOverlay.addEventListener('click', function(e) {
      if (e.target === searchOverlay) closeSearch();
    });
    // Close on Escape
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') closeSearch();
    });
    // Handle form submit → Blogger search
    if (searchForm) {
      searchForm.addEventListener('submit', function(e) {
        e.preventDefault();
        var query = searchInput ? searchInput.value.trim() : '';
        if (query) {
          window.location.href = '/search?q=' + encodeURIComponent(query);
        }
      });
    }
  }

  function openSearch() {
    if (!searchOverlay) return;
    searchOverlay.classList.add('is-open');
    document.body.style.overflow = 'hidden';
    // Focus input after animation
    setTimeout(function() {
      if (searchInput) searchInput.focus();
    }, 200);
  }

  function closeSearch() {
    if (!searchOverlay) return;
    searchOverlay.classList.remove('is-open');
    document.body.style.overflow = '';
  }

  document.addEventListener('DOMContentLoaded', initSearchModal);
})();


/* ==========================================================================
   SUBWAY METRO TIMELINE ARCHIVE — v5.0
   Đặc tả: specs/SUBWAY_TIMELINE_ARCHIVE_SPECIFICATION.md (FEAT-SUBWAY-TIMELINE-ARCHIVE-V5)
   - Tự động nhận diện trang tĩnh /p/muc-luc.html hoặc container #editorial-archive-app
   - Dòng thời gian hợp nhất: Hiển thị cả bài viết thường & bài ghi chép độc quyền @
   - Hình tượng Bản đồ Tàu điện ngầm (Subway Metro Map) với Root Node, Main Track,
     Year Stations, Year Sub-tracks và Post Leaves rẽ nhánh
   - Hệ thống lọc đa tầng: Banner Category Tabs + Search + Popover Bộ lọc nâng cao (@, định dạng, AI)
   - Thích ứng di động (Mobile Bottom Sheet) + Dark Mode + Song ngữ VI | EN
   ========================================================================== */

(function () {
  'use strict';

  var CACHE_KEY = 'blogger_subway_archive_v5';
  var CACHE_TTL = 3 * 60 * 1000; // 3 phút

  var allPosts = [];
  var filterState = {
    searchQuery: '',        // Từ input search
    bannerCategory: 'all',  // Từ tabs dưới banner
    selectedLabel: 'all'    // 'all' | nhãn thường | nhãn @ (@Quote, @Điểm tin, @Tiêu điểm...)
  };

  var expandedYears = {}; // year -> boolean
  var searchDebounceTimer = null;
  var isAppMounted = false;
  var isPopoverOpen = false;

  // ── Helper: Loại bỏ dấu tiếng Việt ──
  function removeVietnameseDiacritics(str) {
    if (!str) return '';
    return str
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/đ/g, 'd')
      .replace(/Đ/g, 'D')
      .toLowerCase()
      .trim();
  }

  // ── Helper: Format ngày DD/MM từ chuỗi ISO ──
  function formatDateStr(isoStr) {
    if (!isoStr) return '';
    var d = new Date(isoStr);
    if (isNaN(d.getTime())) return '';
    var dd = String(d.getDate()).padStart(2, '0');
    var mm = String(d.getMonth() + 1).padStart(2, '0');
    return dd + '/' + mm;
  }

  // ── Helper: Lấy năm YYYY từ chuỗi ISO ──
  function getYearFromDate(isoStr) {
    if (!isoStr) return new Date().getFullYear();
    var d = new Date(isoStr);
    return isNaN(d.getTime()) ? new Date().getFullYear() : d.getFullYear();
  }

  // ── Helper: Escape HTML ──
  function escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }

  // ── Helper: Escape Attribute ──
  function escapeAttr(str) {
    return escapeHtml(str);
  }

  // ── Kiểm tra xem hiện tại có phải trang Mục Lục hay không ──
  function isArchivePage() {
    var pathname = window.location.pathname.toLowerCase();
    var href = window.location.href.toLowerCase();
    var container = document.getElementById('editorial-archive-app');
    var isContainerVisible = container && (
      container.offsetParent !== null ||
      !container.closest('#archive-page-wrapper') ||
      container.closest('#archive-page-wrapper').style.display !== 'none'
    );

    return (
      Boolean(isContainerVisible) ||
      pathname.endsWith('/p/muc-luc.html') ||
      pathname.endsWith('/p/archive.html') ||
      pathname.endsWith('/p/dong-thoi-gian.html') ||
      href.indexOf('/p/muc-luc.html') !== -1 ||
      href.indexOf('/p/archive.html') !== -1 ||
      href.indexOf('/p/dong-thoi-gian.html') !== -1 ||
      window.location.hash === '#archive'
    );
  }

  // ── Trích xuất link alternate từ Blogger feed entry ──
  function extractAlternateLink(entry) {
    if (!entry || !entry.link) return '#';
    var alt = entry.link.find(function (l) { return l.rel === 'alternate'; });
    return alt ? alt.href : '#';
  }

  // ── Phân tích Blogger JSON Feed Entry (Mục 5.1 Spec) ──
  function parseEntry(entry) {
    var rawLabels = (entry.category || []).map(function (c) { return (c.term || '').trim(); }).filter(Boolean);

    var normalLabels = [];
    var featureLabels = [];
    var aiTypeContent = null;
    var aiTypeProduct = null;
    var priority = ['ai:generated', 'ai:contributed', 'ai:assisted', 'ai:translated'];
    var seriesName = null;

    rawLabels.forEach(function (lbl) {
      var lower = lbl.toLowerCase();
      if (lbl.startsWith('@')) {
        featureLabels.push(lbl);
      } else if (lower.startsWith('ai:') || lower.startsWith('ai-')) {
        var t = lower.replace(/-/g, ':');
        if (t === 'ai:product') {
          aiTypeProduct = t;
        } else {
          if (priority.indexOf(t) !== -1) {
            if (!aiTypeContent || priority.indexOf(t) < priority.indexOf(aiTypeContent)) {
              aiTypeContent = t;
            }
          }
        }
      } else if (lower.startsWith('series:')) {
        if (!seriesName) seriesName = lbl.replace(/^series:\s*/i, '').trim();
      } else {
        normalLabels.push(lbl);
      }
    });

    var isFeatureOnly = rawLabels.length > 0 && normalLabels.length === 0 && !seriesName && featureLabels.length > 0;
    var postType = (isFeatureOnly || featureLabels.length > 0) ? 'feature' : 'regular';
    var primaryCategory = normalLabels.length > 0 ? normalLabels[0] : (seriesName || (featureLabels.length > 0 ? featureLabels[0] : 'Chưa phân loại'));

    var publishedStr = (entry.published && entry.published.$t) || '';
    var year = getYearFromDate(publishedStr);
    var dateStr = formatDateStr(publishedStr);
    var timestamp = publishedStr ? new Date(publishedStr).getTime() : 0;

    var aiTypeArr = [];
    if (aiTypeContent) aiTypeArr.push(aiTypeContent);
    if (aiTypeProduct) aiTypeArr.push(aiTypeProduct);
    var aiType = aiTypeArr.length > 0 ? aiTypeArr.join(',') : null;

    return {
      id: entry.id.$t,
      title: entry.title ? entry.title.$t : 'Bài viết không có tiêu đề',
      url: extractAlternateLink(entry),
      published: publishedStr,
      year: year,
      dateStr: dateStr,
      timestamp: timestamp,
      category: primaryCategory,
      normalLabels: normalLabels,
      featureLabels: featureLabels,
      postType: postType, // 'regular' | 'feature'
      aiType: aiType,
      seriesName: seriesName
    };
  }

  // ── Tải dữ liệu bài viết (Cache -> API -> Mock Data) ──
  function loadArchiveData(callback) {
    var isPreviewOrLocal =
      window.location.protocol === 'file:' ||
      window.location.hostname === 'localhost' ||
      window.location.hostname === '127.0.0.1';

    // Khi chạy trên môi trường preview local: Luôn xóa cache cũ và tải mock data mới nhất
    if (isPreviewOrLocal) {
      try {
        sessionStorage.removeItem(CACHE_KEY);
      } catch (e) {}
      useFallbackData(callback);
      return;
    }

    // 1. Kiểm tra sessionStorage Cache (chỉ áp dụng trên production Blogger)
    try {
      var cached = sessionStorage.getItem(CACHE_KEY);
      if (cached) {
        var parsed = JSON.parse(cached);
        if (parsed && parsed.ts && (Date.now() - parsed.ts < CACHE_TTL) && Array.isArray(parsed.posts) && parsed.posts.length > 0) {
          allPosts = parsed.posts;
          if (callback) callback(allPosts);
          return;
        } else {
          sessionStorage.removeItem(CACHE_KEY);
        }
      }
    } catch (e) {
      console.warn('[SubwayTimeline] Cache read error:', e);
    }

    var feedUrl = '/feeds/posts/summary?alt=json&max-results=500&_cb=' + Date.now();
    if (!isPreviewOrLocal) {
      fetch(feedUrl, { cache: 'no-cache' })
        .then(function (res) {
          if (!res.ok) throw new Error('Feed fetch failed: ' + res.status);
          return res.json();
        })
        .then(function (data) {
          var entries = (data.feed && data.feed.entry) || [];
          var posts = entries.map(parseEntry);

          // Sắp xếp giảm dần theo thời gian
          posts.sort(function (a, b) { return b.timestamp - a.timestamp; });
          allPosts = posts;

          try {
            sessionStorage.setItem(CACHE_KEY, JSON.stringify({
              ts: Date.now(),
              posts: posts
            }));
          } catch (e) {}

          if (callback) callback(allPosts);
        })
        .catch(function (err) {
          console.warn('[SubwayTimeline] Feed API failed, using fallback:', err);
          useFallbackData(callback);
        });
    } else {
      useFallbackData(callback);
    }
  }

  // ── Fallback dữ liệu mock khi chạy local preview ──
  function useFallbackData(callback) {
    if (window.__TIMELINE_MOCK_POSTS__ && window.__TIMELINE_MOCK_POSTS__.length > 0) {
      allPosts = window.__TIMELINE_MOCK_POSTS__.map(function (p) {
        var featLabels = Array.isArray(p.featureLabels) ? p.featureLabels.slice() : [];
        var normLabels = Array.isArray(p.normalLabels) ? p.normalLabels.slice() : [];
        var cat = p.category || '';

        if (cat.startsWith('@') && featLabels.indexOf(cat) === -1) {
          featLabels.push(cat);
        } else if (cat && !cat.startsWith('@') && normLabels.length === 0) {
          normLabels.push(cat);
        }

        var isFeat = featLabels.length > 0 || p.postType === 'feature';
        var primaryCat = normLabels.length > 0 ? normLabels[0] : (featLabels.length > 0 ? featLabels[0] : (cat || 'Chưa phân loại'));

        return {
          title: p.title || 'Bài viết mẫu',
          url: p.url || '#',
          year: p.year || new Date().getFullYear(),
          dateStr: p.dateStr || '15/08',
          category: primaryCat,
          normalLabels: normLabels,
          featureLabels: featLabels,
          postType: isFeat ? 'feature' : 'regular',
          aiType: p.aiType || null,
          timestamp: p.timestamp || Date.now()
        };
      });
    } else {
      allPosts = [];
    }

    allPosts.sort(function (a, b) { return b.timestamp - a.timestamp; });
    if (callback) callback(allPosts);
  }

  // ── Đọc URL Query Parameters (?q=, ?cat=, ?label=, ?year=) ──
  function parseUrlParams() {
    var params = new URLSearchParams(window.location.search);
    var q = params.get('q');
    var cat = params.get('cat');
    var lbl = params.get('label') || params.get('feature');
    var yr = params.get('year');

    if (q) filterState.searchQuery = q.trim();
    if (cat) filterState.bannerCategory = cat.trim();
    if (lbl) filterState.selectedLabel = lbl.trim();

    if (yr) {
      var yNum = parseInt(yr, 10);
      if (!isNaN(yNum)) {
        expandedYears = {};
        expandedYears[yNum] = true;
      }
    }
  }

  // ── Đồng bộ URL Query Parameters không reload trang ──
  function syncUrlParams() {
    try {
      var url = new URL(window.location.href);
      if (filterState.searchQuery) url.searchParams.set('q', filterState.searchQuery);
      else url.searchParams.delete('q');

      if (filterState.bannerCategory && filterState.bannerCategory !== 'all') {
        url.searchParams.set('cat', filterState.bannerCategory);
      } else {
        url.searchParams.delete('cat');
      }

      if (filterState.selectedLabel && filterState.selectedLabel !== 'all') {
        url.searchParams.set('label', filterState.selectedLabel);
      } else {
        url.searchParams.delete('label');
        url.searchParams.delete('feature');
      }

      url.searchParams.delete('type');
      url.searchParams.delete('ai');

      window.history.replaceState({}, '', url.toString());
    } catch (e) {}
  }

  // ── Kiểm tra khớp chuyên mục (hỗ trợ song ngữ VI | EN) ──
  function isCategoryMatch(postCat, targetCat) {
    if (!targetCat || targetCat === 'all') return true;
    if (!postCat) return false;

    var pLower = postCat.toLowerCase().trim();
    var tLower = targetCat.toLowerCase().trim();

    if (pLower === tLower) return true;

    var pParts = pLower.split('|').map(function (s) { return s.trim(); });
    var tParts = tLower.split('|').map(function (s) { return s.trim(); });

    for (var i = 0; i < pParts.length; i++) {
      for (var j = 0; j < tParts.length; j++) {
        if (pParts[i] && tParts[j]) {
          if (pParts[i] === tParts[j] || pParts[i].indexOf(tParts[j]) !== -1 || tParts[j].indexOf(pParts[i]) !== -1) {
            return true;
          }
        }
      }
    }
    return false;
  }

  // ── Thu thập toàn bộ các nhãn: nhãn @ và nhãn chuyên mục thường ──
  function getAllLabels() {
    var regularMap = {};
    var featureMap = {};

    allPosts.forEach(function (p) {
      (p.normalLabels || []).forEach(function (lbl) {
        if (lbl.startsWith('@')) {
          featureMap[lbl] = (featureMap[lbl] || 0) + 1;
        } else {
          regularMap[lbl] = (regularMap[lbl] || 0) + 1;
        }
      });
      if (p.category) {
        if (p.category.startsWith('@')) {
          featureMap[p.category] = (featureMap[p.category] || 0) + 1;
        } else {
          regularMap[p.category] = (regularMap[p.category] || 0) + 1;
        }
      }
      (p.featureLabels || []).forEach(function (lbl) {
        featureMap[lbl] = (featureMap[lbl] || 0) + 1;
      });
    });

    // Luôn đảm bảo các nhãn @ tiêu chuẩn có mặt
    ['@Quote', '@Điểm tin', '@Tiêu điểm'].forEach(function (sl) {
      if (featureMap[sl] === undefined) featureMap[sl] = 0;
    });

    var regularList = Object.keys(regularMap).sort(function (a, b) {
      return (regularMap[b] || 0) - (regularMap[a] || 0);
    });

    var featureList = Object.keys(featureMap).sort(function (a, b) {
      return (featureMap[b] || 0) - (featureMap[a] || 0);
    });

    return {
      regular: regularList,
      feature: featureList
    };
  }

  // ── Lọc danh sách bài viết theo filterState ──
  function filterPosts() {
    var qRaw = filterState.searchQuery.toLowerCase().trim();
    var qNorm = removeVietnameseDiacritics(filterState.searchQuery);

    return allPosts.filter(function (post) {
      // 1. Lọc theo Banner Category (dưới hero cover)
      if (filterState.bannerCategory !== 'all') {
        var hasMatchingNormalLabel = (post.normalLabels || []).some(function (lbl) {
          return isCategoryMatch(lbl, filterState.bannerCategory);
        });
        var matchMainCategory = isCategoryMatch(post.category, filterState.bannerCategory);
        if (!hasMatchingNormalLabel && !matchMainCategory) {
          return false;
        }
      }

      // 2. Lọc theo nhãn được chọn (Regular hoặc @ Feature)
      if (filterState.selectedLabel && filterState.selectedLabel !== 'all') {
        var targetLbl = filterState.selectedLabel.toLowerCase();
        var allPostLabels = (post.featureLabels || [])
          .concat(post.normalLabels || [])
          .concat([post.category || ''])
          .map(function (s) { return s.toLowerCase(); });

        var matchSelected = allPostLabels.some(function (lbl) {
          return isCategoryMatch(lbl, targetLbl);
        });
        if (!matchSelected) return false;
      }

      // 3. Lọc theo từ khóa tìm kiếm tức thì (Search Query)
      if (qRaw) {
        var tRaw = (post.title || '').toLowerCase();
        var tNorm = removeVietnameseDiacritics(post.title || '');
        var cNorm = removeVietnameseDiacritics(post.category || '');
        var yStr = String(post.year);
        var dStr = post.dateStr || '';

        var matchTitle = tRaw.indexOf(qRaw) !== -1 || tNorm.indexOf(qNorm) !== -1;
        var matchCat = cNorm.indexOf(qNorm) !== -1;
        var matchYear = yStr.indexOf(qRaw) !== -1;
        var matchDate = dStr.indexOf(qRaw) !== -1;

        var matchLabels = (post.featureLabels || []).concat(post.normalLabels || []).some(function (l) {
          return l.toLowerCase().indexOf(qRaw) !== -1 || removeVietnameseDiacritics(l).indexOf(qNorm) !== -1;
        });

        if (!matchTitle && !matchCat && !matchYear && !matchDate && !matchLabels) {
          return false;
        }
      }

      return true;
    });
  }

  // ── Nhóm bài viết theo Năm ──
  function groupPostsByYear(posts) {
    var groups = {};
    posts.forEach(function (p) {
      var yr = p.year || new Date().getFullYear();
      if (!groups[yr]) groups[yr] = [];
      groups[yr].push(p);
    });

    var years = Object.keys(groups).map(Number);
    years.sort(function (a, b) { return b - a; });

    return years.map(function (yr) {
      return {
        year: yr,
        posts: groups[yr]
      };
    });
  }

  // ── Kiểm tra xem có bộ lọc nâng cao nào đang active không ──
  function hasActiveAdvancedFilter() {
    return filterState.selectedLabel && filterState.selectedLabel !== 'all';
  }

  // ── Cập nhật trạng thái nút icon filter trong Search bar ──
  function updateFilterTriggerState(container) {
    var triggerBtn = container.querySelector('#archive-filter-trigger-btn');
    var dot = container.querySelector('#archive-filter-dot');
    if (!triggerBtn) return;

    var isActive = hasActiveAdvancedFilter();
    triggerBtn.classList.toggle('is-active', isActive);
    if (dot) {
      dot.style.display = isActive ? 'block' : 'none';
    }
  }

  // ── Cập nhật trạng thái active của các tab chuyên mục dưới banner ──
  function updateActiveCategoryTabs() {
    var tabs = document.querySelectorAll('.category-tabs-bar .tab-pill, #category-tabs-bar .tab-pill');
    tabs.forEach(function (t) {
      var href = t.getAttribute('href') || '';
      var raw = (t.getAttribute('data-raw-label') || t.getAttribute('data-label') || t.textContent || '').trim();
      var clean = raw.replace(/^✦\s*/, '').trim();
      var isAll = href === '/' || href === (window.location.origin + '/') ||
                  clean.toLowerCase().indexOf('tất cả') !== -1 ||
                  clean.toLowerCase() === 'all';

      if (filterState.bannerCategory === 'all') {
        t.classList.toggle('active', isAll);
      } else {
        t.classList.toggle('active', isCategoryMatch(clean, filterState.bannerCategory));
      }
    });
  }

  // ── Render Popover Bộ Lọc Nhãn Bài Viết (Danh sách thống nhất: Regular trước, Feature sau, cùng màu, không icon) ──
  function renderFilterPopoverContent(container) {
    var popover = container.querySelector('#archive-filter-popover');
    if (!popover) return;

    var labels = getAllLabels();
    var curSelected = (filterState.selectedLabel || 'all').toLowerCase();

    var pillsContainer = popover.querySelector('#filter-pills-list') ||
                         popover.querySelector('#filter-pills-regular') ||
                         popover.querySelector('.filter-popover-pills');
    if (!pillsContainer) return;

    var html = '';

    var lang = (typeof localStorage !== 'undefined' && localStorage.getItem('user_lang')) || 'vi';

    // 1. "Tất cả" ở vị trí đầu tiên
    var isAllActive = curSelected === 'all';
    var allRaw = 'Tất cả | All';
    var allParsed = window.parseBilingualText ? window.parseBilingualText(allRaw, lang) : 'Tất cả';
    html += '<button type="button" class="filter-tag-pill ' + (isAllActive ? 'is-active' : '') + '" data-val="all" data-bilingual="true" data-raw-label="' + allRaw + '">' + allParsed + '</button>';

    // 2. Toàn bộ regular labels / category trước
    labels.regular.forEach(function (reg) {
      var isActive = curSelected === reg.toLowerCase();
      var parsedReg = window.parseBilingualText ? window.parseBilingualText(reg, lang) : reg.split('|')[0].trim();
      html += '<button type="button" class="filter-tag-pill ' + (isActive ? 'is-active' : '') + '" data-val="' + escapeAttr(reg) + '" data-bilingual="true" data-raw-label="' + escapeAttr(reg) + '">';
      html += escapeHtml(parsedReg);
      html += '</button>';
    });

    // 3. Toàn bộ feature labels (@...) sau, không icon, cùng màu chung
    labels.feature.forEach(function (feat) {
      var isActive = curSelected === feat.toLowerCase();
      var parsedFeat = window.parseBilingualText ? window.parseBilingualText(feat, lang) : feat.split('|')[0].trim();
      html += '<button type="button" class="filter-tag-pill ' + (isActive ? 'is-active' : '') + '" data-val="' + escapeAttr(feat) + '" data-bilingual="true" data-raw-label="' + escapeAttr(feat) + '">';
      html += escapeHtml(parsedFeat);
      html += '</button>';
    });

    pillsContainer.innerHTML = html;
  }

  // ── Mở / Đóng Popover Bộ Lọc ──
  function toggleFilterPopover(container, forceState) {
    var popover = container.querySelector('#archive-filter-popover');
    var backdrop = container.querySelector('#archive-filter-backdrop');
    if (!popover) return;

    var willOpen = forceState !== undefined ? forceState : !isPopoverOpen;
    isPopoverOpen = willOpen;

    if (willOpen) {
      renderFilterPopoverContent(container);
      popover.style.display = 'flex';
      if (backdrop) backdrop.style.display = 'block';
      popover.classList.add('is-open');
    } else {
      popover.classList.remove('is-open');
      popover.style.display = 'none';
      if (backdrop) backdrop.style.display = 'none';
    }
  }

  // ── Xây dựng thẻ bài viết Subway Metro (Section 4.3 Spec) ──
  function renderSubwayPostCard(post) {
    var lang = (typeof localStorage !== 'undefined' && localStorage.getItem('user_lang')) || 'vi';

    // Xác định phong cách thẻ theo định dạng bài viết
    var cardModifier = 'subway-card--regular';
    var isQuote = false;
    var isBulletin = false;
    var isSpotlight = false;

    var firstFeat = (post.featureLabels && post.featureLabels[0]) || '';
    var lowerFeat = firstFeat.toLowerCase();

    if (lowerFeat.indexOf('quote') !== -1 || post.category.toLowerCase().indexOf('quote') !== -1) {
      cardModifier = 'subway-card--quote';
      isQuote = true;
    } else if (lowerFeat.indexOf('điểm tin') !== -1 || post.category.toLowerCase().indexOf('điểm tin') !== -1) {
      cardModifier = 'subway-card--bulletin';
      isBulletin = true;
    } else if (lowerFeat.indexOf('tiêu điểm') !== -1 || post.category.toLowerCase().indexOf('tiêu điểm') !== -1) {
      cardModifier = 'subway-card--spotlight';
      isSpotlight = true;
    } else if (post.postType === 'feature') {
      cardModifier = 'subway-card--feature';
    }

    // Tiêu đề bài viết
    var rawTitle = post.title || 'Bài viết không tiêu đề';
    var parsedTitle = window.parseBilingualText ? window.parseBilingualText(rawTitle, lang) : rawTitle.split('|')[0].trim();

    // Huy hiệu chuyên mục
    var rawCat = post.category || 'Góc Nhìn';
    var parsedCat = window.parseBilingualText ? window.parseBilingualText(rawCat, lang) : rawCat.split('|')[0].trim();

    var catIcon = '';
    var pillClass = 'subway-cat-pill';

    if (isQuote) {
      catIcon = '💬 ';
      pillClass += ' subway-pill--quote';
    } else if (isBulletin) {
      catIcon = '⚡ ';
      pillClass += ' subway-pill--bulletin';
    } else if (isSpotlight) {
      catIcon = '🌟 ';
      pillClass += ' subway-pill--spotlight';
    } else if (post.postType === 'feature') {
      catIcon = '⚡ ';
      pillClass += ' subway-pill--feature';
    }

    var aiAttr = post.aiType ? ' data-ai-type="' + escapeAttr(post.aiType) + '"' : '';
    var aiHtml = '';
    if (post.aiType && window.AITransparency) {
      aiHtml = window.AITransparency.renderAIBadge(post.aiType, 'micro', lang);
    }

    // Với bài @Quote: định dạng tiêu đề trong ngoặc kép thanh lịch nếu chưa có
    var displayTitle = parsedTitle;
    if (isQuote && !displayTitle.startsWith('“') && !displayTitle.startsWith('"')) {
      displayTitle = '“' + displayTitle + '”';
    }

    var html = [
      '<div class="subway-post-item">',
      '  <div class="subway-post-node" aria-hidden="true"></div>',
      '  <div class="subway-post-connector" aria-hidden="true"></div>',
      '  <a class="subway-post-card ' + cardModifier + '" href="' + escapeAttr(post.url) + '"' + aiAttr + '>',
      '    <span class="' + pillClass + '" data-bilingual="true" data-raw-label="' + escapeAttr(rawCat) + '" title="' + escapeAttr(parsedCat) + '">' + catIcon + escapeHtml(parsedCat) + '</span>',
      '    <span class="subway-post-title' + (isQuote ? ' subway-title--quote' : '') + '" data-bilingual="true" data-raw-label="' + escapeAttr(rawTitle) + '">' + escapeHtml(displayTitle) + '</span>',
      aiHtml ? '    ' + aiHtml : '',
      '    <div class="subway-post-meta">',
      '      <span class="subway-post-date">',
      '        <svg class="subway-date-icon" width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg>',
      '        <span>' + escapeHtml(post.dateStr) + '</span>',
      '      </span>',
      '      <span class="subway-post-arrow" aria-hidden="true">→</span>',
      '    </div>',
      '  </a>',
      '</div>'
    ].join('\n');

    return html;
  }

  // ── Render toàn bộ Cây Dòng Thời Gian Đường Tàu (Subway Metro Tree) ──
  function applyFilterAndRender(container) {
    var body = container.querySelector('#archive-app-body');
    if (!body) return;

    var filtered = filterPosts();
    var yearGroups = groupPostsByYear(filtered);

    // Cập nhật trạng thái nút icon filter
    updateFilterTriggerState(container);

    // Xử lý trạng thái rỗng nếu không tìm thấy bài viết
    if (yearGroups.length === 0) {
      body.innerHTML = [
        '<div class="archive-empty-state">',
        '  <div class="archive-empty-icon">🔍</div>',
        '  <h3 class="archive-empty-title" data-bilingual="true" data-raw-label="Không tìm thấy bài viết nào phù hợp | No matching posts found">' + (window.parseBilingualText ? window.parseBilingualText('Không tìm thấy bài viết nào phù hợp | No matching posts found', window.currentLang || 'vi') : 'Không tìm thấy bài viết nào phù hợp | No matching posts found') + '</h3>',
        '  <p class="archive-empty-desc" data-bilingual="true" data-raw-label="Thử điều chỉnh từ khóa tìm kiếm hoặc đặt lại các bộ lọc nâng cao. | Try adjusting your search keywords or resetting the filters.">' + (window.parseBilingualText ? window.parseBilingualText('Thử điều chỉnh từ khóa tìm kiếm hoặc đặt lại các bộ lọc nâng cao. | Try adjusting your search keywords or resetting the filters.', window.currentLang || 'vi') : 'Thử điều chỉnh từ khóa tìm kiếm hoặc đặt lại các bộ lọc nâng cao. | Try adjusting your search keywords or resetting the filters.') + '</p>',
        '  <button type="button" class="archive-btn-reset" id="archive-empty-reset-btn" data-bilingual="true" data-raw-label="↺ Xem tất cả bài viết | ↺ View all posts">' + (window.parseBilingualText ? window.parseBilingualText('↺ Xem tất cả bài viết | ↺ View all posts', window.currentLang || 'vi') : '↺ Xem tất cả bài viết | ↺ View all posts') + '</button>',
        '</div>'
      ].join('');

      var resetBtn = body.querySelector('#archive-empty-reset-btn');
      if (resetBtn) {
        resetBtn.addEventListener('click', function () {
          filterState.searchQuery = '';
          filterState.bannerCategory = 'all';
          filterState.selectedLabel = 'all';

          var searchInput = container.querySelector('#archive-search-input');
          var clearBtn = container.querySelector('#archive-search-clear');
          if (searchInput) searchInput.value = '';
          if (clearBtn) clearBtn.style.display = 'none';

          updateActiveCategoryTabs();
          syncUrlParams();
          applyFilterAndRender(container);
        });
      }
      return;
    }

    var lang = (typeof localStorage !== 'undefined' && localStorage.getItem('user_lang')) || 'vi';
    var rawRootTitle = window.parseBilingualText ? window.parseBilingualText('Bài Viết | Articles', lang) : 'Bài Viết';
    var cleanRootTitle = rawRootTitle.replace(/^[✦*\s]+/, '').trim();

    var html = '<div class="subway-tree">';

    // 1. Root Node ở đỉnh dòng thời gian (Node Gốc) - Không lặp lại dấu sao, không hiển thị số đếm
    html += '<div class="subway-root-node">';
    html += '  <div class="subway-root-badge">';
    html += '    <span class="subway-root-sparkle">✦</span>';
    html += '    <span class="subway-root-title">' + escapeHtml(cleanRootTitle) + '</span>';
    html += '  </div>';
    html += '</div>';

    // 2. Cột ray chính (Main Track) chứa các năm
    html += '<div class="subway-main-track">';
    html += '  <div class="subway-main-line" aria-hidden="true"></div>';

    yearGroups.forEach(function (group, gIdx) {
      var yr = group.year;
      // Năm đầu tiên (mới nhất) tự động mở; các năm cũ thu gọn mặc định (nếu chưa được lưu trạng thái)
      var isExpanded = expandedYears[yr] !== undefined ? expandedYears[yr] : (gIdx === 0);

      html += '<div class="subway-year-group ' + (isExpanded ? 'is-expanded' : 'is-collapsed') + '" data-year="' + yr + '">';

      // Hàng trạm năm (Station Row): Node Tròn Trạm -> Connector Ngang -> Lá Năm (Bỏ icon lịch, bỏ số bài)
      html += '<div class="subway-station-row">';
      html += '  <div class="subway-station-node" title="Trạm Năm ' + yr + '" aria-hidden="true">';
      html += '    <span class="subway-station-core"></span>';
      html += '  </div>';
      html += '  <div class="subway-branch-connector" aria-hidden="true"></div>';
      html += '  <button type="button" class="subway-year-leaf" aria-expanded="' + isExpanded + '" aria-controls="subway-branch-' + yr + '">';
      html += '    <span class="subway-year-num">' + yr + '</span>';
      html += '    <span class="subway-year-chevron" aria-hidden="true">';
      html += '      <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg>';
      html += '    </span>';
      html += '  </button>';
      html += '</div>'; // /.subway-station-row

      // Nhánh rẽ năm (Year Branch): Line năm thẳng đứng nét đứt + Danh sách Lá Bài Viết
      html += '<div class="subway-year-branch" id="subway-branch-' + yr + '">';
      html += '  <div class="subway-year-line" aria-hidden="true"></div>';
      html += '  <div class="subway-post-list">';
      group.posts.forEach(function (post) {
        html += renderSubwayPostCard(post);
      });
      html += '  </div>'; // /.subway-post-list
      html += '</div>'; // /.subway-year-branch

      html += '</div>'; // /.subway-year-group
    });

    html += '</div>'; // /.subway-main-track
    html += '</div>'; // /.subway-tree

    body.innerHTML = html;

    // Gắn sự kiện Expand / Collapse cho Lá Năm
    var yearLeaves = body.querySelectorAll('.subway-year-leaf');
    yearLeaves.forEach(function (leafBtn) {
      function toggleYearAccordion(e) {
        if (e) e.preventDefault();
        var groupEl = leafBtn.closest('.subway-year-group');
        if (!groupEl) return;
        var yr = groupEl.getAttribute('data-year');
        var branchEl = groupEl.querySelector('.subway-year-branch');
        var willExpand = !groupEl.classList.contains('is-expanded');

        if (willExpand) {
          groupEl.classList.remove('is-collapsed');
          groupEl.classList.add('is-expanded');
          leafBtn.setAttribute('aria-expanded', 'true');
          expandedYears[yr] = true;

          if (branchEl) {
            branchEl.style.maxHeight = branchEl.scrollHeight + 'px';
            setTimeout(function () {
              if (groupEl.classList.contains('is-expanded')) branchEl.style.maxHeight = 'none';
            }, 300);
          }
        } else {
          if (branchEl) {
            branchEl.style.maxHeight = branchEl.scrollHeight + 'px';
            // Force repaint
            void branchEl.offsetHeight;
            branchEl.style.maxHeight = '0px';
          }
          setTimeout(function () {
            groupEl.classList.remove('is-expanded');
            groupEl.classList.add('is-collapsed');
            leafBtn.setAttribute('aria-expanded', 'false');
            expandedYears[yr] = false;
          }, 240);
        }
      }

      leafBtn.addEventListener('click', toggleYearAccordion);
      leafBtn.addEventListener('keydown', function (e) {
        if (e.key === 'Enter' || e.key === ' ') {
          toggleYearAccordion(e);
        }
      });
    });

    // Luôn đồng bộ trạng thái active của Category Tabs dưới banner
    updateActiveCategoryTabs();
  }

  // ── Khởi tạo sự kiện tìm kiếm & popover bộ lọc ──
  function bindArchiveEvents(container) {
    if (container._eventsBound) return;
    container._eventsBound = true;

    var searchInput = container.querySelector('#archive-search-input');
    var clearBtn = container.querySelector('#archive-search-clear');
    var filterTrigger = container.querySelector('#archive-filter-trigger-btn');
    var filterClose = container.querySelector('#archive-filter-close-btn');
    var filterBackdrop = container.querySelector('#archive-filter-backdrop');
    var filterPopover = container.querySelector('#archive-filter-popover');
    var resetBtn = container.querySelector('#filter-popover-reset-btn');
    var applyBtn = container.querySelector('#filter-popover-apply-btn');

    // 1. Text Search Input
    if (searchInput) {
      if (filterState.searchQuery) {
        searchInput.value = filterState.searchQuery;
        if (clearBtn) clearBtn.style.display = 'flex';
      }

      searchInput.addEventListener('input', function () {
        filterState.searchQuery = searchInput.value;
        if (clearBtn) {
          clearBtn.style.display = filterState.searchQuery.length > 0 ? 'flex' : 'none';
        }

        clearTimeout(searchDebounceTimer);
        searchDebounceTimer = setTimeout(function () {
          syncUrlParams();
          applyFilterAndRender(container);
        }, 150); // Debounce 150ms chuẩn spec
      });
    }

    if (clearBtn) {
      clearBtn.addEventListener('click', function () {
        filterState.searchQuery = '';
        if (searchInput) {
          searchInput.value = '';
          searchInput.focus();
        }
        clearBtn.style.display = 'none';
        syncUrlParams();
        applyFilterAndRender(container);
      });
    }

    // 2. Mở / Đóng Filter Popover
    if (filterTrigger) {
      filterTrigger.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();
        toggleFilterPopover(container);
      });
    }

    if (filterClose) {
      filterClose.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();
        toggleFilterPopover(container, false);
      });
    }

    if (filterBackdrop) {
      filterBackdrop.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();
        toggleFilterPopover(container, false);
      });
    }

    // Đóng popover khi nhấn phím ESC hoặc click bên ngoài trên desktop
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && isPopoverOpen) {
        toggleFilterPopover(container, false);
      }
    });

    document.addEventListener('click', function (e) {
      if (!isPopoverOpen) return;
      var popover = container.querySelector('#archive-filter-popover');
      var trigger = container.querySelector('#archive-filter-trigger-btn');
      if (popover && !popover.contains(e.target) && trigger && !trigger.contains(e.target)) {
        toggleFilterPopover(container, false);
      }
    });

    // 3. Tương tác chọn Pill bên trong Popover: Lọc tức thì và đóng popup
    if (filterPopover) {
      filterPopover.addEventListener('click', function (e) {
        var pill = e.target.closest('.filter-tag-pill');
        if (!pill) return;

        var val = pill.getAttribute('data-val') || 'all';
        filterState.selectedLabel = val;

        syncUrlParams();
        applyFilterAndRender(container);
        toggleFilterPopover(container, false);
      });
    }

    // 4. Nút Đặt Lại / Xem Tất Cả trong Popover
    if (resetBtn) {
      resetBtn.addEventListener('click', function () {
        filterState.selectedLabel = 'all';
        syncUrlParams();
        applyFilterAndRender(container);
        toggleFilterPopover(container, false);
      });
    }
  }

  // ── Tạo khung HTML hoàn chỉnh cho Dedicated Archive Page ──
  function createArchiveStructure(container) {
    if (container.querySelector('#archive-filter-trigger-btn') && container.querySelector('#archive-app-body')) {
      return; // Đã có cấu trúc đầy đủ
    }

    var lang = (typeof localStorage !== 'undefined' && localStorage.getItem('user_lang')) || 'vi';
    var placeholderText = lang === 'en' ? 'Search articles...' : 'Tìm kiếm bài viết...';

    var filterHeadingRaw = 'Lọc Theo Nhãn | Filter by Tags';
    var filterHeadingText = window.parseBilingualText ? window.parseBilingualText(filterHeadingRaw, lang) : 'Lọc Theo Nhãn';

    var resetBtnRaw = '↺ Xem tất cả | ↺ View all';
    var resetBtnText = window.parseBilingualText ? window.parseBilingualText(resetBtnRaw, lang) : '↺ Xem tất cả';

    var html = [
      '<!-- Thanh Tìm Kiếm Tức Thì & Nút Bộ Lọc Nâng Cao (@) -->',
      '<div class="archive-search-wrap">',
      '  <span class="archive-search-icon" aria-hidden="true">🔍</span>',
      '  <input class="archive-search-input" id="archive-search-input" type="search"',
      '         placeholder="' + placeholderText + '" data-i18n="searchPlaceholder"',
      '         autocomplete="off" aria-label="Tìm kiếm bài viết"/>',
      '  <button type="button" class="archive-search-clear" id="archive-search-clear" aria-label="Xóa tìm kiếm" style="display:none;">✕</button>',
      '  <button type="button" class="archive-filter-trigger-btn" id="archive-filter-trigger-btn" aria-label="Mở bộ lọc nâng cao" title="Bộ lọc tính năng nâng cao">',
      '    <svg class="icon-filter" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">',
      '      <polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"></polygon>',
      '    </svg>',
      '    <span class="filter-badge-dot" id="archive-filter-dot" style="display:none;"></span>',
      '  </button>',
      '',
      '  <!-- Backdrop & Popover / Bottom Sheet Bộ Lọc Nâng Cao -->',
      '  <div class="archive-filter-backdrop" id="archive-filter-backdrop" style="display:none;"></div>',
      '  <div class="archive-filter-popover" id="archive-filter-popover" style="display:none;" role="dialog" aria-modal="true" aria-labelledby="archive-filter-heading">',
      '    <div class="filter-popover-sheet-handle" aria-hidden="true"></div>',
      '    <div class="filter-popover-header">',
      '      <div class="filter-popover-title-row">',
      '        <span class="filter-popover-icon">🏷️</span>',
      '        <h4 class="filter-popover-heading" id="archive-filter-heading" data-bilingual="true" data-raw-label="' + filterHeadingRaw + '">' + filterHeadingText + '</h4>',
      '      </div>',
      '      <button type="button" class="filter-popover-close-btn" id="archive-filter-close-btn" aria-label="Đóng bộ lọc">✕</button>',
      '    </div>',
      '',
      '    <div class="filter-popover-body">',
      '      <div class="filter-popover-pills" id="filter-pills-list">',
      '        <!-- Dynamic Pills: Tất cả, Regular Labels, Feature @ Labels -->',
      '      </div>',
      '    </div>',
      '',
      '    <!-- Chân trang Popover -->',
      '    <div class="filter-popover-footer">',
      '      <button type="button" class="filter-popover-btn-reset" id="filter-popover-reset-btn" data-bilingual="true" data-raw-label="' + resetBtnRaw + '">' + resetBtnText + '</button>',
      '    </div>',
      '  </div>',
      '</div>',
      '',
      '<!-- Khung cây Dòng Thời Gian Đường Tàu -->',
      '<div id="archive-app-body" class="subway-tree-container" aria-live="polite">',
      '  <div class="archive-loading">',
      '    <div class="archive-spinner"></div>',
      '    <span>Đang đồng bộ tuyến đường thời gian...</span>',
      '  </div>',
      '</div>'
    ].join('\n');

    container.innerHTML = html;
  }

  // ── Kết nối thanh nhãn Chuyên mục dưới banner (.category-tabs-bar) ──
  function bindCategoryTabs(container) {
    if (window._categoryTabsBound) return;
    window._categoryTabsBound = true;

    document.addEventListener('click', function (e) {
      var pill = e.target.closest('.category-tabs-bar .tab-pill, #category-tabs-bar .tab-pill');
      if (!pill) return;

      // Chỉ can thiệp khi đang ở trang Dòng thời gian / Mục lục
      if (!isArchivePage()) return;

      var appEl = document.getElementById('editorial-archive-app');
      if (!appEl) return;

      // Chặn chuyển hướng trang chủ
      e.preventDefault();
      e.stopPropagation();

      var href = pill.getAttribute('href') || '';
      var rawLabel = (pill.getAttribute('data-raw-label') || pill.getAttribute('data-label') || pill.textContent || '').trim();
      var cleanLabel = rawLabel.replace(/^✦\s*/, '').trim();

      var isAll = href === '/' || href === (window.location.origin + '/') ||
                  cleanLabel.toLowerCase().indexOf('tất cả') !== -1 ||
                  cleanLabel.toLowerCase() === 'all';

      filterState.bannerCategory = isAll ? 'all' : cleanLabel;

      syncUrlParams();
      updateActiveCategoryTabs();
      applyFilterAndRender(appEl);
    }, true);
  }

  // ── Khởi động toàn bộ ứng dụng Mục Lục Đường Tàu ──
  function mountArchiveApp(targetEl) {
    var container = targetEl || document.getElementById('editorial-archive-app');
    if (!container) return;

    container.classList.add('editorial-archive-page');
    createArchiveStructure(container);
    parseUrlParams();
    bindArchiveEvents(container);
    bindCategoryTabs(container);
    updateActiveCategoryTabs();

    loadArchiveData(function () {
      applyFilterAndRender(container);
    });

    isAppMounted = true;
  }

  // ── Khởi chạy khi DOM sẵn sàng ──
  function init() {
    var appEl = document.getElementById('editorial-archive-app');
    if (appEl && (isArchivePage() || window.location.hash === '#archive' || appEl.offsetParent !== null)) {
      mountArchiveApp(appEl);
    }
  }

  // Export API toàn cục để preview.html hoặc router có thể gọi trực tiếp
  window.initArchivePage = function (targetEl) {
    mountArchiveApp(targetEl);
  };

  // Lắng nghe sự kiện đổi hash sang #archive
  window.addEventListener('hashchange', function () {
    if (window.location.hash === '#archive') {
      var appEl = document.getElementById('editorial-archive-app');
      if (appEl) mountArchiveApp(appEl);
    }
  });

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();


/* ==========================================
   AUTO TABLE OF CONTENTS (TOC) GENERATOR
   - Extracts visible h2, h3 from .post-body
   - Supports bilingual content filtering & sync
   - Collapsible with toggle button
   - Smooth scroll to section on click
   - Highlights active section during scroll
   ========================================== */
(function() {
  'use strict';

  var tocContainer = null;
  var isCollapsed = false;
  var observer = null;

  function getVisibleHeadings() {
    var postBody = document.querySelector('.post-body');
    if (!postBody) return [];

    var allHeadings = postBody.querySelectorAll('h2, h3');
    var visibleHeadings = [];

    allHeadings.forEach(function(heading) {
      var parent = heading.parentElement;
      var isHidden = false;
      while (parent && parent !== postBody) {
        if (parent.style.display === 'none' || (parent.hasAttribute('data-lang') && parent.style.display === 'none')) {
          isHidden = true;
          break;
        }
        parent = parent.parentElement;
      }
      if (!isHidden) {
        visibleHeadings.push(heading);
      }
    });

    return visibleHeadings;
  }

  function initTOC() {
    var postBody = document.querySelector('.post-body');
    tocContainer = document.getElementById('auto-toc');
    if (!postBody || !tocContainer) return;

    var headings = getVisibleHeadings();
    if (headings.length < 2) {
      tocContainer.style.display = 'none';
      return;
    }
    tocContainer.style.display = '';

    // Assign IDs to headings
    headings.forEach(function(heading, idx) {
      if (!heading.id) {
        var slug = heading.innerText
          .toLowerCase()
          .replace(/[^a-z0-9À-ɏḀ-ỿ\s-]/g, '')
          .replace(/\s+/g, '-')
          .replace(/-+/g, '-')
          .trim();
        heading.id = slug || ('heading-' + idx);
      }
    });

    // Detect language for title
    var currentLang = (typeof localStorage !== 'undefined' && localStorage.getItem('user_lang')) || 'vi';
    var isEn = (currentLang === 'en');
    var tocTitleText = isEn ? '📑 Table of Contents' : '📑 Mục Lục Bài Viết';

    // Build TOC HTML
    var html = '<div class="toc-title" onclick="toggleTocList()" role="button" tabindex="0">' +
               '<span data-i18n="tableOfContents">' + tocTitleText + '</span>' +
               '<span class="toc-toggle-icon" id="toc-toggle-icon">' + (isCollapsed ? '▼' : '▲') + '</span>' +
               '</div>' +
               '<ul class="toc-list" id="toc-list-items"' + (isCollapsed ? ' style="display:none;"' : '') + '>';

    headings.forEach(function(heading) {
      var tagClass = heading.tagName.toLowerCase() === 'h3' ? 'toc-h3' : 'toc-h2';
      var headingText = (typeof window.parseBilingualText === 'function')
        ? window.parseBilingualText(heading.innerText, currentLang)
        : heading.innerText;
      html += '<li class="' + tagClass + '">' +
              '<a href="#' + heading.id + '" onclick="scrollToSection(event, \'' + heading.id + '\')">' +
              headingText + '</a></li>';
    });

    html += '</ul>';
    tocContainer.innerHTML = html;

    // Keyboard accessibility for TOC title
    var tocTitle = tocContainer.querySelector('.toc-title');
    if (tocTitle) {
      tocTitle.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') toggleTocList();
      });
    }

    // Activate IntersectionObserver for highlight
    initTOCObserver(headings);
  }

  // Toggle open/collapse
  window.toggleTocList = function() {
    var list = document.getElementById('toc-list-items');
    var icon = document.getElementById('toc-toggle-icon');
    if (!list) return;
    isCollapsed = !isCollapsed;
    list.style.display = isCollapsed ? 'none' : '';
    if (icon) icon.innerText = isCollapsed ? '▼' : '▲';
  };

  // Smooth scroll to heading
  window.scrollToSection = function(e, id) {
    e.preventDefault();
    var target = document.getElementById(id);
    if (!target) return;
    var offset = 80; // header height + gap
    var top = target.getBoundingClientRect().top + window.pageYOffset - offset;
    window.scrollTo({ top: top, behavior: 'smooth' });
    if (history.replaceState) {
      history.replaceState(null, null, '#' + id);
    }
  };

  // Highlight active TOC item on scroll
  function initTOCObserver(headings) {
    if (!('IntersectionObserver' in window)) return;
    if (observer) observer.disconnect();

    var activeId = null;

    observer = new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        if (entry.isIntersecting) {
          activeId = entry.target.id;
        }
      });

      if (activeId) {
        var links = document.querySelectorAll('.toc-list a');
        links.forEach(function(link) {
          if (link.getAttribute('href') === '#' + activeId) {
            link.classList.add('active');
          } else {
            link.classList.remove('active');
          }
        });
      }
    }, {
      rootMargin: '-80px 0px -60% 0px',
      threshold: 0
    });

    headings.forEach(function(heading) {
      observer.observe(heading);
    });
  }

  // Re-generate TOC on language change
  window.addEventListener('languageChanged', function() {
    initTOC();
  });

  document.addEventListener('DOMContentLoaded', initTOC);
})();


/* ==========================================
   READING PROGRESS BAR & READING TIME
   ========================================== */
(function() {
  'use strict';

  // Reading Progress Bar (throttled for perf)
  var progressBar = null;
  var ticking = false;

  function updateProgress() {
    if (!progressBar) return;
    var winScroll = window.pageYOffset || document.documentElement.scrollTop;
    var height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
    var pct = height > 0 ? Math.min(100, (winScroll / height) * 100) : 0;
    progressBar.style.width = pct + '%';
    ticking = false;
  }

  window.addEventListener('scroll', function() {
    if (!ticking) {
      requestAnimationFrame(updateProgress);
      ticking = true;
    }
  }, { passive: true });

  // Reading Time Calculator (Localized)
  function calcReadingTime() {
    var postBody = document.querySelector('.post-body');
    var readTimeEl = document.getElementById('reading-time-val');
    if (!postBody || !readTimeEl) return;

    var lang = (typeof localStorage !== 'undefined' && localStorage.getItem('user_lang')) || 'vi';
    var text = postBody.innerText || postBody.textContent || '';
    var words = text.trim().split(/\s+/).filter(function(w) { return w.length > 0; }).length;
    var minutes = Math.max(1, Math.ceil(words / 200));
    var unit = (lang === 'en') ? 'min read' : 'phút đọc';
    readTimeEl.innerText = minutes + ' ' + unit;
  }

  // Copy share link buttons
  function initCopyLink() {
    var copyBtns = document.querySelectorAll('#copy-link-btn, #quick-copy-link-btn, .btn-share-copy, .quick-share-copy');
    if (!copyBtns.length) return;
    copyBtns.forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.preventDefault();
        var url = window.location.href;
        if (navigator.clipboard) {
          navigator.clipboard.writeText(url).then(function() {
            showCopiedToast();
          }).catch(function() {
            fallbackCopy(url);
          });
        } else {
          fallbackCopy(url);
        }
      });
    });
  }

  // Share Dropdowns & Web Share API (Handles both Header and Bottom share buttons)
  function initShareDropdown() {
    var dropdowns = document.querySelectorAll('.post-share-dropdown');
    if (!dropdowns.length) return;

    dropdowns.forEach(function(wrapper) {
      var trigger = wrapper.querySelector('.post-share-trigger');
      var menu = wrapper.querySelector('.post-share-menu');
      if (!trigger || !menu) return;

      var nativeBtn = wrapper.querySelector('.share-menu-native');
      if (navigator.share && nativeBtn) {
        nativeBtn.style.display = 'flex';
        nativeBtn.addEventListener('click', function(e) {
          e.preventDefault();
          closeMenu();
          navigator.share({
            title: document.title,
            url: window.location.href
          }).catch(function() {});
        });
      }

      function toggleMenu(open) {
        var isExpanded = trigger.getAttribute('aria-expanded') === 'true';
        var state = (typeof open === 'boolean') ? open : !isExpanded;
        if (state) {
          // Close other open dropdowns
          document.querySelectorAll('.post-share-dropdown').forEach(function(other) {
            if (other !== wrapper) {
              var ot = other.querySelector('.post-share-trigger');
              var om = other.querySelector('.post-share-menu');
              if (ot) ot.setAttribute('aria-expanded', 'false');
              if (om) om.classList.remove('show');
            }
          });
        }
        trigger.setAttribute('aria-expanded', state ? 'true' : 'false');
        if (state) {
          menu.classList.add('show');
        } else {
          menu.classList.remove('show');
        }
      }

      function closeMenu() {
        toggleMenu(false);
      }

      trigger.addEventListener('click', function(e) {
        e.stopPropagation();
        toggleMenu();
      });

      // Close when clicking outside
      document.addEventListener('click', function(e) {
        if (!wrapper.contains(e.target)) {
          closeMenu();
        }
      });

      // Close on Escape key
      document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') closeMenu();
      });

      // Social share links popup window
      var socialLinks = menu.querySelectorAll('a.share-menu-item');
      socialLinks.forEach(function(link) {
        link.addEventListener('click', function(e) {
          var href = this.getAttribute('href');
          if (href && !href.startsWith('#')) {
            e.preventDefault();
            window.open(href, '_blank', 'width=600,height=500,menubar=no,toolbar=no');
            closeMenu();
          }
        });
      });

      // Close menu when clicking copy link
      var copyBtn = menu.querySelector('#quick-copy-link-btn, .quick-share-copy');
      if (copyBtn) {
        copyBtn.addEventListener('click', function() {
          closeMenu();
        });
      }
    });
  }

  // Auto-enhance Post Images: upscale Blogger CDN images & remove restrictive inline dimensions
  function enhancePostImages() {
    var postBody = document.querySelector('.post-body');
    if (!postBody) return;

    var images = postBody.querySelectorAll('img');
    images.forEach(function(img) {
      // 1. Remove fixed width/height HTML attributes and inline style constraints
      img.removeAttribute('width');
      img.removeAttribute('height');
      if (img.style.width) img.style.width = '';
      if (img.style.height) img.style.height = '';

      // 2. Upgrade resolution in Blogger/Google CDN URLs to full HD (s1600)
      var src = img.getAttribute('src');
      if (src && (src.includes('blogger.googleusercontent.com') || src.includes('.bp.blogspot.com') || src.includes('googleusercontent.com'))) {
        // Matches /s72-c/, /s320/, /s400/, /s640/, /s800/, /w320-h180/, etc.
        var newSrc = src.replace(/\/(s(72|120|200|320|400|640|800|1024|1200)(-[a-z0-9]+)?|w[0-9]+-h[0-9]+(-[a-z0-9]+)?)\//i, '/s1600/');
        if (newSrc !== src) {
          img.src = newSrc;
        }
      }

      // 3. Ensure parent link/separator does not clip or restrict image
      var parent = img.parentElement;
      if (parent && (parent.classList.contains('separator') || parent.tagName === 'A')) {
        parent.style.maxWidth = '100%';
        parent.style.display = 'block';
        if (parent.parentElement && parent.parentElement.classList.contains('separator')) {
          parent.parentElement.style.maxWidth = '100%';
          parent.parentElement.style.display = 'block';
        }
      }
    });
  }

  function fallbackCopy(text) {
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); } catch(e) {}
    document.body.removeChild(ta);
    showCopiedToast();
  }

  function showCopiedToast() {
    var existing = document.getElementById('copied-toast');
    if (existing) existing.remove();

    var lang = (typeof localStorage !== 'undefined' && localStorage.getItem('user_lang')) || 'vi';
    var toastMsg = (lang === 'en') ? '✅ Link copied to clipboard!' : '✅ Đã sao chép liên kết!';

    var toast = document.createElement('div');
    toast.id = 'copied-toast';
    toast.innerText = toastMsg;
    toast.style.cssText = [
      'position: fixed',
      'bottom: 1.5rem',
      'left: 50%',
      'transform: translateX(-50%)',
      'background: #0f172a',
      'color: #fff',
      'padding: 0.65rem 1.35rem',
      'border-radius: 9999px',
      'font-size: 0.88rem',
      'font-weight: 600',
      'z-index: 9999',
      'box-shadow: 0 4px 20px rgba(0,0,0,0.3)',
      'animation: fadeInUp 0.3s ease'
    ].join(';');

    // Inject keyframe once
    if (!document.getElementById('toast-keyframe')) {
      var style = document.createElement('style');
      style.id = 'toast-keyframe';
      style.textContent = '@keyframes fadeInUp { from { opacity:0; transform: translateX(-50%) translateY(10px); } to { opacity:1; transform: translateX(-50%) translateY(0); } }';
      document.head.appendChild(style);
    }

    document.body.appendChild(toast);
    setTimeout(function() {
      toast.style.opacity = '0';
      toast.style.transition = 'opacity 0.3s ease';
      setTimeout(function() { toast.remove(); }, 350);
    }, 2200);
  }

  // Newsletter Subscription Modal
  function initNewsletterModal() {
    var modal = document.getElementById('newsletter-modal');
    if (!modal) return;

    var closeBtn = document.getElementById('newsletter-modal-close');
    var form = document.getElementById('newsletter-modal-form');
    var emailInput = document.getElementById('newsletter-modal-email');
    var backdrop = document.getElementById('newsletter-modal-backdrop');

    function openModal() {
      modal.style.display = 'flex';
      requestAnimationFrame(function() {
        modal.classList.add('is-open');
        if (emailInput) emailInput.focus();
      });
      document.body.style.overflow = 'hidden';
    }

    function closeModal() {
      modal.classList.remove('is-open');
      setTimeout(function() {
        modal.style.display = 'none';
        document.body.style.overflow = '';
      }, 250);
    }

    window.openNewsletterModal = openModal;
    window.closeNewsletterModal = closeModal;

    // Attach click event to all newsletter triggers across the page
    document.querySelectorAll('a[href="#newsletter"], .btn-subscribe, .btn-newsletter-trigger').forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.preventDefault();
        openModal();
      });
    });

    if (closeBtn) closeBtn.addEventListener('click', closeModal);
    if (backdrop) backdrop.addEventListener('click', closeModal);

    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape' && modal.classList.contains('is-open')) {
        closeModal();
      }
    });

    if (form) {
      form.addEventListener('submit', function(e) {
        e.preventDefault();
        if (!emailInput) return;
        var email = emailInput.value.trim();
        var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!email || !emailRegex.test(email)) {
          emailInput.style.borderColor = '#ef4444';
          emailInput.focus();
          setTimeout(function() { emailInput.style.borderColor = ''; }, 2500);
          return;
        }

        var submitBtn = form.querySelector('button[type="submit"]');
        var lang = (typeof localStorage !== 'undefined' && localStorage.getItem('user_lang')) || 'vi';
        var origText = submitBtn ? submitBtn.innerText : '';
        if (submitBtn) {
          submitBtn.disabled = true;
          submitBtn.innerText = (lang === 'en') ? '✓ Subscribed!' : '✓ Đã Đăng Ký!';
          submitBtn.style.background = '#10b981';
        }

        // Show toast
        var successMsg = (lang === 'en')
          ? '🎉 Thank you! You have subscribed to our newsletter.'
          : '🎉 Cảm ơn bạn! Đã đăng ký nhận bản tin thành công.';

        var toast = document.createElement('div');
        toast.className = 'newsletter-success-toast';
        toast.innerText = successMsg;
        toast.style.cssText = 'position:fixed;bottom:2rem;left:50%;transform:translateX(-50%);background:#10b981;color:#fff;padding:0.75rem 1.5rem;border-radius:9999px;font-weight:700;z-index:99999;box-shadow:0 4px 20px rgba(0,0,0,0.25);';
        document.body.appendChild(toast);
        setTimeout(function() { toast.remove(); }, 3500);

        setTimeout(function() {
          closeModal();
          emailInput.value = '';
          if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerText = origText;
            submitBtn.style.background = '';
          }
        }, 1500);
      });
    }
  }

  // Scroll-to-top button
  function initScrollTop() {
    var btn = document.getElementById('scroll-top-btn');
    if (!btn) return;
    btn.addEventListener('click', function(e) {
      e.preventDefault();
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  }

  // Dynamic Related Posts via Blogger JSON Feed API
  function initRelatedPosts() {
    var relSection = document.getElementById('related-posts-section');
    if (!relSection) return;
    var grid = document.getElementById('related-posts-grid');
    if (!grid) return;

    // In local preview where Blogger feed doesn't exist, preserve static cards if present
    if (window.location.protocol === 'file:' && grid.querySelector('.related-post-card')) return;

    var label = (relSection.getAttribute('data-label') || '').trim();
    var currentUrl = relSection.getAttribute('data-current-url') || window.location.href;
    var currentPath = '';
    try {
      currentPath = new URL(currentUrl, window.location.origin).pathname;
    } catch(e) {
      currentPath = window.location.pathname;
    }

    var lastEntries = null;

    var feedUrl = label
      ? '/feeds/posts/summary/-/' + encodeURIComponent(label) + '?alt=json&max-results=6&_cb=' + Date.now()
      : '/feeds/posts/summary?alt=json&max-results=6&_cb=' + Date.now();

    function renderPosts(entries) {
      if (!entries || !entries.length) {
        if (label) {
          // If category feed returned empty, fallback to recent posts
          label = '';
          fetchFeed('/feeds/posts/summary?alt=json&max-results=6&_cb=' + Date.now());
        } else {
          relSection.style.display = 'none';
        }
        return;
      }

      var validPosts = [];
      for (var i = 0; i < entries.length; i++) {
        var entry = entries[i];
        var postUrl = '';
        if (entry.link) {
          for (var j = 0; j < entry.link.length; j++) {
            if (entry.link[j].rel === 'alternate') {
              postUrl = entry.link[j].href;
              break;
            }
          }
        }

        // Avoid showing current post
        if (postUrl) {
          var entryPath = '';
          try {
            entryPath = new URL(postUrl, window.location.origin).pathname;
            if (entryPath === currentPath) continue;
          } catch(err) {
            if (postUrl === currentUrl) continue;
          }

          // Deduplicate: avoid showing posts that already belong to the active series
          if (window.SERIES_POST_URLS && window.SERIES_POST_URLS.length) {
            var isSeriesPost = false;
            for (var s = 0; s < window.SERIES_POST_URLS.length; s++) {
              var sUrl = window.SERIES_POST_URLS[s];
              if (sUrl === postUrl) { isSeriesPost = true; break; }
              try {
                if (entryPath && new URL(sUrl, window.location.origin).pathname === entryPath) {
                  isSeriesPost = true; break;
                }
              } catch(se) {}
            }
            if (isSeriesPost) continue;
          }
        }

        var title = entry.title ? (entry.title.$t || '') : '';
        var published = entry.published ? (entry.published.$t || '') : '';
        var dateStr = '';
        if (published) {
          try {
            var d = new Date(published);
            var day = ('0' + d.getDate()).slice(-2);
            var month = ('0' + (d.getMonth() + 1)).slice(-2);
            var year = d.getFullYear();
            dateStr = day + '/' + month + '/' + year;
          } catch(e) {
            dateStr = published.substring(0, 10);
          }
        }

        // Extract thumbnail and upgrade resolution
        var thumb = '';
        if (entry.media$thumbnail && entry.media$thumbnail.url) {
          thumb = entry.media$thumbnail.url;
          thumb = thumb.replace(/\/s72-c\//, '/w600-h360-c/')
                       .replace(/\/w72-h72-p-k-no-nu\//, '/w600-h360-c/')
                       .replace(/\/s1600-w[0-9]+-h[0-9]+-c\//, '/w600-h360-c/');
        } else if (entry.content && entry.content.$t) {
          var match = entry.content.$t.match(/<img[^>]+src=["']([^"']+)["']/i);
          if (match && match[1]) thumb = match[1];
        }

        validPosts.push({
          title: title,
          url: postUrl || '#',
          date: dateStr,
          thumb: thumb
        });

        if (validPosts.length >= 3) break;
      }

      if (validPosts.length === 0) {
        relSection.style.display = 'none';
        return;
      }

      grid.innerHTML = '';
      validPosts.forEach(function(item) {
        var card = document.createElement('a');
        card.className = 'related-post-card';
        card.href = item.url;

        var imgHtml = item.thumb
          ? '<img class="related-post-thumb" src="' + item.thumb + '" alt="' + item.title.replace(/"/g, '&quot;') + '" loading="lazy" decoding="async"/>'
          : '<div class="related-post-thumb-placeholder">📰</div>';

        card.innerHTML = imgHtml +
          '<span class="related-post-title" data-bilingual="true">' + item.title + '</span>' +
          '<span class="related-post-date">📅 ' + item.date + '</span>';

        grid.appendChild(card);
      });

      if (window.applyBilingualElements) {
        window.applyBilingualElements();
      }
    }

    function fetchFeed(url) {
      fetch(url, { cache: 'no-cache' })
        .then(function(res) {
          if (!res.ok) throw new Error('Network error');
          return res.json();
        })
        .then(function(data) {
          var entries = (data && data.feed && data.feed.entry) ? data.feed.entry : [];
          lastEntries = entries;
          renderPosts(entries);
        })
        .catch(function() {
          if (label) {
            label = '';
            fetch('/feeds/posts/summary?alt=json&max-results=6&_cb=' + Date.now(), { cache: 'no-cache' })
              .then(function(r) { return r.json(); })
              .then(function(d) {
                var entries = (d && d.feed && d.feed.entry) ? d.feed.entry : [];
                lastEntries = entries;
                renderPosts(entries);
              })
              .catch(function() {
                relSection.style.display = 'none';
              });
          } else {
            relSection.style.display = 'none';
          }
        });
    }

    // When series widget finishes loading, re-render related posts to ensure deduplication
    window.addEventListener('seriesLoaded', function() {
      if (lastEntries && lastEntries.length) {
        renderPosts(lastEntries);
      }
    });

    fetchFeed(feedUrl);
  }

  // Update on language changed
  window.addEventListener('languageChanged', function() {
    calcReadingTime();
  });

  document.addEventListener('DOMContentLoaded', function() {
    progressBar = document.querySelector('.reading-progress-bar');
    calcReadingTime();
    initCopyLink();
    initShareDropdown();
    initNewsletterModal();
    enhancePostImages();
    initScrollTop();
    initRelatedPosts();
  });
})();


/* ==========================================================================
   POST SERIES NAVIGATOR — LUXURY EDITORIAL EDITION (ROBUST V3)
   - Detects posts with 'series:[name]' label
   - Queries Blogger JSON Feed API for all parts with cache-buster
   - Stale-while-revalidate caching (invalidates if current post missing)
   - Robust URL/Slug pathname matching
   - Connected Vertical Journey Stepper (Timeline)
   - Active Illuminated Chapter Card & Next Chapter Spotlight
   - Populates window.SERIES_POST_URLS to deduplicate Related Posts
   - Localized (VI/EN)
   ========================================================================== */
(function() {
  'use strict';

  var SERIES_I18N = {
    vi: {
      seriesBadge: 'CHUYÊN ĐỀ',
      partLabel: 'Phần',
      progressText: 'Tiến trình:',
      completedRatio: 'hoàn thành',
      currentReading: 'Đang đọc',
      readStatus: 'Đã đọc',
      nextChapterBadge: 'Tiếp theo',
      upcomingBadge: 'Chưa đọc',
      nextKicker: 'Bài tiếp theo',
      prevKicker: 'Bài trước',
      completedSeriesMsg: 'Bạn đã hoàn thành tất cả các phần trong chuyên đề này.',
      viewRoadmap: 'Lộ trình ↓'
    },
    en: {
      seriesBadge: 'SERIES',
      partLabel: 'Part',
      progressText: 'Progress:',
      completedRatio: 'completed',
      currentReading: 'Reading Now',
      readStatus: 'Completed',
      nextChapterBadge: 'Next Up',
      upcomingBadge: 'Upcoming',
      nextKicker: 'Next Chapter',
      prevKicker: 'Previous',
      completedSeriesMsg: 'You have completed all parts of this series.',
      viewRoadmap: 'Roadmap ↓'
    }
  };

  function getLang() {
    return (typeof localStorage !== 'undefined' && localStorage.getItem('user_lang')) || 'vi';
  }

  function formatSeriesTitle(rawLabel) {
    if (!rawLabel) return '';
    var name = rawLabel.replace(/^series:\s*/i, '').trim();
    if (name.indexOf('-') > -1 && name.indexOf(' ') === -1) {
      name = name.split('-').map(function(word) {
        return word.charAt(0).toUpperCase() + word.slice(1);
      }).join(' ');
    }
    return name;
  }

  function initPostSeries() {
    var pillContainer = document.getElementById('series-header-pill-container');
    var boxContainer = document.getElementById('series-roadmap-box-container');

    var seriesLabel = (pillContainer && pillContainer.getAttribute('data-series-label')) ||
                      (boxContainer && boxContainer.getAttribute('data-series-label')) || '';

    if (!seriesLabel) {
      var seriesEl = document.querySelector('[data-series-label]');
      if (seriesEl) seriesLabel = seriesEl.getAttribute('data-series-label');
    }

    if (!seriesLabel) {
      var rawLabels = document.querySelectorAll('.post-raw-label');
      rawLabels.forEach(function(lbl) {
        var txt = (lbl.innerText || lbl.textContent || '').trim();
        if (/^series:/i.test(txt)) {
          seriesLabel = txt;
        }
      });
    }

    if (!seriesLabel || !/^series:/i.test(seriesLabel)) {
      if (pillContainer) pillContainer.style.display = 'none';
      if (boxContainer) boxContainer.style.display = 'none';
      return;
    }

    var seriesTitle = formatSeriesTitle(seriesLabel);
    var currentUrl = window.location.href;
    var currentPath = window.location.pathname;

    // Use versioned cache key to discard old invalid caches
    var cacheKey = 'post_series_v3_' + encodeURIComponent(seriesLabel);
    var cachedData = null;
    try {
      var raw = sessionStorage.getItem(cacheKey);
      if (raw) cachedData = JSON.parse(raw);
    } catch(e) {}

    // Verify if cachedData actually contains the post we are currently reading
    var isCacheValid = false;
    if (cachedData && Array.isArray(cachedData) && cachedData.length > 0) {
      for (var c = 0; c < cachedData.length; c++) {
        try {
          var cp = new URL(cachedData[c].url, window.location.origin).pathname;
          if (cp === currentPath || currentPath.indexOf(cp) > -1 || cp.indexOf(currentPath) > -1 || cachedData[c].url === currentUrl) {
            isCacheValid = true;
            break;
          }
        } catch(e) {}
      }
    }

    if (isCacheValid) {
      // 1. Render immediately from valid cache for 0ms CLS
      renderSeries(cachedData, seriesTitle, currentUrl, currentPath);
      // 2. Revalidate in background to pick up newly published parts
      fetchSeriesFeed(seriesLabel, seriesTitle, currentUrl, currentPath, cacheKey, true);
    } else {
      // Cache missing or invalid (does not contain current post) -> fetch immediately
      fetchSeriesFeed(seriesLabel, seriesTitle, currentUrl, currentPath, cacheKey, false);
    }
  }

  function fetchSeriesFeed(seriesLabel, seriesTitle, currentUrl, currentPath, cacheKey, isBackgroundRevalidate) {
    // If preview sandbox environment offline, do not crash but wire up pill click
    if (window.location.protocol === 'file:') {
      var pillTrigger = document.getElementById('series-pill-trigger');
      if (pillTrigger) {
        pillTrigger.addEventListener('click', function(e) {
          e.preventDefault();
          var target = document.getElementById('series-roadmap-box');
          if (target) {
            target.scrollIntoView({ behavior: 'smooth', block: 'center' });
            target.style.outline = '2px solid var(--primary)';
            setTimeout(function() { target.style.outline = 'none'; }, 2000);
          }
        });
      }
      return;
    }

    // Add cache buster timestamp to prevent stale browser disk cache
    var feedUrl = '/feeds/posts/summary/-/' + encodeURIComponent(seriesLabel) +
                  '?alt=json&max-results=50&_cb=' + Date.now();

    fetch(feedUrl, { cache: 'no-cache' })
      .then(function(res) {
        if (!res.ok) throw new Error('Failed to fetch series feed: ' + res.status);
        return res.json();
      })
      .then(function(data) {
        var entries = (data && data.feed && data.feed.entry) ? data.feed.entry : [];
        if (!entries.length) return;

        var posts = [];
        entries.forEach(function(entry) {
          var postUrl = '';
          if (entry.link) {
            for (var i = 0; i < entry.link.length; i++) {
              if (entry.link[i].rel === 'alternate') {
                postUrl = entry.link[i].href;
                break;
              }
            }
          }

          var title = entry.title ? (entry.title.$t || '') : '';
          var published = entry.published ? (entry.published.$t || '') : '';

          if (postUrl && title) {
            posts.push({
              title: title,
              url: postUrl,
              published: published
            });
          }
        });

        // Sort CHRONOLOGICALLY (oldest = Part 1)
        posts.sort(function(a, b) {
          return new Date(a.published) - new Date(b.published);
        });

        try {
          sessionStorage.setItem(cacheKey, JSON.stringify(posts));
        } catch(e) {}

        renderSeries(posts, seriesTitle, currentUrl, currentPath);
      })
      .catch(function(err) {
        console.warn('Series feed error:', err);
      });
  }

  function renderSeries(posts, seriesTitle, currentUrl, currentPath) {
    if (!posts || !posts.length) return;

    // Register all series URLs globally so Related Posts can exclude them
    window.SERIES_POST_URLS = posts.map(function(p) { return p.url; });
    try {
      window.dispatchEvent(new CustomEvent('seriesLoaded', { detail: { urls: window.SERIES_POST_URLS } }));
    } catch(e) {}

    // Find active post index
    var activeIdx = -1;
    for (var i = 0; i < posts.length; i++) {
      var pUrl = posts[i].url;
      try {
        var pPath = new URL(pUrl, window.location.origin).pathname;
        if (pPath === currentPath || currentPath.endsWith(pPath) || pPath.endsWith(currentPath)) {
          activeIdx = i;
          break;
        }
      } catch(e) {
        if (pUrl === currentUrl || currentUrl.indexOf(pUrl) > -1) {
          activeIdx = i;
          break;
        }
      }
    }

    // Fallback: match by post title in document.title if pathname matching didn't catch
    if (activeIdx === -1) {
      var docTitle = document.title || '';
      for (var j = 0; j < posts.length; j++) {
        if (posts[j].title && docTitle.indexOf(posts[j].title.slice(0, 25)) > -1) {
          activeIdx = j;
          break;
        }
      }
    }

    if (activeIdx === -1) activeIdx = 0;

    var currentPartNum = activeIdx + 1;
    var totalParts = posts.length;
    var progressPct = Math.round((currentPartNum / totalParts) * 100);

    var lang = getLang();
    var i18n = SERIES_I18N[lang] || SERIES_I18N.vi;

    // 1. Render Top Pill
    var pillContainer = document.getElementById('series-header-pill-container');
    if (pillContainer) {
      pillContainer.style.display = 'block';
      pillContainer.innerHTML =
        '<div class="series-header-pill-wrapper">' +
          '<a href="#series-roadmap-box" class="series-header-pill" id="series-pill-trigger">' +
            '<span class="series-pill-kicker">' + i18n.seriesBadge + '</span>' +
            '<span class="series-pill-divider">/</span>' +
            '<span class="series-pill-title" data-bilingual="true">' + seriesTitle + '</span>' +
            '<span class="series-pill-badge">' + i18n.partLabel + ' ' + currentPartNum + '/' + totalParts + '</span>' +
            '<span class="series-pill-action">' + i18n.viewRoadmap + '</span>' +
          '</a>' +
        '</div>';

      var pillTrigger = document.getElementById('series-pill-trigger');
      if (pillTrigger) {
        pillTrigger.addEventListener('click', function(e) {
          e.preventDefault();
          var target = document.getElementById('series-roadmap-box');
          if (target) {
            target.scrollIntoView({ behavior: 'smooth', block: 'center' });
            target.style.outline = '2px solid var(--primary)';
            target.style.transition = 'outline 0.3s ease';
            setTimeout(function() { target.style.outline = 'none'; }, 2000);
          }
        });
      }
    }

    // 2. Render Bottom Roadmap Box
    var boxContainer = document.getElementById('series-roadmap-box-container');
    if (boxContainer) {
      boxContainer.style.display = 'block';

      var stepsHtml = '';
      posts.forEach(function(post, idx) {
        var partNum = ('0' + (idx + 1)).slice(-2);
        var isCurrent = (idx === activeIdx);
        var isRead = (idx < activeIdx);
        var isNext = (idx === activeIdx + 1);

        var itemClass = 'series-step-item';
        if (isCurrent) itemClass += ' is-active';
        if (isRead) itemClass += ' is-read';

        var badgeHtml = '';
        if (isCurrent) {
          badgeHtml = '<span class="series-step-badge badge-active"><span class="badge-dot"></span>' + i18n.currentReading + '</span>';
        } else if (isRead) {
          badgeHtml = '<span class="series-step-badge badge-read">✓ ' + i18n.readStatus + '</span>';
        } else if (isNext) {
          badgeHtml = '<span class="series-step-badge badge-next">' + i18n.nextChapterBadge + '</span>';
        } else {
          badgeHtml = '<span class="series-step-badge badge-upcoming">' + i18n.upcomingBadge + '</span>';
        }

        var nodeContent = isRead ? '✓' : partNum;
        var tag = isCurrent ? 'div' : 'a';
        var hrefAttr = isCurrent ? '' : ' href="' + post.url + '"';
        var cleanTitle = (post.title || '').replace(/"/g, '&quot;');

        stepsHtml +=
          '<' + tag + ' class="' + itemClass + '"' + hrefAttr + ' title="' + cleanTitle + '">' +
            '<div class="series-step-node">' + nodeContent + '</div>' +
            '<div class="series-step-content">' +
              '<span class="series-step-title" data-bilingual="true" title="' + cleanTitle + '">' + post.title + '</span>' +
              badgeHtml +
            '</div>' +
          '</' + tag + '>';
      });

      // Navigation Spotlight Cards
      var navHtml = '';
      var hasPrev = (activeIdx > 0);
      var hasNext = (activeIdx < posts.length - 1);

      if (hasPrev || hasNext) {
        var navClass = 'series-nav-spotlight';
        if (hasPrev && !hasNext) navClass += ' only-prev';
        if (!hasPrev && hasNext) navClass += ' only-next';

        navHtml += '<div class="' + navClass + '">';

        if (hasPrev) {
          var prevPost = posts[activeIdx - 1];
          var cleanPrevTitle = (prevPost.title || '').replace(/"/g, '&quot;');
          navHtml +=
            '<a class="series-nav-card series-nav-prev" href="' + prevPost.url + '" title="' + cleanPrevTitle + '">' +
              '<span class="series-nav-kicker">← ' + i18n.prevKicker + '</span>' +
              '<span class="series-nav-title" data-bilingual="true" title="' + cleanPrevTitle + '">' + prevPost.title + '</span>' +
            '</a>';
        }

        if (hasNext) {
          var nextPost = posts[activeIdx + 1];
          var cleanNextTitle = (nextPost.title || '').replace(/"/g, '&quot;');
          navHtml +=
            '<a class="series-nav-card series-nav-next" href="' + nextPost.url + '" title="' + cleanNextTitle + '">' +
              '<div class="series-nav-next-content">' +
                '<span class="series-nav-kicker">' + i18n.nextKicker + ' →</span>' +
                '<span class="series-nav-title" data-bilingual="true" title="' + cleanNextTitle + '">' + nextPost.title + '</span>' +
              '</div>' +
              '<div class="series-nav-arrow-bubble">' +
                '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg>' +
              '</div>' +
            '</a>';
        }

        navHtml += '</div>';
      } else if (posts.length > 1 && activeIdx === posts.length - 1) {
        navHtml = '<div class="series-completed-msg"><span>🏆</span> ' + i18n.completedSeriesMsg + '</div>';
      }

      boxContainer.innerHTML =
        '<div class="series-roadmap-box" id="series-roadmap-box">' +
          '<div class="series-box-header">' +
            '<div class="series-box-top-row">' +
              '<div class="series-box-kicker-group">' +
                '<span class="series-box-icon">✦</span>' +
                '<span class="series-box-kicker">' + i18n.seriesBadge + '</span>' +
              '</div>' +
              '<div class="series-box-progress-pill">' +
                '<span class="series-progress-count">' + currentPartNum + ' / ' + totalParts + '</span>' +
                '<span class="series-progress-label">' + i18n.completedRatio + '</span>' +
              '</div>' +
            '</div>' +
            '<h4 class="series-box-title" data-bilingual="true">' + seriesTitle + '</h4>' +
            '<div class="series-progress-track">' +
              '<div class="series-progress-fill" style="width: ' + progressPct + '%;"></div>' +
            '</div>' +
          '</div>' +
          '<div class="series-steps-list">' + stepsHtml + '</div>' +
          navHtml +
        '</div>';
    }

    if (window.applyBilingualElements) {
      window.applyBilingualElements();
    }
  }

  window.addEventListener('languageChanged', function() {
    initPostSeries();
  });

  document.addEventListener('DOMContentLoaded', initPostSeries);
})();


/**
 * FOOTER SCRIPTS — Modular Footer (FEAT-MODULAR-FOOTER-V3)
 * - Scroll-to-top button
