  function formatSeriesTitle(rawLabel) {
    if (!rawLabel) return '';
    let name = rawLabel.replace(/^series:\s*/i, '').trim();
    if (name.indexOf('-') > -1 && name.indexOf(' ') === -1) {
      name = name.split('-').map(word => {
        return word.charAt(0).toUpperCase() + word.slice(1);
      }).join(' ');
    }
    return name;
  }

  async function fetchAvailableSeriesLabels(forceRefresh = false) {
    const cacheKey = CACHE_PREFIX + 'series_catalog_v2';
    if (!forceRefresh) {
      const cached = readCache(cacheKey);
      if (cached && Array.isArray(cached) && cached.length > 0) {
        return cached;
      }
    }

    let foundLabels = [];
    try {
      const blogUrl = getBlogBaseUrl();
      const cbParam = forceRefresh ? `&_cb=${Date.now()}` : '';
      const res = await fetch(`${blogUrl}/feeds/posts/summary?alt=json&max-results=500${cbParam}`);
      if (res.ok) {
        const data = await res.json();
        if (data && data.feed) {
          if (data.feed.category && Array.isArray(data.feed.category)) {
            data.feed.category.forEach(c => {
              if (c && c.term && /^series:/i.test(c.term)) foundLabels.push(c.term);
            });
          }
          if (data.feed.entry && Array.isArray(data.feed.entry)) {
            data.feed.entry.forEach(entry => {
              if (entry.category && Array.isArray(entry.category)) {
                entry.category.forEach(c => {
                  if (c && c.term && /^series:/i.test(c.term)) foundLabels.push(c.term);
                });
              }
            });
          }
        }
      }
    } catch (_) {}

    const labelMap = new Map();
    foundLabels.forEach(lbl => {
      const norm = lbl.trim().toLowerCase();
      if (!labelMap.has(norm)) labelMap.set(norm, lbl.trim());
    });

    let seriesLabels = Array.from(labelMap.values());
    if (seriesLabels.length === 0) {
      seriesLabels = Object.keys(MOCK_SERIES_CATALOG);
    }

    writeCache(cacheKey, seriesLabels);
    return seriesLabels;
  }

  async function fetchSeriesPosts(seriesLabel) {
    let posts = [];
    try {
      posts = await fetchSingleLabelFeed(seriesLabel, 50, 'summary');
    } catch (_) {
      posts = [];
    }

    if (!posts || posts.length === 0) {
      const mock = MOCK_SERIES_CATALOG[seriesLabel] || Object.values(MOCK_SERIES_CATALOG)[0];
      if (mock && mock.posts) {
        posts = mock.posts.map(p => Object.assign({}, p));
      }
    }

    // Sắp xếp theo trình tự thời gian (Tập 1 -> Tập N)
    posts.sort((a, b) => new Date(a.published) - new Date(b.published));
    return posts;
  }

  function renderSeriesPattern(posts, opts = {}) {
    const lang = (() => { try { return localStorage.getItem('user_lang') || 'vi'; } catch(e) { return 'vi'; } })();
    const limit = opts.limit || 5;
    const seriesLabel = opts.seriesLabel || (posts[0] && (posts[0].labels || []).find(l => /^series:/i.test(l))) || '';
    const seriesTitle = opts.seriesTitle || formatSeriesTitle(seriesLabel);
    const totalParts = posts.length;
    const displayedPosts = posts.slice(0, limit);

    // Compact count text: e.g. "3/10 bài viết | 3/10 topics"
    const rawCountBadge = `${displayedPosts.length}/${totalParts} bài viết | ${displayedPosts.length}/${totalParts} topics`;
    const parsedCountBadge = window.parseBilingualText ? window.parseBilingualText(rawCountBadge, lang) : `${displayedPosts.length}/${totalParts} bài viết`;

    // Tooltip text for extension icon button
    const rawTooltip = `Xem tất cả | View all`;
    const parsedTooltip = window.parseBilingualText ? window.parseBilingualText(rawTooltip, lang) : `Xem tất cả`;
    const seriesSearchUrl = buildLabelUrl(seriesLabel, seriesTitle);

    const itemsHtml = displayedPosts.map((post, index) => {
      const numStr = String(index + 1).padStart(2, '0');
      const thumb = (opts.showThumb !== false && post.thumbnail)
        ? optimizeThumbnail(post.thumbnail, 's160-c')
        : '';
      const parsedPostTitle = window.parseBilingualText ? window.parseBilingualText(post.title, lang) : post.title.split('|')[0].trim();
      const aiType = extractAITypes(post.labels || []);
      const aiHtml = aiType ? (' • ' + renderAIInlineBadge(aiType)) : '';

      return `
        <li>
          <a class="popular-post-item" href="${escapeHtml(post.url)}"${aiType ? ` data-ai-type="${aiType}"` : ''}>
            <span class="popular-post-num">${numStr}</span>
            ${thumb ? `<img class="popular-post-thumb" src="${escapeHtml(thumb)}" alt="${escapeHtml(post.title)}" loading="lazy" width="60" height="60"/>` : '<div class="popular-post-thumb sp-no-thumb"></div>'}
            <div class="popular-post-info">
              <div class="popular-post-title" data-bilingual="true" data-raw-label="${escapeHtml(post.title)}">${escapeHtml(parsedPostTitle)}</div>
              <div class="popular-post-date">📅 ${escapeHtml(post.dateFormatted)}${aiHtml}</div>
            </div>
          </a>
        </li>`;
    }).join('');

    return `
      <div class="series-showcase-summary">
        <div class="series-showcase-name-group" title="${escapeHtml(seriesTitle)}">
          <span class="series-showcase-book-icon" aria-hidden="true">📖</span>
          <strong class="series-showcase-name" data-bilingual="true" data-raw-label="${escapeHtml(seriesTitle)}">${escapeHtml(seriesTitle)}</strong>
        </div>
        <div class="series-showcase-meta-right">
          <span class="series-showcase-count-pill" data-bilingual="true" data-raw-label="${escapeHtml(rawCountBadge)}">${escapeHtml(parsedCountBadge)}</span>
        </div>
      </div>
      <ul class="popular-posts-list series-showcase-list">
        ${itemsHtml}
      </ul>
      <div class="series-showcase-footer">
        <a href="${escapeHtml(seriesSearchUrl)}" class="series-showcase-ext-btn" title="${escapeHtml(parsedTooltip)}" aria-label="${escapeHtml(parsedTooltip)}">
          <span class="series-ext-label" data-bilingual="true" data-raw-label="${escapeHtml(rawTooltip)}">${escapeHtml(parsedTooltip)}</span>
          <svg class="series-ext-svg" viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
            <polyline points="13 17 18 12 13 7"></polyline>
            <polyline points="6 17 11 12 6 7"></polyline>
          </svg>
        </a>
      </div>
    `;
  }

  async function renderSeriesWidget(container, opts) {
    const { widgetTitle, limit, specifiedLabel } = opts;

    let availableSeries = await fetchAvailableSeriesLabels();
    container._availableSeries = availableSeries;

    let targetLabel = specifiedLabel;
    if (!targetLabel || !/^series:/i.test(targetLabel)) {
      const randIdx = Math.floor(Math.random() * availableSeries.length);
      targetLabel = availableSeries[randIdx];
      container._currentSeriesIndex = randIdx;
    } else {
      container._currentSeriesIndex = availableSeries.indexOf(targetLabel);
      if (container._currentSeriesIndex === -1) container._currentSeriesIndex = 0;
    }

    await renderSeriesContainerView(container, targetLabel, limit, widgetTitle);
  }

  async function renderSeriesContainerView(container, seriesLabel, limit, widgetTitle) {
    const posts = await fetchSeriesPosts(seriesLabel);
    const seriesTitle = formatSeriesTitle(seriesLabel);
    const lang = (() => { try { return localStorage.getItem('user_lang') || 'vi'; } catch(e) { return 'vi'; } })();
    const shuffleRawLabel = 'Đổi tuyến bài | Switch series';
    const shuffleRawTitle = 'Khám phá chuyên đề khác | Discover another series';
    const shuffleParsedLabel = window.parseBilingualText ? window.parseBilingualText(shuffleRawLabel, lang) : 'Đổi tuyến bài';
    const shuffleParsedTitle = window.parseBilingualText ? window.parseBilingualText(shuffleRawTitle, lang) : 'Khám phá chuyên đề khác';

    const shuffleBtnHtml = `
      <button type="button" class="series-shuffle-btn" aria-label="${escapeHtml(shuffleParsedLabel)}" title="${escapeHtml(shuffleParsedTitle)}">
        <svg class="series-shuffle-svg" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
          <polyline points="16 3 21 3 21 8"></polyline>
          <line x1="4" y1="20" x2="21" y2="3"></line>
          <polyline points="21 16 21 21 16 21"></polyline>
          <line x1="15" y1="15" x2="21" y2="21"></line>
          <line x1="4" y1="4" x2="9" y2="9"></line>
        </svg>
      </button>
    `;

    const bodyHtml = renderSeriesPattern(posts, {
      limit,
      seriesLabel,
      seriesTitle,
      showThumb: container.dataset.showThumbnail !== 'false'
    });

    container.innerHTML = buildWidgetShell(
      widgetTitle || '📚 Chuyên Đề | 📚 Series Topic',
      '',
      seriesLabel,
      'series',
      bodyHtml,
      posts,
      shuffleBtnHtml
    );

    // Gắn sự kiện cho nút Shuffle
    const shuffleBtn = container.querySelector('.series-shuffle-btn');
    if (shuffleBtn) {
      shuffleBtn.addEventListener('click', async function (e) {
        e.preventDefault();
        e.stopPropagation();

        shuffleBtn.classList.add('is-spinning');
        let available = container._availableSeries || [];

        // Nếu chỉ có 1 series hoặc rỗng, thử quét lại feed (forceRefresh) để cập nhật nếu có series mới
        if (available.length <= 1) {
          try {
            available = await fetchAvailableSeriesLabels(true);
            container._availableSeries = available;
          } catch (_) {}
        }

        if (available.length > 1) {
          let nextIdx = ((container._currentSeriesIndex || 0) + 1) % available.length;
          if (available[nextIdx] === seriesLabel) {
            nextIdx = (nextIdx + 1) % available.length;
          }
          container._currentSeriesIndex = nextIdx;
          const nextLabel = available[nextIdx];

          const bodyEl = container.querySelector('.series-widget-body, .sp-widget-body');
          if (bodyEl) {
            bodyEl.style.opacity = '0.35';
            bodyEl.style.transition = 'opacity 0.25s ease';
          }

          await renderSeriesContainerView(container, nextLabel, limit, widgetTitle);

          const newBody = container.querySelector('.series-widget-body, .sp-widget-body');
          if (newBody) {
            newBody.style.opacity = '1';
          }
        } else {
          // Blog chỉ có 1 series: tạo hiệu ứng reload nhẹ và dừng xoay
          const bodyEl = container.querySelector('.series-widget-body, .sp-widget-body');
          if (bodyEl) {
            bodyEl.style.opacity = '0.4';
            bodyEl.style.transition = 'opacity 0.2s ease';
            setTimeout(() => {
              bodyEl.style.opacity = '1';
            }, 300);
          }
        }

        setTimeout(function () {
          const btn = container.querySelector('.series-shuffle-btn');
          if (btn) btn.classList.remove('is-spinning');
        }, 500);

        if (window.applyBilingualElements) {
          window.applyBilingualElements();
        }
      });
    }

    if (window.applyBilingualElements) {
      window.applyBilingualElements();
    }
  }

  /* ═══════════════════════════════════════════════════════════════
     DATA FETCHERS
     ═══════════════════════════════════════════════════════════════ */

  /* ── Fetch nhiều nhãn song song + deduplication ─────────────── */
  async function fetchMultiLabelPosts(labels, limit, sort, feedType = 'summary') {
    // Nạp song song tất cả nhãn
    const promises = labels.map(label => fetchSingleLabelFeed(label, limit + 5, feedType));
    const results  = await Promise.all(promises);

    // Gộp
    const allPosts = results.flat();

    // Khử trùng lặp theo URL
    const uniqueMap = new Map();
    allPosts.forEach(post => {
      if (!uniqueMap.has(post.url)) uniqueMap.set(post.url, post);
    });
    let merged = Array.from(uniqueMap.values());

    // Sắp xếp
    if (sort === 'random') {
      merged.sort(() => Math.random() - 0.5);
    } else {
      // latest (mặc định)
      merged.sort((a, b) => new Date(b.published) - new Date(a.published));
    }

    return merged.slice(0, limit);
  }

  /* ── Fetch 1 nhãn qua Blogger JSON Feed API ─────────────────── */
  async function fetchSingleLabelFeed(label, count, feedType = 'summary') {
    const cacheKey = CACHE_PREFIX + 'label_' + encodeURIComponent(label) + '_' + count + '_' + feedType;
    const cached   = readCache(cacheKey);
    if (cached) return cached;

    try {
      const encodedLabel = encodeURIComponent(label);
      const blogUrl      = getBlogBaseUrl();
      const url          = `${blogUrl}/feeds/posts/${feedType}/-/${encodedLabel}?alt=json&max-results=${count}&orderby=published`;

      const res  = await fetch(url);
      if (!res.ok) {
        if (label !== label.toLowerCase()) {
          return await fetchSingleLabelFeed(label.toLowerCase(), count, feedType);
        }
        return [];
      }
      const json = await res.json();

      let posts = parseFeedEntries(json.feed ? json.feed.entry : []);
      // Nếu không có bài nào và tên nhãn chứa chữ hoa, thử tìm biến thể chữ thường
      if (posts.length === 0 && label !== label.toLowerCase()) {
        const lowerPosts = await fetchSingleLabelFeed(label.toLowerCase(), count, feedType);
        if (lowerPosts && lowerPosts.length > 0) return lowerPosts;
      }

      writeCache(cacheKey, posts);
      return posts;
    } catch (e) {
      if (label !== label.toLowerCase()) {
        try {
          return await fetchSingleLabelFeed(label.toLowerCase(), count, feedType);
        } catch (_) {}
      }
      return [];
    }
  }

  /* ── Fetch bài viết mới nhất toàn blog (Fallback tự động) ─────── */
  async function fetchLatestPosts(count, feedType = 'summary') {
    const cacheKey = CACHE_PREFIX + 'latest_' + count + '_' + feedType;
    const cached   = readCache(cacheKey);
    if (cached) return cached;

    try {
      const blogUrl = getBlogBaseUrl();
      const url     = `${blogUrl}/feeds/posts/${feedType}?alt=json&max-results=${count}&orderby=published`;
      const res     = await fetch(url);
      if (!res.ok) return [];
      const json    = await res.json();
      const posts   = parseFeedEntries(json.feed ? json.feed.entry : []);
      writeCache(cacheKey, posts);
      return posts;
    } catch (e) {
      return [];
    }
  }

  /* ── Fetch Popular Posts (lượt xem nhiều nhất) ──────────────── */
  async function fetchPopularPosts(limit, timeRange, labelFilter, feedType = 'summary') {
    const cacheKey = CACHE_PREFIX + 'popular_' + timeRange + '_' + limit + '_' + feedType;
    const cached   = readCache(cacheKey);
    if (cached) {
      return filterByLabels(cached, labelFilter, limit);
    }

    try {
      const blogUrl = getBlogBaseUrl();
      let url;
      if (labelFilter) {
        const labelList    = splitLabels(labelFilter);
        const encodedLabel = encodeURIComponent(labelList[0]);
        url = `${blogUrl}/feeds/posts/${feedType}/-/${encodedLabel}?alt=json&max-results=20&orderby=updated`;
      } else {
        url = `${blogUrl}/feeds/posts/${feedType}?alt=json&max-results=20&orderby=updated`;
      }

      const res  = await fetch(url);
      if (!res.ok) return [];
      const json = await res.json();

      const posts = parseFeedEntries(json.feed ? json.feed.entry : []);
      writeCache(cacheKey, posts);
      return posts.slice(0, limit);
    } catch (e) {
      return [];
    }
  }

  /* ── Fetch các bài viết theo danh sách URL chỉ định ─────────── */
  async function fetchHandpickedPosts(rawUrls) {
    const urls = rawUrls.split(',')
      .map(u => u.trim())
      .filter(Boolean);

    const blogBase = getBlogBaseUrl();

    const promises = urls.map(async (relOrAbs) => {
      const absUrl   = relOrAbs.startsWith('http') ? relOrAbs : blogBase + relOrAbs;
      const feedUrl  = absUrl.includes('?')
        ? absUrl + '&alt=json'
        : absUrl + '?alt=json';
      const cacheKey = CACHE_PREFIX + 'post_' + encodeURIComponent(absUrl);
      const cached   = readCache(cacheKey);
      if (cached) return cached;

      try {
        const res  = await fetch(feedUrl);
        const json = await res.json();
        const entry = json.entry;
        if (!entry) return null;
        const post = parseEntry(entry);
        writeCache(cacheKey, post);
        return post;
      } catch {
        return null;
      }
    });

    const results = await Promise.all(promises);
    return results.filter(Boolean);
  }

  /* ═══════════════════════════════════════════════════════════════
     PARSER HELPERS
     ═══════════════════════════════════════════════════════════════ */

  function parseFeedEntries(entries) {
    if (!Array.isArray(entries)) return [];
    return entries.map(parseEntry).filter(Boolean);
  }

  function parseEntry(entry) {
    try {
      // URL bài viết
      const links  = entry.link || [];
      const altLink = links.find(l => l.rel === 'alternate');
      const url    = altLink ? altLink.href : '';

      // Tiêu đề
      const title = entry.title ? (entry.title.$t || '') : '';

      // Ảnh thumbnail
      let thumbnail = '';
      if (entry.content && entry.content.$t) {
        const imgMatch = entry.content.$t.match(/<img[^>]+src=["']([^"']+)["']/i);
        if (imgMatch) thumbnail = imgMatch[1];
      }
      if (!thumbnail && entry.media$thumbnail) {
        thumbnail = entry.media$thumbnail.url || '';
      }

      // Snippet
      let snippet = '';
      if (entry.summary) {
        snippet = (entry.summary.$t || '').replace(/<[^>]+>/g, '').trim();
      } else if (entry.content) {
        snippet = (entry.content.$t || '').replace(/<[^>]+>/g, '').trim().substring(0, 200);
      }

      // Ngày đăng
      const published = entry.published ? entry.published.$t : '';
      const dateFormatted = formatDate(published);

      // Labels
      const labels = (entry.category || []).map(c => c.term || '');

      const rawContent = entry.content ? (entry.content.$t || '') : '';

      return { url, title, thumbnail, snippet, published, dateFormatted, labels, rawContent };
    } catch {
      return null;
    }
  }

  /* ═══════════════════════════════════════════════════════════════
     UTILS
     ═══════════════════════════════════════════════════════════════ */

  /** Trích xuất nhãn chuyên mục thường đầu tiên (loại trừ @ và ai:) */
  function extractNormalCategory(labels) {
    if (!labels || !labels.length) return '';
    for (var i = 0; i < labels.length; i++) {
      var raw = (labels[i] || '').trim();
      var lower = raw.toLowerCase();
      if (!raw.startsWith('@') && !lower.startsWith('ai:') && !lower.startsWith('ai-') && !lower.startsWith('series:')) {
        return raw;
      }
    }
    return '';
  }

  /** Lọc ký tự @ # _ ~ khỏi tên nhãn trước khi hiển thị */
  function formatLabelName(raw) {
    if (!raw) return '';
    return decodeURIComponent(String(raw)).replace(/^[@#_~]+/, '').trim();
  }

  /** Trích xuất loại AI từ mảng labels; trả về key hoặc null với thứ tự ưu tiên */
  function extractAITypes(labels) {
    var aiTypeContent = null;
    var aiTypeProduct = null;
    var priority = ['ai:generated', 'ai:contributed', 'ai:assisted', 'ai:translated'];
    if (labels && labels.length) {
      for (var i = 0; i < labels.length; i++) {
        var raw = labels[i] || '';
        var lower = raw.toLowerCase().replace(/-/g, ':');
        if (lower.startsWith('ai:')) {
          if (lower === 'ai:product') {
             aiTypeProduct = lower;
          } else {
             if (priority.indexOf(lower) !== -1) {
               if (!aiTypeContent || priority.indexOf(lower) < priority.indexOf(aiTypeContent)) {
                 aiTypeContent = lower;
               }
             }
          }
        }
      }
    }
    var res = [];
    if (aiTypeContent) res.push(aiTypeContent);
    if (aiTypeProduct) res.push(aiTypeProduct);
    return res.length > 0 ? res.join(',') : null;
  }

  function renderAIInlineBadge(aiTypeString) {
    if (!aiTypeString) return '';
    var aiTypes = aiTypeString.split(',').filter(Boolean);
    var html = '';
    var icons = { 'ai:assisted': '✨', 'ai:contributed': '✨', 'ai:product': '🤖', 'ai:generated': '⚡', 'ai:translated': '🌐' };
    for (var i = 0; i < aiTypes.length; i++) {
      var type = aiTypes[i];
      var icon = icons[type] || '✨';
      html += '<span class="ai-badge ai-badge-inline" data-ai-type="' + type + '" data-ai-variant="inline">' +
        '<span class="ai-badge-icon">' + icon + '</span>' +
        '<span class="ai-badge-label">AI</span>' +
      '</span>';
    }
    return html;
  }

  function renderAIStandardBadge(aiTypeString, lang) {
    if (!aiTypeString) return '';
    var aiTypes = aiTypeString.split(',').filter(Boolean);
    var html = '';
    var icons = { 'ai:assisted': '✨', 'ai:contributed': '✨', 'ai:product': '🤖', 'ai:generated': '⚡', 'ai:translated': '🌐' };
    var labels = {
      'ai:assisted':    { vi: 'Hỗ trợ bởi AI',   en: 'AI-Assisted'   },
      'ai:contributed': { vi: 'Đóng góp bởi AI', en: 'AI-Contributed' },
      'ai:product':     { vi: 'Sản phẩm AI',     en: 'AI Product'     },
      'ai:generated':   { vi: 'Tạo bởi AI',      en: 'AI-Generated'   },
      'ai:translated':  { vi: 'Dịch bởi AI',     en: 'AI-Translated'  }
    };
    for (var i = 0; i < aiTypes.length; i++) {
      var type = aiTypes[i];
      var icon = icons[type] || '✨';
      var labelCfg = labels[type] || labels['ai:assisted'];
      var labelText = (lang === 'en') ? labelCfg.en : labelCfg.vi;
      html += '<span class="ai-badge ai-badge-standard" data-ai-type="' + type + '" data-ai-variant="standard">' +
        '<span class="ai-badge-icon">' + icon + '</span>' +
        '<span class="ai-badge-label">' + labelText + '</span>' +
      '</span>';
    }
    return html;
  }

  /** Tách chuỗi nhãn "A, B, C" thành mảng */
  function splitLabels(raw) {
    if (!raw) return [];
    const cleaned = raw.replace(/^(labels?|nhãn)\s*:\s*/i, '');
    return cleaned.split(',').map(l => l.trim()).filter(Boolean);
  }

  /** Tối ưu kích thước ảnh Blogger (Retina-safe) */
  function optimizeThumbnail(url, size) {
    if (!url) return '';
    return url
      .replace(/\/(s[0-9]+|w[0-9]+-h[0-9]+)(-c)?\//, '/' + size + '/')
      .replace(/=(s[0-9]+|w[0-9]+-h[0-9]+)(-c)?([a-zA-Z0-9-]*)$/i, '=' + size);
  }

  /** Format ngày ISO thành DD/MM/YYYY */
  function formatDate(iso) {
    if (!iso) return '';
    try {
      const d = new Date(iso);
      const dd   = String(d.getDate()).padStart(2, '0');
      const mm   = String(d.getMonth() + 1).padStart(2, '0');
      const yyyy = d.getFullYear();
      return `${dd}/${mm}/${yyyy}`;
    } catch { return ''; }
  }

  /** Lấy base URL của blog hiện tại */
  function getBlogBaseUrl() {
    return window.location.protocol + '//' + window.location.host;
  }

  /** Build URL trang nhãn (lọc @ cho URL, kèm tiêu đề hiển thị nếu có) */
  function buildLabelUrl(label, title) {
    if (!label) return '/';
    const blogBase = getBlogBaseUrl();
    let url = `${blogBase}/search/label/${encodeURIComponent(label)}`;
    if (title) {
      url += `?title=${encodeURIComponent(title)}`;
    }
    return url;
  }

  /** Lọc bài viết theo danh sách nhãn (OR logic) */
  function filterByLabels(posts, rawLabels, limit) {
    if (!rawLabels) return posts.slice(0, limit);
    const labels = splitLabels(rawLabels);
    const filtered = posts.filter(p =>
      p.labels && p.labels.some(l => labels.includes(l))
    );
    return (filtered.length > 0 ? filtered : posts).slice(0, limit);
  }

  /** Escape HTML để tránh XSS */
  function escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }

  /* ═══════════════════════════════════════════════════════════════
     SESSION STORAGE CACHE
     ═══════════════════════════════════════════════════════════════ */

  function readCache(key) {
    try {
      const raw = sessionStorage.getItem(key);
      if (!raw) return null;
      const { data, ts } = JSON.parse(raw);
      if (Date.now() - ts > CACHE_TTL) {
        sessionStorage.removeItem(key);
        return null;
      }
      return data;
    } catch { return null; }
  }

  function writeCache(key, data) {
    try {
      sessionStorage.setItem(key, JSON.stringify({ data, ts: Date.now() }));
    } catch { /* Quota exceeded — bỏ qua */ }
  }

  /* ═══════════════════════════════════════════════════════════════
     ANCHOR SCROLL HIGHLIGHT
     Khi URL chứa #widget-{slug}, cuộn mượt + kích hoạt pulse
     ═══════════════════════════════════════════════════════════════ */
  function initAnchorHighlight() {
    function handleHash(hash) {
      if (!hash) return;
      const el = document.querySelector(hash);
      if (el && el.classList.contains('special-posts-widget')) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        el.classList.add('sp-anchor-highlight');
        setTimeout(() => el.classList.remove('sp-anchor-highlight'), 1800);
      }
    }

    // Xử lý hash lúc trang load
    if (window.location.hash) {
      // Đợi widget render xong
      setTimeout(() => handleHash(window.location.hash), 600);
    }

    // Xử lý khi hash thay đổi (bấm link trong trang)
    window.addEventListener('hashchange', () => handleHash(window.location.hash));
  }

})();


/* ==========================================
   AI TRANSPARENCY SYSTEM — FEAT-AI-TRANSPARENCY-V1
   Spec: specs/AI_TRANSPARENCY_SPECIFICATION.md

   Chức năng:
   - Nhận diện nhãn ai:assisted / ai:product / ai:generated
   - Render 4 biến thể badge: full, standard, micro, inline
   - Render Khung Thông Cáo Minh Bạch (Disclosure Box) ở đầu bài
   - Hỗ trợ song ngữ VI/EN, tự động cập nhật khi languageChanged
   - Hoàn toàn độc lập, không ảnh hưởng đến filter/category logic
   ========================================== */
(function () {
  'use strict';

  /* ─── Cấu hình nhãn AI ─────────────────────────────────────── */
  var AI_TYPES = {
    'ai:assisted':    { icon: '✨', vi: 'Hỗ trợ bởi AI',   en: 'AI-Assisted'   },
    'ai:contributed': { icon: '✨', vi: 'Đóng góp bởi AI', en: 'AI-Contributed' },
    'ai:product':     { icon: '🤖', vi: 'Sản phẩm AI',   en: 'AI Product'     },
    'ai:generated':   { icon: '⚡', vi: 'Tạo bởi AI',    en: 'AI-Generated'   },
    'ai:translated':  { icon: '🌐', vi: 'Dịch bởi AI',   en: 'AI-Translated'  },
  };

  /* Nội dung Khung Thông Cáo Minh Bạch */
  var DISCLOSURE_TEXT = {
    'ai:assisted': {
      vi: 'Bài viết này được thực hiện với sự hỗ trợ của Trí tuệ Nhân tạo (AI) trong quá trình nghiên cứu và sắp xếp thông tin. Mục đích nhằm mang đến cho bạn đọc những tài liệu tham khảo đa dạng và phong phú hơn. Bạn hãy cân nhắc và thận trọng khi sử dụng thông tin.',
      en: 'This article was created with the assistance of Artificial Intelligence (AI) tools during the research and organization process. The aim is to offer readers more diverse and rich reference materials. Please use discretion and caution when applying this information.',
    },
    'ai:contributed': {
      vi: 'Bài viết này được thực hiện với sự đóng góp và hỗ trợ của công cụ Trí tuệ Nhân tạo (AI) trong quá trình nghiên cứu và xây dựng nội dung. Mục đích nhằm mang đến cho bạn đọc thông tin tham khảo đa chiều và khách quan. Bạn hãy cân nhắc và thận trọng khi sử dụng thông tin.',
      en: 'This article was created with the contribution and assistance of Artificial Intelligence (AI) tools during the research and content creation process. The goal is to provide readers with multi-dimensional and objective reference information. Please use discretion and caution when applying this information.',
    },
    'ai:product': {
      vi: 'Bài viết này là đánh giá, trải nghiệm thực tế của tác giả về một sản phẩm hoặc công cụ AI. Mọi nhận xét đều dựa trên trải nghiệm cá nhân, không bị ảnh hưởng bởi nhà sản xuất.',
      en: 'This article is an honest review and personal experience of an AI product or tool. All opinions are based on personal use and are independent from the product makers.',
    },
    'ai:generated': {
      vi: 'Nội dung bài viết này được khởi tạo hoàn toàn bởi các công cụ Trí tuệ Nhân tạo (AI). Tác giả chia sẻ lại nhằm mục đích mang đến một góc nhìn công nghệ để bạn đọc tham khảo thêm. Bạn hãy cân nhắc và thận trọng khi sử dụng thông tin.',
      en: 'The content of this article was entirely generated by Artificial Intelligence (AI) tools. It is shared here to provide an additional tech-driven perspective for reference purposes. Please use discretion and caution when applying this information.',
    },
    'ai:translated': {
      vi: 'Bản dịch tiếng Anh của bài viết này được thực hiện bởi Trí tuệ Nhân tạo (AI) để hỗ trợ bạn đọc quốc tế. Tác giả không đảm bảo độ chính xác tuyệt đối của bản dịch so với bản gốc tiếng Việt.',
      en: 'The English translation of this article was generated by Artificial Intelligence (AI) tools to assist international readers. The author does not guarantee the absolute accuracy of the translation compared to the original Vietnamese text.',
    },
  };

  /* ─── Nhận diện ngôn ngữ hiện tại ──────────────────────────── */
  function getCurrentLang() {
    try {
      return localStorage.getItem('user_lang') || 'vi';
    } catch (e) {
      return 'vi';
    }
  }

  /* ─── Chuẩn hóa nhãn AI (không phân biệt hoa thường, hỗ trợ dấu gạch ngang) */
  function normalizeAILabel(str) {
    if (!str) return '';
    return str.toLowerCase().replace(/-/g, ':');
  }

  /* ─── Phát hiện loại AI từ chuỗi nhãn đơn ─────────────────── */
  function detectAIType(labelStr) {
    var normalized = normalizeAILabel(labelStr.trim());
    // Khớp trực tiếp
    if (AI_TYPES[normalized]) return normalized;
    // Khớp từng key
    var keys = Object.keys(AI_TYPES);
    for (var i = 0; i < keys.length; i++) {
      if (normalized.indexOf(keys[i].replace(':', ':')) === 0 ||
          normalized.indexOf(keys[i].replace(':', '-')) === 0) {
        return keys[i];
      }
    }
    return null;
  }

  /* ─── Phát hiện loại AI từ mảng nhãn ───────────────────────── */
  function extractAITypesFromLabels(labels) {
    if (!labels || !labels.length) return null;
    var foundContent = null;
    var foundProduct = null;
    var priority = ['ai:generated', 'ai:product', 'ai:contributed', 'ai:assisted', 'ai:translated'];
    for (var i = 0; i < labels.length; i++) {
      var raw = (typeof labels[i] === 'string') ? labels[i] : (labels[i].name || '');
      var type = detectAIType(raw);
      if (type) {
        if (type === 'ai:product') {
          foundProduct = type;
        } else {
          if (!foundContent || priority.indexOf(type) < priority.indexOf(foundContent)) {
            foundContent = type;
          }
        }
      }
    }
    var res = [];
    if (foundContent) res.push(foundContent);
    if (foundProduct) res.push(foundProduct);
    return res.length > 0 ? res.join(',') : null;
  }

  /* ─── Render Badge HTML ─────────────────────────────────────── */
  /**
   * @param {string} type     - 'ai:contributed' | 'ai:product' | 'ai:generated'
   * @param {string} variant  - 'full' | 'standard' | 'micro' | 'inline'
   * @param {string} lang     - 'vi' | 'en'
   * @returns {string} HTML string
   */
  function renderAIBadge(type, variant, lang) {
    type = detectAIType(type) || type;
    var cfg = AI_TYPES[type];
    if (!cfg) return '';

    var label = (lang === 'en') ? cfg.en : cfg.vi;
    var icon  = cfg.icon;
    var displayAttr = (type === 'ai:translated' && lang === 'vi') ? ' style="display: none;"' : '';

    if (variant === 'inline') {
      return (
        '<span class="ai-badge ai-badge-inline" data-ai-type="' + type + '" data-ai-variant="inline"' + displayAttr + '>' +
          '<span class="ai-badge-icon">' + icon + '</span>' +
          '<span class="ai-badge-label">AI</span>' +
        '</span>'
      );
    }

    if (variant === 'micro') {
      return (
        '<span class="ai-badge ai-badge-micro" data-ai-type="' + type + '" data-ai-variant="micro"' + displayAttr + '>' +
          '<span class="ai-badge-icon">' + icon + '</span>' +
          '<span class="ai-badge-label">AI</span>' +
        '</span>'
      );
    }

    if (variant === 'full') {
      return (
        '<button type="button" class="ai-badge ai-badge-full" data-ai-type="' + type + '" data-ai-variant="full" aria-expanded="false"' + displayAttr + '>' +
          '<span class="ai-badge-icon">' + icon + '</span>' +
          '<span class="ai-badge-label">' + label + '</span>' +
          '<span class="ai-badge-chevron">▾</span>' +
        '</button>'
      );
    }

    // standard (default)
    return (
      '<span class="ai-badge ai-badge-standard" data-ai-type="' + type + '" data-ai-variant="standard"' + displayAttr + '>' +
        '<span class="ai-badge-icon">' + icon + '</span>' +
        '<span class="ai-badge-label">' + label + '</span>' +
      '</span>'
    );
  }

  /* ─── Render Disclosure Box HTML ────────────────────────────── */
  function renderDisclosureBox(type, lang) {
    type = detectAIType(type) || type;
    var cfg  = AI_TYPES[type];
    var disc = DISCLOSURE_TEXT[type];
    if (!cfg || !disc) return '';

    var label    = (lang === 'en') ? cfg.en : cfg.vi;
    var bodyText = (lang === 'en') ? disc.en : disc.vi;
    var titleVI  = '✦ THÔNG CÁO MINH BẠCH VỀ NỘI DUNG';
    var titleEN  = '✦ AI TRANSPARENCY DISCLOSURE';
    var title    = (lang === 'en') ? titleEN : titleVI;
    var learnVI  = 'ℹ️ Tìm hiểu thêm về Chính sách AI của chúng tôi »';
    var learnEN  = 'ℹ️ Learn more about our AI Policy »';
    var learnTxt = (lang === 'en') ? learnEN : learnVI;
    var toggleVI = 'Xem chi tiết';
    var toggleEN = 'Details';
    var toggleTxt = (lang === 'en') ? toggleEN : toggleVI;
    var displayAttr = (type === 'ai:translated' && lang === 'vi') ? ' style="display: none;"' : '';

    return (
      '<div class="ai-disclosure-box" data-ai-type="' + type + '" id="ai-disclosure-box-' + type.replace(':', '-') + '"' + displayAttr + '>' +
        '<div class="ai-disclosure-header" id="ai-disclosure-header-' + type.replace(':', '-') + '" role="button" tabindex="0" aria-expanded="false" aria-controls="ai-disclosure-body-' + type.replace(':', '-') + '">' +
          '<div class="ai-disclosure-title">' +
            '<span class="ai-disclosure-icon">' + cfg.icon + '</span>' +
            '<span class="ai-disclosure-title-text" data-vi="' + titleVI + '" data-en="' + titleEN + '">' + title + '</span>' +
          '</div>' +
          '<button type="button" class="ai-disclosure-toggle" aria-controls="ai-disclosure-body-' + type.replace(':', '-') + '">' +
            '<span class="ai-disclosure-toggle-text" data-vi="' + toggleVI + '" data-en="' + toggleEN + '">' + toggleTxt + '</span>' +
            '<span class="ai-disclosure-toggle-icon">▾</span>' +
          '</button>' +
        '</div>' +
        '<div class="ai-disclosure-body" id="ai-disclosure-body-' + type.replace(':', '-') + '">' +
          '<div class="ai-disclosure-text">' +
            '<p data-vi="' + escapeAttr(disc.vi) + '" data-en="' + escapeAttr(disc.en) + '">' + escapeHtml(bodyText) + '</p>' +
            '<a href="#" class="ai-disclosure-learn-more" data-vi="' + escapeAttr(learnVI) + '" data-en="' + escapeAttr(learnEN) + '">' + escapeHtml(learnTxt) + '</a>' +
          '</div>' +
        '</div>' +
      '</div>'
    );
  }

  /* ─── Cập nhật ngôn ngữ tất cả badges đang hiển thị ────────── */
  function updateAllBadgesLanguage(lang) {
    // Cập nhật standard và full badge labels
    var badges = document.querySelectorAll('.ai-badge[data-ai-type][data-ai-variant]');
    badges.forEach(function (badge) {
      var type    = badge.getAttribute('data-ai-type');
      var variant = badge.getAttribute('data-ai-variant');
      var cfg     = AI_TYPES[type];
      if (!cfg) return;

      if (type === 'ai:translated') {
        badge.style.display = (lang === 'vi') ? 'none' : '';
      }

      var labelEl = badge.querySelector('.ai-badge-label');
      if (!labelEl) return;

      if (variant === 'full' || variant === 'standard') {
        labelEl.textContent = (lang === 'en') ? cfg.en : cfg.vi;
      }
      // micro/inline: luôn hiển thị "AI" — không đổi
    });

    // Cập nhật Disclosure Box
    var boxes = document.querySelectorAll('.ai-disclosure-box');
    boxes.forEach(function (box) {
      var boxType = box.getAttribute('data-ai-type');
      if (boxType === 'ai:translated') {
        box.style.display = (lang === 'vi') ? 'none' : '';
      }

      // Title
      var titleEl = box.querySelector('.ai-disclosure-title-text');
      if (titleEl) {
        titleEl.textContent = (lang === 'en') ? titleEl.getAttribute('data-en') : titleEl.getAttribute('data-vi');
      }
      // Toggle text
      var toggleEl = box.querySelector('.ai-disclosure-toggle-text');
      if (toggleEl) {
        toggleEl.textContent = (lang === 'en') ? toggleEl.getAttribute('data-en') : toggleEl.getAttribute('data-vi');
      }
      // Body paragraph
      var bodyEl = box.querySelector('.ai-disclosure-text p');
      if (bodyEl) {
        bodyEl.textContent = (lang === 'en') ? bodyEl.getAttribute('data-en') : bodyEl.getAttribute('data-vi');
      }
      // Learn more link
      var learnEl = box.querySelector('.ai-disclosure-learn-more');
      if (learnEl) {
        learnEl.textContent = (lang === 'en') ? learnEl.getAttribute('data-en') : learnEl.getAttribute('data-vi');
      }
    });
  }

  /* ─── ĐIỂM TÍCH HỢP 1: Single Post Header (Full Badge + Disclosure Box) */
  function injectSinglePostBadge() {
    var container = document.getElementById('single-post-wrapper');
    if (container) {
      if (container.style.display === 'none') return;
    } else {
      container = document.querySelector('.single-post-container');
      if (!container) return;
    }

    // Đọc ai type từ data attribute trên container hoặc bài viết
    var rawType = container.getAttribute('data-ai-type');
    if (!rawType) {
      var childWithAI = container.querySelector('[data-ai-type]');
      if (childWithAI) rawType = childWithAI.getAttribute('data-ai-type');
    }
    if (!rawType) {
      var rawLabels = container.querySelectorAll('.post-raw-label');
      var allLabels = [];
      for (var i = 0; i < rawLabels.length; i++) {
        allLabels.push(rawLabels[i].textContent);
      }
      var t = extractAITypesFromLabels(allLabels);
      if (t) { rawType = t; container.setAttribute('data-ai-type', t); }
    }
    if (!rawType) return;
    var aiTypes = rawType.split(',').filter(function(t) { return AI_TYPES[t]; });
    if (!aiTypes.length) return;

    var lang = getCurrentLang();

    // (A) Inject Full Badge vào author-meta-details
    var metaDetails = container.querySelector('.author-meta-details');
    if (metaDetails && !metaDetails.querySelector('.ai-badge-full')) {
      for (var k = 0; k < aiTypes.length; k++) {
        var aiType = aiTypes[k];
        var sepEl = document.createElement('span');
        sepEl.textContent = '•';
        metaDetails.appendChild(sepEl);

        var wrapper = document.createElement('span');
        wrapper.innerHTML = renderAIBadge(aiType, 'full', lang);
        metaDetails.appendChild(wrapper);
        initFullBadgeToggle(wrapper.querySelector('.ai-badge-full'));
      }
    }

    // (B) Inject Disclosure Box sau .post-body
    var postBody = container.querySelector('.post-body');

    if (postBody && !container.querySelector('.ai-disclosure-box')) {
      // Loop ngược để chèn vào sau postBody đúng thứ tự (vì insertBefore)
      for (var k = aiTypes.length - 1; k >= 0; k--) {
        var aiType = aiTypes[k];
        var discEl = document.createElement('div');
        discEl.innerHTML = renderDisclosureBox(aiType, lang);
        postBody.parentNode.insertBefore(discEl.firstChild, postBody.nextSibling);
      }
      initDisclosureBoxToggle();
    }
  }

  /* Toggle Full Badge → mở/đóng Disclosure Box */
  function initFullBadgeToggle(badgeEl) {
    if (!badgeEl) return;
    badgeEl.addEventListener('click', function () {
      var box = document.getElementById('ai-disclosure-box-' + badgeEl.getAttribute('data-ai-type').replace(':', '-'));
      if (!box) return;
      var isOpen = box.classList.toggle('is-open');
      badgeEl.setAttribute('aria-expanded', isOpen);
      badgeEl.classList.toggle('is-open', isOpen);
    });
  }

  /* Toggle Disclosure Box header */
  function initDisclosureBoxToggle() {
    var headers = document.querySelectorAll('.ai-disclosure-header');
    if (!headers.length) return;
    headers.forEach(function(header) {
      if (header.dataset.hasToggleInit) return;
      header.dataset.hasToggleInit = 'true';

    function toggle() {
      var box = header.closest('.ai-disclosure-box');
      if (!box) return;
      var isOpen = box.classList.toggle('is-open');
      header.setAttribute('aria-expanded', isOpen);
    }

    header.addEventListener('click', toggle);
    header.addEventListener('keydown', function (e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          toggle();
        }
      });
    });
  }

  /* ─── ĐIỂM TÍCH HỢP 2: Post Cards Feed (Standard Badge) ────── */
  function injectPostCardBadges() {
    var lang = getCurrentLang();
    var cards = document.querySelectorAll('.post-card');
    cards.forEach(function (card) {
      var rawType = card.getAttribute('data-ai-type');
      if (!rawType) {
        var rawLabels = card.querySelectorAll('.post-raw-label');
        var allLabels = [];
        for (var i = 0; i < rawLabels.length; i++) {
          allLabels.push(rawLabels[i].textContent);
        }
        var t = extractAITypesFromLabels(allLabels);
        if (t) { rawType = t; card.setAttribute('data-ai-type', t); }
      }
      if (!rawType) return;
      var aiTypes = rawType.split(',').filter(function(t) { return AI_TYPES[t]; });
      if (!aiTypes.length) return;

      var meta = card.querySelector('.post-card-meta');
      if (!meta) return;
      if (meta.querySelector('.ai-badge-standard')) return;

      for (var k = 0; k < aiTypes.length; k++) {
        var aiType = aiTypes[k];
        var sepEl = document.createElement('span');
        sepEl.textContent = '•';

        var wrapper = document.createElement('span');
        wrapper.style.display = 'inline-flex';
        wrapper.innerHTML = renderAIBadge(aiType, 'standard', lang);

        meta.appendChild(sepEl);
        meta.appendChild(wrapper);
      }
    });
  }

  /* ─── ĐIỂM TÍCH HỢP 3: Archive Timeline (Micro Badge) ──────── */
  function injectTimelineBadges() {
    var lang = getCurrentLang();
    // archive-page.js đã render .archive-post-card với data-ai-type
    var cards = document.querySelectorAll('.archive-post-card[data-ai-type]');
    cards.forEach(function (card) {
      var rawType = card.getAttribute('data-ai-type');
      var aiTypes = rawType.split(',').filter(function(t) { return AI_TYPES[t]; });
      if (!aiTypes.length) return;
      if (card.querySelector('.ai-badge-micro')) return;

      var titleEl = card.querySelector('.archive-post-card-title');
      if (!titleEl) return;

      for (var k = aiTypes.length - 1; k >= 0; k--) {
        var aiType = aiTypes[k];
        var wrapper = document.createElement('span');
        wrapper.innerHTML = renderAIBadge(aiType, 'micro', lang);
        titleEl.after(wrapper.firstChild);
      }
    });
  }

  /* ─── ĐIỂM TÍCH HỢP 4: Special Post Widgets (Inline Badge) ─── */
  function injectWidgetBadges() {
    var lang = getCurrentLang();

    // Ranked widget: inject vào .sp-ranked-date
    var rankedDates = document.querySelectorAll('.sp-ranked-item[data-ai-type] .sp-ranked-date');
    rankedDates.forEach(function (dateEl) {
      var item = dateEl.closest('[data-ai-type]');
      if (!item) return;
      var rawType = item.getAttribute('data-ai-type');
      var aiTypes = rawType.split(',').filter(function(t) { return AI_TYPES[t]; });
      if (!aiTypes.length) return;
      if (dateEl.querySelector('.ai-badge-inline')) return;

      for (var k = 0; k < aiTypes.length; k++) {
        var aiType = aiTypes[k];
        var sepEl = document.createElement('span');
        sepEl.textContent = ' • ';
        var wrapper = document.createElement('span');
        wrapper.innerHTML = renderAIBadge(aiType, 'inline', lang);
        dateEl.appendChild(sepEl);
        dateEl.appendChild(wrapper.firstChild);
      }
    });

    // Spotlight widget: inject vào .sp-spotlight-meta
    var spotlightMetas = document.querySelectorAll('.sp-spotlight-card[data-ai-type] .sp-spotlight-meta');
    spotlightMetas.forEach(function (metaEl) {
      var card = metaEl.closest('[data-ai-type]');
      if (!card) return;
      var rawType = card.getAttribute('data-ai-type');
      var aiTypes = rawType.split(',').filter(function(t) { return AI_TYPES[t]; });
      if (!aiTypes.length) return;
      if (metaEl.querySelector('.ai-badge-standard')) return;

      for (var k = 0; k < aiTypes.length; k++) {
        var aiType = aiTypes[k];
        var wrapper = document.createElement('span');
        wrapper.innerHTML = renderAIBadge(aiType, 'standard', lang);
        metaEl.appendChild(wrapper.firstChild);
      }
    });

    // Digest widget: inject vào .sp-digest-timestamp
    var digestTimestamps = document.querySelectorAll('.sp-digest-item[data-ai-type] .sp-digest-timestamp');
    digestTimestamps.forEach(function (tsEl) {
      var item = tsEl.closest('[data-ai-type]');
      if (!item) return;
      var rawType = item.getAttribute('data-ai-type');
      var aiTypes = rawType.split(',').filter(function(t) { return AI_TYPES[t]; });
      if (!aiTypes.length) return;
      if (tsEl.querySelector('.ai-badge-inline')) return;

      for (var k = 0; k < aiTypes.length; k++) {
        var aiType = aiTypes[k];
        var sepEl = document.createElement('span');
        sepEl.textContent = ' • ';
        var wrapper = document.createElement('span');
        wrapper.innerHTML = renderAIBadge(aiType, 'inline', lang);
        tsEl.appendChild(sepEl);
        tsEl.appendChild(wrapper.firstChild);
      }
    });
  }

  /* ─── Khởi chạy toàn bộ injection ─────────────────────────── */
  function initAITransparency() {
    injectSinglePostBadge();
    injectPostCardBadges();
    injectTimelineBadges();
    injectWidgetBadges();
  }

  /* ─── Lắng nghe sự kiện languageChanged từ bilingual.js ─────── */
  window.addEventListener('languageChanged', function (e) {
    var lang = (e.detail && e.detail.lang) ? e.detail.lang : getCurrentLang();
    updateAllBadgesLanguage(lang);
  });

  /* ─── MutationObserver: tự động inject khi DOM thay đổi ─────── */
  // (dùng cho archive-page.js và special-posts.js render bất đồng bộ)
  var _observer = null;
  function startObserver() {
    if (_observer) return;
    _observer = new MutationObserver(function (mutations) {
      var needsInject = mutations.some(function (m) {
        return m.addedNodes.length > 0;
      });
      if (needsInject) {
        injectTimelineBadges();
        injectWidgetBadges();
        injectPostCardBadges();
      }
    });
    _observer.observe(document.body, { childList: true, subtree: true });
  }

  /* ─── Utility: escape ────────────────────────────────────────── */
  function escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');
  }

  function escapeAttr(str) {
    if (!str) return '';
    return String(str).replace(/"/g, '&quot;').replace(/'/g, '&#039;');
  }

  /* ─── Export API cho các module khác ───────────────────────── */
  window.AITransparency = {
    detectAIType: detectAIType,
    extractAITypesFromLabels: extractAITypesFromLabels,
    renderAIBadge: renderAIBadge,
    renderDisclosureBox: renderDisclosureBox,
    injectTimelineBadges: injectTimelineBadges,
    injectWidgetBadges: injectWidgetBadges,
    injectPostCardBadges: injectPostCardBadges,
    reinject: initAITransparency,
  };

  /* ─── Khởi động ─────────────────────────────────────────────── */
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () {
      initAITransparency();
      startObserver();
    });
  } else {
    initAITransparency();
    startObserver();
  }

})();


/**
 * HOMEPAGE INTERLEAVED WIDGETS & MAIN FEED CONTROLLER
 * Feature: FEAT-HOMEPAGE-INTERLEAVED-WIDGETS-V1
 * 
 * Manages 3-tier main feed layout:
 * 1. Above Feed Hero (#main-above-feed) - Auto hides on Page 2+
 * 2. In-Feed Interleaved (#main-in-feed-section) - Auto-injects after post 3 (or data-insert-after)
 * 3. Pre-Pagination Action Zone (#main-pre-pagination-section) - Positioned immediately above .blog-pager
 */

(function () {
  'use strict';

  function initPostCardsProcessing() {
    var isHomepage = document.body.classList.contains('view-homepage');

    // 1. Xử lý các thẻ bài viết trên feed (Trang chủ / Danh mục)
    document.querySelectorAll('.post-card').forEach(function(card) {
      var rawLabels = card.querySelectorAll('.post-raw-label');
      if (rawLabels.length > 0) {
        var allFeatureAt = true;
        var firstNormalLabel = null;
        var detectedAiTypeContent = null;
        var detectedAiTypeProduct = null;
        var priority = ['ai:generated', 'ai:contributed', 'ai:assisted', 'ai:translated'];

        rawLabels.forEach(function(lblEl) {
          var name = lblEl.textContent.trim();
          var url = lblEl.getAttribute('data-url');
          if (name.startsWith('@')) {
            // Nhãn tính năng cho widget (@Quote, @Tiêu điểm, @Nổi bật, @Điểm tin)
          } else if (name.toLowerCase().startsWith('ai:') || name.toUpperCase().startsWith('AI-')) {
            // Nhãn AI minh bạch - KHÔNG tính là nhãn chuyên mục thường
            var t = name.toLowerCase().replace(/-/g, ':');
            if (t === 'ai:product') {
              detectedAiTypeProduct = t;
            } else {
              if (priority.indexOf(t) !== -1) {
                if (!detectedAiTypeContent || priority.indexOf(t) < priority.indexOf(detectedAiTypeContent)) {
                  detectedAiTypeContent = t;
                }
              }
            }
          } else if (name.toLowerCase().startsWith('series:')) {
            // Nhãn Series Navigator - Không dùng làm badge chuyên mục nhưng không phải nhãn ẩn @
            allFeatureAt = false;
          } else {
            allFeatureAt = false;
            if (!firstNormalLabel) firstNormalLabel = { name: name, url: url };
          }
        });

        // ══ QUY TẮC VÀNG: Ẩn bài viết "độc quyền @" khỏi Trang chủ ══
        // Bài viết chỉ có nhãn @ (và có thể kèm ai:) mà không có nhãn chuyên mục thường -> Ẩn khỏi Trang chủ
        if (allFeatureAt && !firstNormalLabel && isHomepage) {
          card.style.display = 'none';
          card.classList.add('is-exclusive-feature-hidden');
          return;
        }

        // Đảm bảo huy hiệu chuyên mục hiển thị sạch sẽ
        var badge = card.querySelector('.post-badge');
        if (badge) {
          var currentLang = (typeof localStorage !== 'undefined' && localStorage.getItem('user_lang')) || 'vi';
          if (firstNormalLabel) {
            badge.setAttribute('data-raw-label', firstNormalLabel.name);
            badge.setAttribute('data-bilingual', 'true');
            badge.textContent = window.parseBilingualText ? window.parseBilingualText(firstNormalLabel.name, currentLang) : firstNormalLabel.name.split('|')[0].trim();
            badge.href = firstNormalLabel.url;
            badge.style.display = '';
          } else {
            // Không có nhãn chuyên mục thường (chỉ có nhãn @ hoặc hệ thống) -> Ẩn badge để giao diện sạch sẽ
            badge.style.display = 'none';
          }
        }

        var detectedAiTypeArr = [];
        if (detectedAiTypeContent) detectedAiTypeArr.push(detectedAiTypeContent);
        if (detectedAiTypeProduct) detectedAiTypeArr.push(detectedAiTypeProduct);
        var detectedAiType = detectedAiTypeArr.length ? detectedAiTypeArr.join(',') : null;

        // Tự động gắn data-ai-type để ai-transparency.js kích hoạt badge
        if (detectedAiType) {
          card.setAttribute('data-ai-type', detectedAiType);
        }
      }

      // Trích xuất đoạn tóm tắt bài viết (Snippet) tự động nếu data:post.snippet rỗng
      var snippetEl = card.querySelector('.post-card-snippet');
      var bodySourceEl = card.querySelector('.post-body-snippet-source');
      var rawBodyText = '';
      if (bodySourceEl) {
        var viEl = bodySourceEl.querySelector('[data-lang="vi"]');
        var enEl = bodySourceEl.querySelector('[data-lang="en"]');

        // Cắt gọn một đoạn text (tối đa 140 ký tự)
        function truncateText(txt) {
          if (!txt) return '';
          txt = txt.replace(/\s+/g, ' ').trim();
          if (txt.length <= 140) return txt;
          var cut = txt.lastIndexOf(' ', 140);
          return txt.substring(0, cut === -1 ? 140 : cut) + '...';
        }

        if (viEl && enEl) {
          // Xử lý song ngữ dùng data-lang
          var viText = truncateText(viEl.textContent || viEl.innerText);
          var enText = truncateText(enEl.textContent || enEl.innerText);
          rawBodyText = viText + ' | ' + enText;
        } else {
          // Xử lý text thông thường hoặc dùng cú pháp "|" truyền thống
          rawBodyText = (bodySourceEl.textContent || bodySourceEl.innerText || '').replace(/\s+/g, ' ').trim();
          if (rawBodyText.indexOf('|') === -1) {
             rawBodyText = truncateText(rawBodyText);
          }
        }
      }

      // Luôn ghi đè snippet bằng rawBodyText (vì data:post.snippet của Blogger hay bị cụt chữ và làm hỏng cú pháp song ngữ)
      if (snippetEl && rawBodyText) {
        snippetEl.textContent = rawBodyText;
        snippetEl.setAttribute('data-bilingual', 'true');
        snippetEl.setAttribute('data-raw-label', rawBodyText);
        var currentLang = (typeof localStorage !== 'undefined' && localStorage.getItem('user_lang')) || 'vi';
        if (window.parseBilingualText) {
          snippetEl.textContent = window.parseBilingualText(rawBodyText, currentLang);
        } else {
          var parts = rawBodyText.split('|');
          snippetEl.textContent = currentLang === 'en' && parts.length > 1 ? parts[1].trim() : parts[0].trim();
        }
      }

      // Tính toán số phút đọc ước tính theo dung lượng từ thực tế
      var readTimeEl = card.querySelector('.read-time-est');
      if (readTimeEl && rawBodyText) {
        var words = rawBodyText.split(/\s+/).filter(Boolean).length;
        var mins = Math.max(1, Math.ceil(words / 200));
        var currentLang = (typeof localStorage !== 'undefined' && localStorage.getItem('user_lang')) || 'vi';
        readTimeEl.setAttribute('data-raw-label', mins + ' phút đọc | ' + mins + ' min read');
        readTimeEl.textContent = (currentLang === 'en') ? (mins + ' min read') : (mins + ' phút đọc');
      }

      if (bodySourceEl) {
        bodySourceEl.remove(); // Dọn dẹp DOM sạch sẽ sau khi bóc tách
      }
    });

    // 2. Xử lý trang chi tiết bài viết (Single Post View)
    var singleContainer = document.querySelector('.single-post-container');
    if (singleContainer) {
      var rawLabelsSingle = singleContainer.querySelectorAll('.post-raw-label');
      if (rawLabelsSingle.length > 0) {
        var normalLabelSingle = null;
        var aiTypeSingleContent = null;
        var aiTypeSingleProduct = null;
        var prioritySingle = ['ai:generated', 'ai:contributed', 'ai:assisted', 'ai:translated'];

        rawLabelsSingle.forEach(function(lblEl) {
          var name = lblEl.textContent.trim();
          var url = lblEl.getAttribute('data-url');
          if (name.startsWith('@')) {
            // bỏ qua
          } else if (name.toLowerCase().startsWith('ai:') || name.toUpperCase().startsWith('AI-')) {
            var t = name.toLowerCase().replace(/-/g, ':');
            if (t === 'ai:product') {
              aiTypeSingleProduct = t;
            } else {
              if (prioritySingle.indexOf(t) !== -1) {
                if (!aiTypeSingleContent || prioritySingle.indexOf(t) < prioritySingle.indexOf(aiTypeSingleContent)) {
                  aiTypeSingleContent = t;
                }
              }
            }
          } else if (name.toLowerCase().startsWith('series:')) {
            // bỏ qua không lấy làm breadcrumb chuyên mục
          } else {
            if (!normalLabelSingle) normalLabelSingle = { name: name, url: url };
          }
        });

        var breadcrumbCat = singleContainer.querySelector('.breadcrumb-category-link');
        if (breadcrumbCat) {
          var currentLang = (typeof localStorage !== 'undefined' && localStorage.getItem('user_lang')) || 'vi';
          if (normalLabelSingle) {
            breadcrumbCat.setAttribute('data-raw-label', normalLabelSingle.name);
            breadcrumbCat.setAttribute('data-bilingual', 'true');
            breadcrumbCat.textContent = window.parseBilingualText ? window.parseBilingualText(normalLabelSingle.name, currentLang) : normalLabelSingle.name.split('|')[0].trim();
            breadcrumbCat.href = normalLabelSingle.url;
          } else {
            breadcrumbCat.style.display = 'none';
            var nextSep = breadcrumbCat.nextElementSibling;
            if (nextSep && nextSep.classList.contains('separator')) nextSep.style.display = 'none';
          }
        }

        var aiTypeSingleArr = [];
        if (aiTypeSingleContent) aiTypeSingleArr.push(aiTypeSingleContent);
        if (aiTypeSingleProduct) aiTypeSingleArr.push(aiTypeSingleProduct);
        var aiTypeSingle = aiTypeSingleArr.length ? aiTypeSingleArr.join(',') : null;
        if (aiTypeSingle) {
          singleContainer.setAttribute('data-ai-type', aiTypeSingle);
        }
      }
    }
  }

  function initInFeedInterleaving() {
    const inFeedSection = document.getElementById('main-in-feed-section');
    if (!inFeedSection) return;

    // Loại bỏ widget thừa HTML99 / About Author nếu Blogger tự chèn vào inFeedSection
    const unwantedBio = inFeedSection.querySelectorAll('#HTML99, #hidden-author-bio-config');
    unwantedBio.forEach(el => el.remove());

    // 1. Kiểm tra xem có widget hoặc nội dung không
    const hasWidgets = inFeedSection.querySelectorAll('.widget, .special-posts-widget, .infeed-custom-content').length > 0 ||
                       (inFeedSection.children.length > 0 && inFeedSection.textContent.trim().length > 0);

    if (!hasWidgets) {
      inFeedSection.style.display = 'none';
      return;
    }

    // 2. Lấy danh sách các bài viết hiển thị (loại trừ các bài độc quyền @ đã ẩn)
    const feedContainer = document.getElementById('posts-feed-container') || document.querySelector('.posts-feed');
    if (!feedContainer) {
      inFeedSection.style.display = 'none';
      return;
    }

    const posts = Array.from(feedContainer.querySelectorAll('.post-card')).filter(function(card) {
      return card.style.display !== 'none';
    });
    if (!posts || posts.length === 0) {
      inFeedSection.style.display = 'none';
      return;
    }

    // 3. Xác định vị trí chèn (Mặc định: sau bài số 3 -> index 2)
    let insertAfterIndex = 2;
    const customConfigWidget = inFeedSection.querySelector('[data-insert-after]');
    if (customConfigWidget) {
      const customNum = parseInt(customConfigWidget.dataset.insertAfter, 10);
      if (!isNaN(customNum) && customNum > 0) {
        insertAfterIndex = customNum - 1;
      }
    }

    // Đảm bảo không vượt quá tổng số bài hiện có
    const targetIndex = Math.min(insertAfterIndex, posts.length - 1);

    // 4. Di chuyển mượt mà vào giữa luồng
    posts[targetIndex].after(inFeedSection);
    inFeedSection.classList.add('in-feed-active');
    inFeedSection.style.display = 'block';
  }

  function initPrePaginationSection() {
    const prePagination = document.getElementById('main-pre-pagination-section');
    if (!prePagination) return;

    // Kiểm tra widget / nội dung thực sự (loại trừ trường hợp widget rỗng hoặc chỉ có khoảng trắng / placeholder)
    const adSlot = prePagination.querySelector('.adsense-slot');
    const hasActiveAds = adSlot && adSlot.textContent.trim().length > 0 && !adSlot.textContent.includes('📣');
    const hasOtherWidgets = prePagination.querySelector('ins.adsbygoogle, iframe, script, img, form, .special-posts-widget, .newsletter-card, .pre-pagination-card');
    const hasTextContent = !adSlot && prePagination.children.length > 0 && prePagination.textContent.trim().length > 0;

    const hasWidgets = hasActiveAds || hasOtherWidgets || hasTextContent;

    if (!hasWidgets) {
      prePagination.style.display = 'none';
      return;
    }

    // Tìm nút phân trang blog-pager
    const blogPager = document.querySelector('.blog-pager');
    if (blogPager && blogPager.parentElement) {
      blogPager.before(prePagination);
      prePagination.style.display = 'block';
    } else {
      prePagination.style.display = 'block';
    }
  }

  function initAboveFeedSection() {
    const aboveFeed = document.getElementById('main-above-feed');
    if (!aboveFeed) return;

    // Kiểm tra nếu là trang chi tiết bài viết (Single Post) hoặc trang lưu trữ (Archive)
    const singlePostWrapper = document.getElementById('single-post-wrapper');
    const isSinglePost = document.body.classList.contains('view-single') ||
                         (singlePostWrapper && singlePostWrapper.style.display !== 'none');

    const archiveWrapper = document.getElementById('archive-page-wrapper');
    const isArchivePage = document.body.classList.contains('view-archive') ||
                          (archiveWrapper && archiveWrapper.style.display !== 'none');

    if (isSinglePost || isArchivePage) {
      aboveFeed.style.display = 'none';
      return;
    }

    // Kiểm tra nếu là Trang 2 trở đi (Page 2+)
    const urlParams = new URLSearchParams(window.location.search);
    const isPaged = urlParams.has('updated-max') ||
                    urlParams.get('page') === '2' ||
                    urlParams.get('paged') === '2' ||
                    document.body.classList.contains('is-paged') ||
                    document.body.classList.contains('view-paged');

    if (isPaged) {
      aboveFeed.style.display = 'none';
      return;
    }

    // Kiểm tra rỗng
    const hasWidgets = aboveFeed.querySelectorAll('.widget, .special-posts-widget, .hero-spotlight').length > 0 ||
                       (aboveFeed.children.length > 0 && aboveFeed.textContent.trim().length > 0);

    if (!hasWidgets) {
      aboveFeed.style.display = 'none';
      return;
    }

    aboveFeed.style.display = 'block';
  }

  function initProfileCoverSection() {
    const coverWrapper = document.getElementById('cover-image-wrapper');
    const avatarImg = document.getElementById('profile-avatar-img');
    const nameEl = document.getElementById('profile-author-name');
    const bioEl = document.getElementById('profile-author-bio');

    if (!coverWrapper) return;

    function syncSiteAvatars(avatarUrl) {
      if (!avatarUrl) return;
      document.querySelectorAll('.author-avatar-sm, .author-bio-avatar, .sidebar-about-avatar').forEach(function(img) {
        if (!img.src || img.src.includes('data:image') || img.src.includes('unsplash')) {
          img.src = avatarUrl;
        }
      });
    }

    // 1. Ảnh Banner tải lên trực tiếp từ máy tính qua widget Image1
    const uploadedBannerEl = document.getElementById('profile-uploaded-banner');
    if (uploadedBannerEl) {
      const bannerText = uploadedBannerEl.textContent.trim();
      if (/^https?:\/\/[^\s]+/i.test(bannerText)) {
        coverWrapper.style.backgroundImage = `url("${bannerText}")`;
      }
    }

    // 2. Ảnh Avatar tải lên trực tiếp từ máy tính qua widget Image2
    const uploadedAvatarEl = document.getElementById('profile-uploaded-avatar');
    if (uploadedAvatarEl) {
      const avatarText = uploadedAvatarEl.textContent.trim();
      if (/^https?:\/\/[^\s]+/i.test(avatarText)) {
        if (avatarImg) avatarImg.src = avatarText;
        try { localStorage.setItem('cached_author_avatar', avatarText); } catch(e){}
        syncSiteAvatars(avatarText);
      }
    }

    // Chỉ dùng Unsplash fallback khi ở môi trường Local Preview (preview.html hoặc localhost)
    const isLocalDev = window.location.protocol === 'file:' || window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';
    if (isLocalDev) {
      if (!coverWrapper.style.backgroundImage || coverWrapper.style.backgroundImage === 'none') {
        coverWrapper.style.backgroundImage = 'url("https://images.unsplash.com/photo-1432821596592-e2c18b78144f?w=1200&auto=format&fit=crop&q=80")';
      }
      if (avatarImg && (!avatarImg.src || avatarImg.src.includes('undefined') || avatarImg.src.startsWith('data:image'))) {
        avatarImg.src = 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=300&auto=format&fit=crop&q=80';
      }
    }

    // 3. Đọc cấu hình tùy chỉnh từ ô Content của widget HTML1
    const configEl = document.getElementById('profile-custom-config');
    if (!configEl) return;

    // Chỉ thay thế toàn bộ component nếu người dùng dán NGUYÊN VẸN khối .profile-cover-section từ Preview
    if (configEl.querySelector('.profile-cover-section')) {
      const coverSection = document.getElementById('profile-cover-section');
      if (coverSection) {
        coverSection.outerHTML = configEl.querySelector('.profile-cover-section').outerHTML;
      }
      return;
    }

    // Nếu người dùng chèn ảnh qua nút "Chèn hình ảnh" của Blogger trong ô Content
    const inlineImgs = configEl.querySelectorAll('img');
    if (inlineImgs.length === 1) {
      if (inlineImgs[0].src && avatarImg) {
        avatarImg.src = inlineImgs[0].src;
        try { localStorage.setItem('cached_author_avatar', inlineImgs[0].src); } catch(e){}
        syncSiteAvatars(inlineImgs[0].src);
      }
    } else if (inlineImgs.length >= 2) {
      if (inlineImgs[0].src) coverWrapper.style.backgroundImage = `url("${inlineImgs[0].src}")`;
      if (inlineImgs[1].src && avatarImg) {
        avatarImg.src = inlineImgs[1].src;
        try { localStorage.setItem('cached_author_avatar', inlineImgs[1].src); } catch(e){}
        syncSiteAvatars(inlineImgs[1].src);
      }
    }

    const rawContent = configEl.innerHTML.trim();
    if (!rawContent) return;

    const textOnly = configEl.textContent.trim();
    if (textOnly) {
      // Nếu chỉ dán mỗi link ảnh http... (ưu tiên làm Banner)
      if (/^https?:\/\/[^\s]+$/i.test(textOnly)) {
        coverWrapper.style.backgroundImage = `url("${textOnly}")`;
      } else if (/(?:banner|avatar|bio|name)\s*:/i.test(textOnly)) {
        // Cú pháp tham số: banner: https://... | avatar: https://... | bio: ... | name: ...
        const parts = textOnly.split('|').map(s => s.trim());
        parts.forEach(part => {
          if (/^banner\s*:\s*(https?:\/\/[^\s]+)/i.test(part)) {
            const url = part.match(/^banner\s*:\s*(https?:\/\/[^\s]+)/i)[1];
            coverWrapper.style.backgroundImage = `url("${url}")`;
          } else if (/^avatar\s*:\s*(https?:\/\/[^\s]+)/i.test(part)) {
            const url = part.match(/^avatar\s*:\s*(https?:\/\/[^\s]+)/i)[1];
            if (avatarImg) avatarImg.src = url;
            try { localStorage.setItem('cached_author_avatar', url); } catch(e){}
            syncSiteAvatars(url);
          } else if (/^bio\s*:\s*(.+)/i.test(part)) {
            const bio = part.match(/^bio\s*:\s*(.+)/i)[1].trim();
            if (bioEl) bioEl.textContent = bio;
          } else if (/^name\s*:\s*(.+)/i.test(part)) {
            const name = part.match(/^name\s*:\s*(.+)/i)[1].trim();
            if (nameEl) nameEl.textContent = name;
          } else if (/^https?:\/\/[^\s]+/i.test(part)) {
            coverWrapper.style.backgroundImage = `url("${part.trim()}")`;
          }
        });
      } else {
        // Người dùng gõ văn bản tự nhiên (lời giới thiệu)
        // Nếu có nhiều dòng: dòng 1 < 40 ký tự và không có dấu chấm phẩy thì là Tên, phần sau là Bio
        const lines = textOnly.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
        const lang = (typeof localStorage !== 'undefined' && localStorage.getItem('user_lang')) || 'vi';
        const parseFn = window.parseBilingualText || (t => t);

        if (lines.length > 1 && lines[0].length < 40 && !/[.,;!?]$/.test(lines[0]) && !lines[0].includes('|')) {
          if (nameEl) {
            nameEl.setAttribute('data-raw-label', lines[0]);
            nameEl.textContent = parseFn(lines[0], lang);
          }
          if (bioEl) {
            const bioText = lines.slice(1).join('\n');
            bioEl.setAttribute('data-raw-label', bioText);
            bioEl.innerHTML = parseFn(bioText, lang).replace(/\n/g, '<br/>');
          }
        } else {
          // Toàn bộ là lời giới thiệu Bio
          if (bioEl) {
            bioEl.setAttribute('data-raw-label', textOnly);
            bioEl.innerHTML = parseFn(textOnly, lang).replace(/\n/g, '<br/>');
          }
        }
      }
    }
  }

  function showToast(msg) {
    var toast = document.getElementById('theme-toast-notification');
    if (!toast) {
      toast = document.createElement('div');
      toast.id = 'theme-toast-notification';
      toast.style.cssText = 'position:fixed;bottom:2rem;right:2rem;background:#0f172a;color:#fff;padding:0.85rem 1.4rem;border-radius:999px;font-size:0.92rem;font-weight:600;box-shadow:0 10px 30px rgba(0,0,0,0.3);z-index:99999;transition:all 0.3s cubic-bezier(0.4,0,0.2,1);transform:translateY(20px);opacity:0;pointer-events:none;display:flex;align-items:center;gap:0.5rem;border:1px solid rgba(255,255,255,0.15);';
      document.body.appendChild(toast);
    }
    toast.textContent = msg;
    toast.style.transform = 'translateY(0)';
    toast.style.opacity = '1';
    clearTimeout(toast._timer);
    toast._timer = setTimeout(function() {
      toast.style.transform = 'translateY(20px)';
      toast.style.opacity = '0';
    }, 3500);
  }

  function initNewsletterActions() {
    // 1. Cuộn mượt tới khung đăng ký bản tin khi bấm nút "Nhận Bản Tin"
    document.querySelectorAll('a[href="#newsletter"], .btn-subscribe').forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.preventDefault();
        var target = document.getElementById('newsletter') || document.querySelector('.pre-pagination-newsletter, .sidebar-widget, .footer-col-newsletter');
        if (target) {
          target.scrollIntoView({ behavior: 'smooth', block: 'center' });
          var input = target.querySelector('input[type="email"]');
          if (input) {
            setTimeout(function() {
              input.focus();
              input.style.boxShadow = '0 0 0 3px rgba(37, 99, 235, 0.4)';
              setTimeout(function() { input.style.boxShadow = ''; }, 1600);
            }, 500);
          }
        }
      });
    });

    // 2. Xử lý sự kiện đăng ký bản tin (ở cả Feed, Sidebar và Footer)
    var forms = document.querySelectorAll('.pre-pagination-newsletter-form, .sidebar-newsletter-form, .newsletter-form');
    forms.forEach(function(form) {
      form.addEventListener('submit', function(e) {
        e.preventDefault();
        var input = form.querySelector('input[type="email"]');
        var btn = form.querySelector('button[type="submit"], .pre-pagination-newsletter-btn, .sidebar-submit-btn, .btn-submit');
        if (!input) return;

        var email = input.value.trim();
        var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!email || !emailRegex.test(email)) {
          input.style.borderColor = '#ef4444';
          input.focus();
          showToast('⚠️ Vui lòng nhập địa chỉ email hợp lệ!');
          setTimeout(function() { input.style.borderColor = ''; }, 2500);
          return;
        }

        // Trạng thái thành công
        var origText = btn ? btn.innerHTML : '';
        if (btn) {
          btn.disabled = true;
          btn.innerHTML = '✓ Đã Đăng Ký!';
          btn.style.backgroundColor = '#10b981';
          btn.style.borderColor = '#10b981';
          btn.style.color = '#ffffff';
        }
        input.value = '';
        showToast('🎉 Cảm ơn bạn! Đã ghi nhận email đăng ký bản tin thành công.');

        setTimeout(function() {
          if (btn) {
            btn.disabled = false;
            btn.innerHTML = origText;
            btn.style.backgroundColor = '';
            btn.style.borderColor = '';
            btn.style.color = '';
          }
        }, 4000);
      });
    });
  }

  /**
   * Đồng bộ tiêu đề trang Tìm kiếm / Nhãn:
   * 1. Đọc query param ?title= (truyền từ liên kết 'Xem tất cả' của widget)
   * 2. Fallback bảng tra cứu cho các nhãn kỹ thuật hệ thống (@quote, @tiêu điểm, @nổi bật, @điểm tin)
   * 3. Tự động áp dụng song ngữ VI/EN
   */
  function initSearchPageHeader() {
    var titleEl = document.getElementById('search-page-title');
    if (!titleEl) return;

    var params = new URLSearchParams(window.location.search);
    var customTitle = params.get('title');

    var rawLabel = (titleEl.getAttribute('data-raw-label') || titleEl.textContent || '').trim();
    var FEATURE_MAP = {
      '@quote': '☕ Góc Suy Ngẫm | ☕ Contemplation Corner',
      '@tiêu điểm': '🌟 Tiêu Điểm | Spotlight',
      '@tieu diem': '🌟 Tiêu Điểm | Spotlight',
      '@nổi bật': '🔥 Bài Viết Nổi Bật | Trending Posts',
      '@noi bat': '🔥 Bài Viết Nổi Bật | Trending Posts',
      '@điểm tin': '⚡ Điểm Tin Mỗi Ngày | Daily Digest',
      '@diem tin': '⚡ Điểm Tin Mỗi Ngày | Daily Digest'
    };

    var resolvedTitle = customTitle;
    if (!resolvedTitle && rawLabel) {
      var lower = rawLabel.toLowerCase();
      if (FEATURE_MAP[lower]) {
        resolvedTitle = FEATURE_MAP[lower];
      }
    }

    if (resolvedTitle) {
      var currentLang = (typeof localStorage !== 'undefined' && localStorage.getItem('user_lang')) || 'vi';
      titleEl.setAttribute('data-raw-label', resolvedTitle);
      titleEl.setAttribute('data-bilingual', 'true');
      titleEl.textContent = window.parseBilingualText ? window.parseBilingualText(resolvedTitle, currentLang) : resolvedTitle.split('|')[0].trim();

      try {
        var baseBlogTitle = document.title.split(/[-:|]/)[0].trim();
        var pageTitleText = resolvedTitle.split('|')[0].trim();
        document.title = pageTitleText + ' — ' + baseBlogTitle;
      } catch (e) {}
    }
  }

  function initInPostAds() {
    // 1. Kiểm tra vị trí đầu bài (In-Post Top)
    const topSlot = document.getElementById('post-ad-top-slot');
    if (topSlot) {
      const topSection = document.getElementById('post-ads-top-section');
      const globalConfig = document.getElementById('hidden-global-config');
      let customTopHtml = '';

      if (globalConfig) {
        const adTopEl = globalConfig.querySelector('.in-post-ads-config .ad-top-code');
        if (adTopEl && adTopEl.innerHTML.trim() && !adTopEl.innerHTML.includes('<!-- Mã quảng cáo đầu bài')) {
          customTopHtml = adTopEl.innerHTML.trim();
        }
      }

      if (customTopHtml) {
        topSlot.innerHTML = '<div class="adsense-slot adsense-top" aria-label="Quảng cáo">' + customTopHtml + '</div>';
      } else if (topSection) {
        const topWidget = topSection.querySelector('.widget, .adsense-slot');
        if (topWidget && (topWidget.textContent.trim().length > 0 || topWidget.children.length > 0)) {
          topSlot.appendChild(topWidget);
        }
      }
    }

    // 2. Kiểm tra vị trí cuối bài (In-Post Bottom)
    const bottomSlot = document.getElementById('post-ad-bottom-slot');
    if (bottomSlot) {
      const bottomSection = document.getElementById('post-ads-bottom-section');
      const globalConfig = document.getElementById('hidden-global-config');
      let customBottomHtml = '';

      if (globalConfig) {
        const adBottomEl = globalConfig.querySelector('.in-post-ads-config .ad-bottom-code');
        if (adBottomEl && adBottomEl.innerHTML.trim() && !adBottomEl.innerHTML.includes('<!-- Mã quảng cáo cuối bài')) {
          customBottomHtml = adBottomEl.innerHTML.trim();
        }
      }

      if (customBottomHtml) {
        topSlot && (bottomSlot.innerHTML = '<div class="adsense-slot adsense-bottom" aria-label="Quảng cáo">' + customBottomHtml + '</div>');
      } else if (bottomSection) {
        const bottomWidget = bottomSection.querySelector('.widget, .adsense-slot');
        if (bottomWidget && (bottomWidget.textContent.trim().length > 0 || bottomWidget.children.length > 0)) {
          bottomSlot.appendChild(bottomWidget);
        }
      }
    }

    // Luôn ẩn các section gốc nếu còn
    const topSection = document.getElementById('post-ads-top-section');
    if (topSection) topSection.style.display = 'none';
    const bottomSection = document.getElementById('post-ads-bottom-section');
    if (bottomSection) bottomSection.style.display = 'none';
  }

  function initHomepageInterleavedWidgets() {
    initPostCardsProcessing();
    initSearchPageHeader();
    initProfileCoverSection();
    initAboveFeedSection();
    initInFeedInterleaving();
    initPrePaginationSection();
    initInPostAds();
    initNewsletterActions();
    if (window.AITransparency && typeof window.AITransparency.reinject === 'function') {
      window.AITransparency.reinject();
    }
  }

  // Khởi chạy khi DOM sẵn sàng
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initHomepageInterleavedWidgets);
  } else {
    initHomepageInterleavedWidgets();
  }

  // Expose ra window để các module khác hoặc preview sandbox có thể kích hoạt lại khi chuyển view
  window.initHomepageInterleavedWidgets = initHomepageInterleavedWidgets;
})();


/**
 * GUEST AUTHOR ENGINE — OPEN_020
 * Phát hiện thẻ ẩn .guest-author-meta trong bài viết để override
 * author avatar/tên/bio/social links. Fallback về profile chủ blog.
 *
 * @spec 07_Doing_020_Guest_Author_And_Contact_Submission_Specification.md
 */
(function () {
  'use strict';

  document.addEventListener('DOMContentLoaded', function () {
    // Chỉ chạy logic thay thế tác giả trên trang bài viết đơn
    var body = document.body;
    var isPostView = body.classList.contains('view-item') ||
      body.classList.contains('item-view') ||
      !!document.querySelector('.single-post-container');
    if (!isPostView) return;

    var metaEl = document.querySelector('.post-body .guest-author-meta');
    if (!metaEl) return; // Không có guest author → fallback (logic hiện tại chạy)

    var d = metaEl.dataset;
    var name     = d.authorName     || '';
    var role     = d.authorRole     || '';
    var avatar   = d.authorAvatar   || '';
    var bioVi    = d.authorBioVi    || '';
    var bioEn    = d.authorBioEn    || '';
    var website  = d.authorWebsite  || '';
    var facebook = d.authorFacebook || '';
    var twitter  = d.authorTwitter  || '';
    var linkedin = d.authorLinkedin || '';
    var email    = d.authorEmail    || '';

    if (!name) return; // Tên bắt buộc

    // ── 1. Tạo initials avatar fallback ──────────────────────────────
    function makeInitialsAvatar(nameStr) {
      var parts = nameStr.trim().split(/\s+/);
      var initials = parts.length >= 2
        ? (parts[0][0] + parts[parts.length - 1][0]).toUpperCase()
        : nameStr.slice(0, 2).toUpperCase();
      return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(
        '<svg xmlns="http://www.w3.org/2000/svg" width="80" height="80" viewBox="0 0 80 80">' +
        '<rect width="80" height="80" rx="40" fill="#4f7cac"/>' +
        '<text x="50%" y="54%" dominant-baseline="middle" text-anchor="middle" ' +
        'font-family="Be Vietnam Pro,sans-serif" font-size="28" font-weight="700" fill="#fff">' +
        initials + '</text></svg>'
      );
    }
    var avatarSrc = avatar || makeInitialsAvatar(name);

    // ── 2. Override Post Header (.author-meta-inline) ─────────────────
    var inlineEl = document.querySelector('.author-meta-inline');
    if (inlineEl) {
      var smImg = inlineEl.querySelector('.author-avatar-sm');
      if (smImg) { smImg.src = avatarSrc; smImg.alt = name; }
      var nameEl = inlineEl.querySelector('[itemprop="name"]');
      if (nameEl) nameEl.textContent = name;
      if (!inlineEl.querySelector('.author-badge-guest')) {
        var metaText = inlineEl.querySelector('.author-meta-text');
        if (metaText) {
          var badge = document.createElement('span');
          badge.className = 'author-badge-guest';
          badge.setAttribute('data-bilingual', 'true');
          badge.textContent = 'Khách mời | Guest';
          metaText.insertBefore(badge, metaText.firstChild);
        }
      }
    }

    // ── 3. Override Author Bio Box (#post-author-bio-container) ────────
    var container = document.getElementById('post-author-bio-container');
    if (container) {
      var socialLinks = [
        { url: website,  icon: '🌐', label: 'Website'      },
        { url: facebook, icon: '📘', label: 'Facebook'     },
        { url: twitter,  icon: '✖',  label: 'X (Twitter)'  },
        { url: linkedin, icon: '💼', label: 'LinkedIn'      },
        { url: email,    icon: '✉️', label: 'Email'        },
      ];
      var socialHtml = socialLinks
        .filter(function (s) { return s.url; })
        .map(function (s) {
          return '<a class="author-social-btn" href="' + _esc(s.url) + '" ' +
            'target="_blank" rel="noopener noreferrer" ' +
            'title="' + _esc(s.label) + '" aria-label="' + _esc(s.label) + '">' +
            '<span class="social-icon-emoji">' + s.icon + '</span>' +
            '<span class="social-label">' + _esc(s.label) + '</span></a>';
        }).join('');

      container.innerHTML =
        '<img class="author-bio-avatar" alt="' + _esc(name) + '" ' +
             'width="80" height="80" src="' + _esc(avatarSrc) + '"/>' +
        '<div class="author-bio-content">' +
          '<div class="author-bio-label guest-label" data-bilingual="true">' +
            'Về tác giả khách mời | About guest author' +
          '</div>' +
          '<div class="author-bio-name-wrap">' +
            '<h3 class="author-bio-name">' + _esc(name) + '</h3>' +
            (role ? '<span class="author-bio-role">' + _esc(role) + '</span>' : '') +
          '</div>' +
          (bioVi ? '<div class="author-bio-text lang-vi">' + bioVi + '</div>' : '') +
          (bioEn ? '<div class="author-bio-text lang-en">' + bioEn + '</div>' : '') +
          (socialHtml ? '<div class="author-bio-actions author-social-links">' + socialHtml + '</div>' : '') +
        '</div>';

      container.classList.add('is-guest-author');
    }

    // ── 4. Schema.org JSON-LD Person ──────────────────────────────────
    _updateJsonLdPerson({
      name: name, url: website, image: avatar,
      description: bioEn || bioVi,
      sameAs: [facebook, twitter, linkedin].filter(Boolean),
    });

    // ── 5. Guest Post Callout cuối bài ────────────────────────────────
    var globalConfig = document.getElementById('HTML88');
    if (globalConfig) {
      var calloutConfig = globalConfig.querySelector('.post-guest-callout-config');
      var calloutEl     = document.querySelector('.post-guest-callout');
      if (calloutConfig && calloutEl) {
        var show = calloutConfig.style.display && calloutConfig.style.display !== 'none';
        if (show) {
          calloutEl.style.display = 'block';
          if (!calloutEl.children.length) calloutEl.innerHTML = calloutConfig.innerHTML;
        }
      }
    }
  }); // END DOMContentLoaded guest author

  // ── 6. Render CTA buttons từ #HTML88 config (mọi trang) ──────────────
  document.addEventListener('DOMContentLoaded', function () {
    var globalConfig = document.getElementById('HTML88');
    if (!globalConfig) return;

    // Nút btn-guest-hero trên Banner Hero
    var configBtn = globalConfig.querySelector('.btn-guest-hero-config');
    if (configBtn && configBtn.style.display !== 'none') {
      var ctaArea = document.querySelector('.profile-cta-area');
      if (ctaArea && !ctaArea.querySelector('.btn-guest-hero')) {
        var btn = document.createElement('a');
        btn.className = 'btn-guest-hero';
        btn.href = configBtn.getAttribute('href') || '/p/lien-he.html';
        btn.setAttribute('data-bilingual', 'true');
        var span = configBtn.querySelector('[data-bilingual]');
      var rawLabel = span ? span.textContent.trim() : '✍️ Viết cùng Trà Đá | ✍️ Write with us';
      var lang = (typeof localStorage !== 'undefined' && localStorage.getItem('user_lang')) || 'vi';
      btn.setAttribute('data-bilingual', 'true');
      btn.setAttribute('data-raw-label', rawLabel);
      btn.textContent = window.parseBilingualText ? window.parseBilingualText(rawLabel, lang) : rawLabel;
        ctaArea.appendChild(btn);
      }
    }

    // Sidebar Guest Card
    var cardConfig = globalConfig.querySelector('.sidebar-guest-card-config');
    if (cardConfig && cardConfig.style.display !== 'none') {
      var sidebarWrapper = document.querySelector('.sidebar-wrapper');
      if (sidebarWrapper && !sidebarWrapper.querySelector('.sidebar-guest-card')) {
        var card = document.createElement('div');
        card.className = 'sidebar-guest-card';
        card.innerHTML = cardConfig.innerHTML;
        sidebarWrapper.appendChild(card);
      }
    }
  });

  // ── Utils ─────────────────────────────────────────────────────────────
  function _esc(str) {
    return String(str || '')
      .replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function _updateJsonLdPerson(p) {
    try {
      var node = { '@context': 'https://schema.org', '@type': 'Person', 'name': p.name };
      if (p.url)         node['url']         = p.url;
      if (p.image)       node['image']       = p.image;
      if (p.description) node['description'] = p.description;
      if (p.sameAs && p.sameAs.length) node['sameAs'] = p.sameAs;

      var scripts = document.querySelectorAll('script[type="application/ld+json"]');
      var target  = null;
      for (var i = 0; i < scripts.length; i++) {
        try {
          var parsed = JSON.parse(scripts[i].textContent);
          if (parsed['@type'] === 'BlogPosting') {
            parsed.author = node;
            scripts[i].textContent = JSON.stringify(parsed);
            return;
          }
          if (parsed['@type'] === 'Person') { target = scripts[i]; }
        } catch (_) {}
      }
      if (target) { target.textContent = JSON.stringify(node); return; }
      var s = document.createElement('script');
      s.type = 'application/ld+json';
      s.textContent = JSON.stringify(node);
      document.head.appendChild(s);
    } catch (_) {}
  }

})();


/**
 * CONTACT PAGE MODULE — OPEN_020
 * Logic tương tác trang Liên Hệ & Gửi Bài Viết (/p/lien-he.html)
 * - Tab toggle (Guest Post / General Contact)
 * - Client-side validation
 * - Honeypot anti-spam
 * - Multi-adapter submit (blogger / gas / formsubmit)
 * - UX: spinner, toast, auto-reset
 *
 * @spec 07_Doing_020_Guest_Author_And_Contact_Submission_Specification.md
 */
(function () {
  'use strict';

  // Chỉ khởi động khi có #editorial-contact-app
  document.addEventListener('DOMContentLoaded', function () {
    var app = document.getElementById('editorial-contact-app');
    if (!app) return;
    initContactPage(app);
  });

  function initContactPage(app) {
    var cfg = window.__CONTACT_CONFIG || {};

    // ── 0. Thay thế email hiển thị động ─────────────────────────────────
    var adminEmail = cfg.adminEmail || 'tradabanthesu@gmail.com';
    var emailLink = app.querySelector('.contact-direct-link');
    if (emailLink) {
      emailLink.href = 'mailto:' + adminEmail;
      emailLink.textContent = '✉️ ' + adminEmail;
    }

    // ── 1. Tab Toggle ───────────────────────────────────────────────────
    var tabBtns   = app.querySelectorAll('.contact-tab-btn');
    var formGuest = app.querySelector('#contact-form-guest');
    var formGeneral = app.querySelector('#contact-form-general');

    tabBtns.forEach(function (btn) {
      btn.addEventListener('click', function () {
        tabBtns.forEach(function (b) {
          b.classList.remove('active');
          b.setAttribute('aria-selected', 'false');
        });
        btn.classList.add('active');
        btn.setAttribute('aria-selected', 'true');

        var target = btn.dataset.tab;
        if (formGuest)   formGuest.style.display   = (target === 'guest')   ? 'block' : 'none';
        if (formGeneral) formGeneral.style.display  = (target === 'general') ? 'block' : 'none';
      });
    });

    // ── 2. Submit handler của form Guest Post ──────────────────────────
    if (formGuest) {
      formGuest.addEventListener('submit', function (e) {
        e.preventDefault();
        _handleSubmit(formGuest, 'guest_post');
      });
    }

    // ── 3. Submit handler của form General Contact ───────────────────
    if (formGeneral) {
      formGeneral.addEventListener('submit', function (e) {
        e.preventDefault();
        _handleSubmit(formGeneral, 'general');
      });
    }
  }

  // ─────────────────────────────────────────────────────────────────────
  function _handleSubmit(form, type) {
    // Honeypot check
    var honey = form.querySelector('input[name="_honey"]');
    if (honey && honey.value) {
      // Bot detected — giả vờ thành công
      _showToast('success', form);
      form.reset();
      return;
    }

    // Validation
    if (!_validate(form)) return;

    // Thu thập dữ liệu
    var data = _collectData(form, type);

    // Chọn adapter
    var cfg = window.__CONTACT_CONFIG || {};
    var adapter = cfg.adapter || 'blogger';

    _setLoading(form, true);

    if (adapter === 'gas' && cfg.gasWebhookUrl) {
      _submitGAS(cfg.gasWebhookUrl, data, form);
    } else if (adapter === 'formsubmit' && cfg.adminEmail) {
      _submitFormSubmit(cfg.adminEmail, data, form);
    } else {
      // Mặc định: Blogger native
      _submitBlogger(data, form);
    }
  }

  // ── Validation ──────────────────────────────────────────────────
  function _validate(form) {
    var valid = true;
    var required = form.querySelectorAll('[required]');
    required.forEach(function (field) {
      _clearError(field);
      var val = field.value.trim();
      if (!val) {
        _showError(field, 'Trường này không được để trống.');
        valid = false;
      } else if (field.type === 'email' && !_isValidEmail(val)) {
        _showError(field, 'Địa chỉ email không hợp lệ.');
        valid = false;
      }
    });
    if (!valid) {
      // Scroll đến lỗi đầu tiên
      var firstErr = form.querySelector('.contact-field-error');
      if (firstErr) firstErr.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
    return valid;
  }

  function _isValidEmail(email) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  }

  function _showError(field, msg) {
    field.classList.add('is-invalid');
    var err = field.parentNode.querySelector('.contact-field-error');
    if (!err) {
      err = document.createElement('span');
      err.className = 'contact-field-error';
      field.parentNode.appendChild(err);
    }
    err.textContent = msg;
  }

  function _clearError(field) {
    field.classList.remove('is-invalid');
    var err = field.parentNode.querySelector('.contact-field-error');
    if (err) err.remove();
  }

  // ── Thu thập dữ liệu từ form ────────────────────────────────────
  function _collectData(form, type) {
    var data = { type: type };
    var fields = form.querySelectorAll('input:not([type=hidden]):not([name=_honey]), textarea, select');
    fields.forEach(function (f) {
      if (f.name) data[f.name] = f.value.trim();
    });
    return data;
  }

  // ── Adapter A: Google Apps Script Webhook ────────────────────────
  function _submitGAS(url, data, form) {
    var params = new URLSearchParams();
    Object.keys(data).forEach(function (k) { params.append(k, data[k]); });

    fetch(url, {
      method: 'POST',
      mode: 'no-cors', // GAS yêu cầu no-cors khi gọi từ domain khác
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: params.toString(),
    })
      .then(function () {
        _setLoading(form, false);
        _showToast('success', form);
        form.reset();
      })
      .catch(function () {
        _setLoading(form, false);
        _showToast('error', form);
      });
  }

  // ── Adapter B: Blogger Native ContactForm (Proxy Method) ─────────
  function _submitBlogger(data, form) {
    var isGuest = data.type === 'guest_post';
    var lines = [];
    if (isGuest) {
      lines.push('[Gửi Bài Viết]');
      if (data.post_title)   lines.push('✔ Tiêu đề: '    + data.post_title);
      if (data.content)      lines.push('✔ Bản thảo/Link:\n' + data.content);
      if (data.author_bio)   lines.push('✔ Bio: '           + data.author_bio);
      if (data.author_avatar) lines.push('✔ Avatar URL: '   + data.author_avatar);
      if (data.author_social) lines.push('✔ Social/Web: '   + data.author_social);
    } else {
      lines.push('[Liên Hệ Thông Thường]');
      if (data.subject) lines.push('✔ Chủ đề: ' + data.subject);
      if (data.message) lines.push('✔ Nội dung:\n' + data.message);
    }
    var messageStr = lines.join('\n');
    var nameStr  = data.author_name || data.name || 'Anonymous';
    var emailStr = data.author_email || data.email || 'no-reply@blogger.com';

    // Tìm các trường ẩn của ContactForm1
    var nativeName = document.getElementById('ContactForm1_contact-form-name');
    var nativeEmail = document.getElementById('ContactForm1_contact-form-email');
    var nativeMessage = document.getElementById('ContactForm1_contact-form-email-message');
    var nativeSubmit = document.getElementById('ContactForm1_contact-form-submit');
    var nativeSuccess = document.getElementById('ContactForm1_contact-form-success-message');
    var nativeError = document.getElementById('ContactForm1_contact-form-error-message');

    if (!nativeName || !nativeSubmit) {
      alert('Không tìm thấy tiện ích ContactForm gốc của Blogger. Hãy đảm bảo bạn đã cài đặt mã mới nhất.');
      _setLoading(form, false);
      return;
    }

    // Gán dữ liệu
    nativeName.value = nameStr;
    nativeEmail.value = emailStr;
    nativeMessage.value = messageStr;

    // Reset thông báo cũ
    if (nativeSuccess) nativeSuccess.innerHTML = '';
    if (nativeError) nativeError.innerHTML = '';

    // Bấm nút gửi ảo
    nativeSubmit.click();

    // Dùng MutationObserver để theo dõi phản hồi từ server Blogger
    var observer = new MutationObserver(function (mutations) {
      mutations.forEach(function (mutation) {
        if (mutation.target.innerHTML.trim() !== '') {
          observer.disconnect();
          _setLoading(form, false);
          if (mutation.target === nativeSuccess) {
            _showToast('success', form);
            form.reset();
          } else {
            _showToast('error', form);
          }
        }
      });
    });

    if (nativeSuccess) observer.observe(nativeSuccess, { childList: true, characterData: true, subtree: true });
    if (nativeError) observer.observe(nativeError, { childList: true, characterData: true, subtree: true });

    // Timeout phòng hờ (10s)
    setTimeout(function() {
      observer.disconnect();
      _setLoading(form, false);
    }, 10000);
  }

  // ── Adapter C: FormSubmit ──────────────────────────────────────
  function _submitFormSubmit(adminEmail, data, form) {
    var url = 'https://formsubmit.co/ajax/' + encodeURIComponent(adminEmail);
    var payload = {
      _subject: data.type === 'guest_post'
        ? '[Gửi Bài] ' + (data.post_title || data.author_name)
        : '[Liên Hệ] ' + (data.name || data.author_name),
      _captcha: 'false'
    };
    Object.keys(data).forEach(function (k) { payload[k] = data[k]; });

    fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json'
      },
      body: JSON.stringify(payload),
    })
      .then(function (r) { return r.json(); })
      .then(function (res) {
        _setLoading(form, false);
        console.log('FormSubmit response:', res);
        if (res && (res.success === 'true' || res.success === true || res.success === 'false' /* some edge cases? no wait */)) {
          // Note: sometimes formsubmit returns success=false if not activated?
          if (res.success === 'false' && res.message && res.message.includes('activate')) {
             alert('FormSubmit yêu cầu kích hoạt. Vui lòng kiểm tra email của bạn để kích hoạt form trước!');
             return;
          }
          if (res.success === 'true' || res.success === true) {
            _showToast('success', form);
            form.reset();
          } else {
            _showToast('error', form);
          }
        } else {
          _showToast('error', form);
        }
      })
      .catch(function (err) {
        console.error('FormSubmit error:', err);
        _setLoading(form, false);
        _showToast('error', form);
      });
  }

  // ── UX Helpers ──────────────────────────────────────────────────
  function _setLoading(form, isLoading) {
    var submitBtn = form.querySelector('[type="submit"]');
    if (!submitBtn) return;
    submitBtn.disabled = isLoading;
    if (isLoading) {
      submitBtn.dataset.originalText = submitBtn.textContent;
      submitBtn.innerHTML = '<span class="contact-spinner"></span> Đang gửi...';
    } else {
      submitBtn.textContent = submitBtn.dataset.originalText || 'Gửi';
    }
  }

  function _showToast(type, form) {
    // Tìm hoặc tạo toast container
    var app = document.getElementById('editorial-contact-app');
    var toast = (app || document).querySelector('.contact-toast');
    if (!toast) {
      toast = document.createElement('div');
      toast.className = 'contact-toast';
      if (app) app.insertBefore(toast, app.firstChild);
      else document.body.appendChild(toast);
    }

    toast.className = 'contact-toast contact-toast--' + type + ' contact-toast--visible';
    toast.textContent = type === 'success'
      ? 'Cảm ơn bạn! Bài viết đã được gửi tới hòm thư ban biên tập. Chúng mình sẽ phản hồi qua email trong vòng 24–48 giờ.'
      : 'Có lỗi xảy ra. Vui lòng thử lại hoặc liên hệ trực tiếp qua email.';

    // Scroll lên đầu form
    toast.scrollIntoView({ behavior: 'smooth', block: 'center' });

    // Tự ẩn sau 8 giây
    clearTimeout(toast._hideTimer);
    toast._hideTimer = setTimeout(function () {
      toast.classList.remove('contact-toast--visible');
    }, 8000);
  }

})();

  //
